use std::collections::{BTreeMap, HashMap};
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, Write};
use std::path::{Path, PathBuf};

use clap::{Parser, ValueEnum};
use flate2::read::GzDecoder;
use regex::Regex;

mod args;
mod log_entry;
mod filters;
mod tables;
mod output;

use args::Args;
use log_entry::LogEntry;
use filters::Filters;
use output::OutputMode;
use tables::TablePrinter;

fn main() {
    let args = Args::parse();

    // Determine color mode
    let use_color = match args.color {
        args::ColorMode::Auto => atty::is(atty::Stream::Stdout),
        args::ColorMode::Yes => true,
        args::ColorMode::No => false,
    };

    // Find log files
    let paths = if args.files.is_empty() {
        let default = PathBuf::from("/var/log/nginx");
        if default.exists() {
            vec![default]
        } else {
            eprintln!("No nginx log found at default location, do you have nginx set up?");
            eprintln!("If necessary, provide the path to the log file(s) as argument.");
            eprintln!("More information with 'rhit --help'.");
            eprintln!("Error: PathNotFound(\"/var/log/nginx\")");
            std::process::exit(0);
        }
    } else {
        args.files.clone()
    };

    // Collect all log files
    let log_files = collect_log_files(&paths, args.no_name_check);

    if log_files.is_empty() {
        eprintln!("No log files found");
        std::process::exit(1);
    }

    // Determine display path (for "I've read N files in X")
    let display_path = if args.files.is_empty() {
        "/var/log/nginx".to_string()
    } else if paths.len() == 1 {
        paths[0].display().to_string()
    } else {
        paths[0].display().to_string()
    };

    let n_files = log_files.len();

    // Set up output mode
    let output_mode = args.output.unwrap_or(OutputMode::Tables);

    // Parse filters
    let filters = Filters::from_args(&args);

    // Parse fields
    let fields = parse_fields(&args.fields);

    // Read and process log entries
    let (entries, raw_lines_per_file) = read_log_files(
        &log_files,
        &filters,
        n_files,
        output_mode == OutputMode::Raw,
        args.silent_load,
        use_color,
    );

    // Print loading summary
    if !args.silent_load {
        eprint!("\x1b[2K\x1b[G");
    }

    match output_mode {
        OutputMode::Raw => {
            for raw in raw_lines_per_file {
                print!("{}", raw);
            }
            // Print file summary to stderr
            print_file_summary(n_files, &display_path, &entries);
        }
        OutputMode::Csv => {
            print_csv(&entries);
            print_file_summary(n_files, &display_path, &entries);
        }
        OutputMode::Json => {
            print_json(&entries);
            print_file_summary(n_files, &display_path, &entries);
        }
        OutputMode::Tables => {
            print_file_summary(n_files, &display_path, &entries);
            let printer = TablePrinter::new(&args, &filters, use_color);
            printer.print_all(&entries, &fields);
        }
    }
}

fn collect_log_files(paths: &[PathBuf], no_name_check: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for path in paths {
        if path.is_file() {
            if no_name_check || is_log_file(path) {
                files.push(path.clone());
            }
        } else if path.is_dir() {
            // Collect log files from directory (sorted)
            let mut dir_files: Vec<PathBuf> = fs::read_dir(path)
                .into_iter()
                .flatten()
                .flatten()
                .map(|e| e.path())
                .filter(|p| p.is_file() && (no_name_check || is_log_file(p)))
                .collect();
            dir_files.sort();
            files.extend(dir_files);
        }
    }
    files
}

fn is_log_file(path: &Path) -> bool {
    let name = path.file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("");

    // Accept access.log, access.log.1, access.log.2.gz, etc.
    name.starts_with("access") || 
    (name.contains(".log") && !name.starts_with('.'))
}

fn read_log_files(
    files: &[PathBuf],
    filters: &Filters,
    n_files: usize,
    collect_raw: bool,
    silent: bool,
    use_color: bool,
) -> (Vec<LogEntry>, Vec<String>) {
    let mut entries = Vec::new();
    let mut raw_lines = Vec::new();

    for (i, file) in files.iter().enumerate() {
        if !silent {
            print_progress(i, n_files, use_color);
        }

        let result = if file.extension().and_then(|e| e.to_str()) == Some("gz") {
            read_gz_file(file, filters, collect_raw)
        } else {
            read_plain_file(file, filters, collect_raw)
        };

        if let Ok((file_entries, file_raw)) = result {
            entries.extend(file_entries);
            if collect_raw {
                raw_lines.push(file_raw);
            }
        }
    }

    if !silent {
        print_progress(n_files, n_files, use_color);
        eprint!("\x1b[1b");
    }

    (entries, raw_lines)
}

fn print_progress(current: usize, total: usize, use_color: bool) {
    let width = 40;
    let filled = if total > 0 { current * width / total } else { 0 };

    eprint!("\x1b7\x1b[2K{:3} / {} ", current, total);

    if use_color {
        eprint!("\x1b[48;5;5m\x1b[38;5;11m");
    }

    for i in 0..width {
        if i < filled {
            eprint!("█");
        } else {
            eprint!(" ");
        }
    }

    if use_color {
        eprint!("\x1b[49m\x1b[39m");
    }

    eprint!("\x1b8");
}

fn read_plain_file(path: &Path, filters: &Filters, collect_raw: bool) -> io::Result<(Vec<LogEntry>, String)> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    read_lines(reader, filters, collect_raw)
}

fn read_gz_file(path: &Path, filters: &Filters, collect_raw: bool) -> io::Result<(Vec<LogEntry>, String)> {
    let file = File::open(path)?;
    let gz = GzDecoder::new(file);
    let reader = BufReader::new(gz);
    read_lines(reader, filters, collect_raw)
}

fn read_lines<R: BufRead>(reader: R, filters: &Filters, collect_raw: bool) -> io::Result<(Vec<LogEntry>, String)> {
    let mut entries = Vec::new();
    let mut raw = String::new();

    for line in reader.lines() {
        let line = line?;
        if line.is_empty() {
            continue;
        }

        if let Some(entry) = LogEntry::parse(&line) {
            if filters.matches(&entry) {
                if collect_raw {
                    raw.push_str(&line);
                    raw.push('\n');
                }
                entries.push(entry);
            }
        }
    }

    Ok((entries, raw))
}

fn print_file_summary(n_files: usize, path: &str, entries: &[LogEntry]) {
    let file_word = if n_files == 1 { "file" } else { "files" };
    print!("I've read {} {} in \"{}\"\n", n_files, file_word, path);
}

fn print_csv(entries: &[LogEntry]) {
    println!("date,time,remote address,method,path,status,bytes sent,referer");
    for e in entries {
        println!(
            "{},{},{},{},\"{}\",{},{},\"{}\"",
            e.date_str,
            e.time_str,
            e.remote_addr,
            e.method,
            e.path,
            e.status,
            e.bytes_sent,
            e.referer,
        );
    }
}

fn print_json(entries: &[LogEntry]) {
    println!("[");
    for (i, e) in entries.iter().enumerate() {
        let comma = if i < entries.len() - 1 { "," } else { "" };
        println!(
            "  {{\n    \"date\": \"{}\",\n    \"time\": \"{}\",\n    \"remote_addr\": \"{}\",\n    \"method\": \"{}\",\n    \"path\": \"{}\",\n    \"status\": \"{}\",\n    \"bytes_sent\": {},\n    \"referer\": \"{}\"\n  }}{}",
            e.date_str,
            e.time_str,
            e.remote_addr,
            e.method,
            e.path,
            e.status,
            e.bytes_sent,
            e.referer,
            comma,
        );
    }
    println!("]");
}

#[derive(Debug, Clone, PartialEq)]
pub enum Field {
    Date,
    Time,
    Method,
    Status,
    Ip,
    Referer,
    Path,
}

fn parse_fields(spec: &Option<String>) -> Vec<Field> {
    let default = vec![Field::Date, Field::Status, Field::Referer, Field::Path];
    let all = vec![Field::Date, Field::Time, Field::Method, Field::Status, Field::Ip, Field::Referer, Field::Path];

    let spec = match spec {
        None => return default,
        Some(s) => s.clone(),
    };

    // Parse the field spec
    let mut base = default.clone();
    let mut remaining = spec.as_str();

    // Check if starts with a field name (no + or -)
    let first_op_pos = remaining.find(|c| c == '+' || c == '-');

    if let Some(pos) = first_op_pos {
        if pos == 0 {
            // Starts with + or -, use default as base
        } else {
            // Has a base spec first
            let base_spec = &remaining[..pos];
            if base_spec == "all" || base_spec == "a" {
                base = all.clone();
            } else {
                base = parse_single_field_list(base_spec);
            }
            remaining = &remaining[pos..];
        }
    } else {
        // No + or -, it's just a list
        if spec == "all" || spec == "a" {
            return all;
        }
        return parse_single_field_list(&spec);
    }

    // Apply +/- operations
    let mut i = 0;
    let chars: Vec<char> = remaining.chars().collect();
    while i < chars.len() {
        let op = chars[i];
        i += 1;
        let start = i;
        while i < chars.len() && chars[i] != '+' && chars[i] != '-' {
            i += 1;
        }
        let field_name: String = chars[start..i].iter().collect();
        let field = parse_field_name(&field_name);

        match op {
            '+' => {
                if let Some(f) = field {
                    // Remove from base if already present, then add at end
                    base.retain(|x| x != &f);
                    base.push(f);
                }
            }
            '-' => {
                if let Some(f) = field {
                    base.retain(|x| x != &f);
                }
            }
            _ => {}
        }
    }

    base
}

fn parse_single_field_list(s: &str) -> Vec<Field> {
    let mut result = Vec::new();
    for part in s.split(',') {
        let part = part.trim();
        if let Some(f) = parse_field_name(part) {
            if !result.contains(&f) {
                result.push(f);
            }
        }
    }
    result
}

fn parse_field_name(s: &str) -> Option<Field> {
    match s.to_lowercase().as_str() {
        "date" | "d" => Some(Field::Date),
        "time" | "t" => Some(Field::Time), // Note: 't' is also used for --time filter
        "method" | "m" => Some(Field::Method),
        "status" | "s" => Some(Field::Status),
        "ip" | "i" => Some(Field::Ip),
        "ref" | "referer" | "referrer" | "r" => Some(Field::Referer),
        "path" | "p" => Some(Field::Path),
        _ => None,
    }
}

