fn collect_log_files(paths: &[PathBuf], no_name_check: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for path in paths {
        if path.is_file() {
            if no_name_check || is_log_file(path) {
                files.push(path.clone());
            }
        } else if path.is_dir() {
            // Collect log files from directory (sorted)
            let mut dir_files: Vec<PathBuf> = fs::read_dir(path)
                .into_iter()
                .flatten()
                .flatten()
                .map(|e| e.path())
                .filter(|p| p.is_file() && (no_name_check || is_log_file(p)))
                .collect();
            dir_files.sort();
            files.extend(dir_files);
        }
    }
    files
}

fn is_log_file(path: &Path) -> bool {
    let name = path.file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("");

    // Accept access.log, access.log.1, access.log.2.gz, etc.
    name.starts_with("access") || 
    (name.contains(".log") && !name.starts_with('.'))
}

fn read_log_files(
    files: &[PathBuf],
    filters: &Filters,
    n_files: usize,
    collect_raw: bool,
    silent: bool,
    use_color: bool,
) -> (Vec<LogEntry>, Vec<String>) {
    let mut entries = Vec::new();
    let mut raw_lines = Vec::new();

    for (i, file) in files.iter().enumerate() {
        if !silent {
            print_progress(i, n_files, use_color);
        }

        let result = if file.extension().and_then(|e| e.to_str()) == Some("gz") {
            read_gz_file(file, filters, collect_raw)
        } else {
            read_plain_file(file, filters, collect_raw)
        };

        if let Ok((file_entries, file_raw)) = result {
            entries.extend(file_entries);
            if collect_raw {
                raw_lines.push(file_raw);
            }
        }
    }

    if !silent {
        print_progress(n_files, n_files, use_color);
        eprint!("\x1b[1b");
    }

    (entries, raw_lines)
}

fn print_progress(current: usize, total: usize, use_color: bool) {
    let width = 40;
    let filled = if total > 0 { current * width / total } else { 0 };

    eprint!("\x1b7\x1b[2K{:3} / {} ", current, total);

    if use_color {
        eprint!("\x1b[48;5;5m\x1b[38;5;11m");
    }

    for i in 0..width {
        if i < filled {
            eprint!("█");
        } else {
            eprint!(" ");
        }
    }

    if use_color {
        eprint!("\x1b[49m\x1b[39m");
    }

    eprint!("\x1b8");
}

fn read_plain_file(path: &Path, filters: &Filters, collect_raw: bool) -> io::Result<(Vec<LogEntry>, String)> {
