    let reader = BufReader::new(file);
    read_lines(reader, filters, collect_raw)
}

fn read_gz_file(path: &Path, filters: &Filters, collect_raw: bool) -> io::Result<(Vec<LogEntry>, String)> {
    let file = File::open(path)?;
    let gz = GzDecoder::new(file);
    let reader = BufReader::new(gz);
    read_lines(reader, filters, collect_raw)
}

fn read_lines<R: BufRead>(reader: R, filters: &Filters, collect_raw: bool) -> io::Result<(Vec<LogEntry>, String)> {
    let mut entries = Vec::new();
    let mut raw = String::new();

    for line in reader.lines() {
        let line = line?;
        if line.is_empty() {
            continue;
        }

        if let Some(entry) = LogEntry::parse(&line) {
            if filters.matches(&entry) {
                if collect_raw {
                    raw.push_str(&line);
                    raw.push('\n');
                }
                entries.push(entry);
            }
        }
    }

    Ok((entries, raw))
}

