#[derive(Debug, Clone, PartialEq)]
pub enum Field {
    Date,
    Time,
    Method,
    Status,
    Ip,
    Referer,
    Path,
}

fn parse_fields(spec: &Option<String>) -> Vec<Field> {
    let default = vec![Field::Date, Field::Status, Field::Referer, Field::Path];
    let all = vec![Field::Date, Field::Time, Field::Method, Field::Status, Field::Ip, Field::Referer, Field::Path];

    let spec = match spec {
        None => return default,
        Some(s) => s.clone(),
    };

    // Parse the field spec
    let mut base = default.clone();
    let mut remaining = spec.as_str();

    // Check if starts with a field name (no + or -)
    let first_op_pos = remaining.find(|c| c == '+' || c == '-');

    if let Some(pos) = first_op_pos {
        if pos == 0 {
            // Starts with + or -, use default as base
        } else {
            // Has a base spec first
            let base_spec = &remaining[..pos];
            if base_spec == "all" || base_spec == "a" {
                base = all.clone();
            } else {
                base = parse_single_field_list(base_spec);
            }
            remaining = &remaining[pos..];
        }
    } else {
        // No + or -, it's just a list
        if spec == "all" || spec == "a" {
            return all;
        }
        return parse_single_field_list(&spec);
    }

    // Apply +/- operations
    let mut i = 0;
    let chars: Vec<char> = remaining.chars().collect();
    while i < chars.len() {
        let op = chars[i];
        i += 1;
        let start = i;
        while i < chars.len() && chars[i] != '+' && chars[i] != '-' {
            i += 1;
        }
        let field_name: String = chars[start..i].iter().collect();
        let field = parse_field_name(&field_name);

        match op {
            '+' => {
                if let Some(f) = field {
                    // Remove from base if already present, then add at end
                    base.retain(|x| x != &f);
                    base.push(f);
                }
            }
            '-' => {
                if let Some(f) = field {
                    base.retain(|x| x != &f);
                }
            }
            _ => {}
        }
    }

    base
}

fn parse_single_field_list(s: &str) -> Vec<Field> {
    let mut result = Vec::new();
    for part in s.split(',') {
        let part = part.trim();
        if let Some(f) = parse_field_name(part) {
            if !result.contains(&f) {
                result.push(f);
            }
        }
    }
    result
}

fn parse_field_name(s: &str) -> Option<Field> {
    match s.to_lowercase().as_str() {
        "date" | "d" => Some(Field::Date),
        "time" | "t" => Some(Field::Time), // Note: 't' is also used for --time filter
        "method" | "m" => Some(Field::Method),
        "status" | "s" => Some(Field::Status),
        "ip" | "i" => Some(Field::Ip),
        "ref" | "referer" | "referrer" | "r" => Some(Field::Referer),
        "path" | "p" => Some(Field::Path),
        _ => None,
    }
}

