use chrono::{NaiveDate, NaiveDateTime, NaiveTime};

#[derive(Debug, Clone)]
pub struct LogEntry {
    pub date_str: String,    // YYYY/MM/DD
    pub time_str: String,    // HH:MM:SS
    pub remote_addr: String,
    pub method: String,
    pub path: String,
    pub status: u16,
    pub bytes_sent: u64,
    pub referer: String,
    pub date: NaiveDate,
    pub time: NaiveTime,
    pub datetime: NaiveDateTime,
    pub raw_line: String,
}

impl LogEntry {
    pub fn parse(line: &str) -> Option<Self> {
        // Nginx default log format:
        // $remote_addr - $remote_user [$time_local] "$request" $status $body_bytes_sent "$http_referer" "$http_user_agent"
        // Example: 178.133.125.122 - - [21/Jan/2021:05:49:52 +0000] "HEAD /broot/... HTTP/1.1" 200 0 "-" "Mozilla/4.0"

        let parts: Vec<&str> = line.splitn(2, " - ").collect();
        if parts.len() < 2 {
            return None;
        }

        let remote_addr = parts[0].trim().to_string();
        let rest = parts[1];

        // Skip "- [" part
        let bracket_pos = rest.find('[')? + 1;
        let bracket_end = rest.find(']')?;
        let time_part = &rest[bracket_pos..bracket_end];

        // Parse time: "21/Jan/2021:05:49:52 +0000"
        let (date, time) = parse_datetime(time_part)?;
        let date_str = format!("{}/{:02}/{:02}", date.year_ce().1, date.month(), date.day());
        let time_str = format!("{:02}:{:02}:{:02}", time.hour(), time.minute(), time.second());

        let rest = &rest[bracket_end + 1..].trim_start();
        if !rest.starts_with('"') {
            return None;
        }
        let request_end = rest[1..].find('"')? + 1;
        let request = &rest[1..request_end];
        let rest = &rest[request_end + 1..].trim_start();

        // Parse method, path from request
        let (method, path) = parse_request(request)?;

        // Parse status and bytes_sent
        let parts: Vec<&str> = rest.splitn(3, ' ').collect();
        if parts.len() < 2 {
            return None;
        }
        let status: u16 = parts[0].parse().ok()?;
        let bytes_sent: u64 = parts[1].parse().unwrap_or(0);

        // Parse referer
        let referer = if parts.len() > 2 {
            let rest = parts[2].trim_start();
            if rest.starts_with('"') {
                let end = rest[1..].find('"').unwrap_or(rest.len() - 1) + 1;
                rest[1..end].to_string()
            } else {
                "-".to_string()
            }
        } else {
            "-".to_string()
        };

        let datetime = date.and_time(time);

        Some(LogEntry {
            date_str,
            time_str,
            remote_addr,
            method,
            path,
            status,
            bytes_sent,
            referer,
            date,
            time,
            datetime,
            raw_line: line.to_string(),
        })
    }
}

fn parse_datetime(s: &str) -> Option<(NaiveDate, NaiveTime)> {
    // Format: "21/Jan/2021:05:49:52 +0000"
    let parts: Vec<&str> = s.splitn(2, ':').collect();
    if parts.len() < 2 {
        return None;
    }

    let date_part = parts[0]; // "21/Jan/2021"
    let time_and_tz = parts[1..].join(":"); // "05:49:52 +0000"

    let time_str = time_and_tz.split_whitespace().next()?;

    let date_parts: Vec<&str> = date_part.split('/').collect();
    if date_parts.len() != 3 {
        return None;
    }

    let day: u32 = date_parts[0].parse().ok()?;
    let month = month_to_num(date_parts[1])?;
    let year: i32 = date_parts[2].parse().ok()?;

    let date = NaiveDate::from_ymd_opt(year, month, day)?;

    let time_parts: Vec<&str> = time_str.split(':').collect();
    if time_parts.len() != 3 {
        return None;
    }

    let hour: u32 = time_parts[0].parse().ok()?;
    let minute: u32 = time_parts[1].parse().ok()?;
    let second: u32 = time_parts[2].parse().ok()?;

    let time = NaiveTime::from_hms_opt(hour, minute, second)?;

    Some((date, time))
}

fn month_to_num(m: &str) -> Option<u32> {
    match m {
        "Jan" => Some(1),
        "Feb" => Some(2),
        "Mar" => Some(3),
        "Apr" => Some(4),
        "May" => Some(5),
        "Jun" => Some(6),
        "Jul" => Some(7),
        "Aug" => Some(8),
        "Sep" => Some(9),
        "Oct" => Some(10),
        "Nov" => Some(11),
        "Dec" => Some(12),
        _ => None,
    }
}

fn parse_request(request: &str) -> Option<(String, String)> {
    // "GET /path HTTP/1.1" or "GET /path"
    let parts: Vec<&str> = request.splitn(3, ' ').collect();
    if parts.len() < 2 {
        return None;
    }

    let method = parts[0].to_string();
    let path = parts[1].to_string();

    Some((method, path))
}
EOF

