fn parse_datetime(s: &str) -> Option<(NaiveDate, NaiveTime)> {
    // Format: "21/Jan/2021:05:49:52 +0000"
    let parts: Vec<&str> = s.splitn(2, ':').collect();
    if parts.len() < 2 {
        return None;
    }

    let date_part = parts[0]; // "21/Jan/2021"
    let time_and_tz = parts[1..].join(":"); // "05:49:52 +0000"

    let time_str = time_and_tz.split_whitespace().next()?;

    let date_parts: Vec<&str> = date_part.split('/').collect();
