// Date filter: parses date range specifications
pub struct DateFilter {
    spec: String,
    filter_type: DateFilterType,
}

enum DateFilterType {
    Exact(NaiveDate, NaiveDate),  // from, to (inclusive)
    Negate(Box<DateFilter>),
    After(NaiveDate),
    Before(NaiveDate),
}

impl DateFilter {
    pub fn parse(s: &str) -> Self {
        let s = s.trim();

        // Negation
        if s.starts_with('!') {
            let inner = DateFilter::parse(&s[1..]);
            return DateFilter {
                spec: s.to_string(),
                filter_type: DateFilterType::Negate(Box::new(inner)),
            };
        }

        // After: >date
        if s.starts_with('>') {
            let date = parse_date_range_end(&s[1..]);
            return DateFilter {
                spec: s.to_string(),
                filter_type: DateFilterType::After(date.0),
            };
        }

        // Before: <date
        if s.starts_with('<') {
            let date = parse_date_range_end(&s[1..]);
            return DateFilter {
                spec: s.to_string(),
                filter_type: DateFilterType::Before(date.1),
            };
        }

        // Range: date1-date2 (but be careful about dates like 2021/01/01-2021/01/02)
        // A date range has T separator or has two date patterns separated by -
        // We need to check if it's a range by looking for the pattern
        if let Some(range) = parse_date_range(s) {
            return DateFilter {
                spec: s.to_string(),
                filter_type: DateFilterType::Exact(range.0, range.1),
            };
        }

        // Single date/year/month
        let (from, to) = parse_date_range_end(s);
        DateFilter {
            spec: s.to_string(),
            filter_type: DateFilterType::Exact(from, to),
        }
    }

    pub fn matches(&self, entry: &LogEntry) -> bool {
        match &self.filter_type {
            DateFilterType::Exact(from, to) => {
                entry.date >= *from && entry.date <= *to
            }
            DateFilterType::Negate(inner) => !inner.matches(entry),
            DateFilterType::After(date) => entry.date > *date,
            DateFilterType::Before(date) => entry.date < *date,
        }
    }
}

fn parse_date_range(s: &str) -> Option<(NaiveDate, NaiveDate)> {
    // Check for datetime range with T separator: 2021/11/01T15:05-2021/11/01T15:08
    // Or simple date range: 2021/11/01-2021/12/25

    // Find the '-' separator between two date specs
    // The tricky part is that dates can contain '/' but not '-'... usually
    // Actually date format is YYYY/MM/DD so '-' only appears as range separator

    // Look for pattern like YYYY/...-YYYY/... or YYYY/...T...-YYYY/...T...
    // Split by '-' but only if there are exactly 2 date-like parts

    // Simple approach: find the range separator '-' after first date
    // A date pattern is: [\d]{4}(/\d{1,2}(/\d{1,2}(T\d{2}:\d{2}(:\d{2})?)?)?)?
    // Find position after first complete date pattern

    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() < 2 {
        return None;
    }

    // Try to find where first date ends and second begins
    // Strategy: try splitting at each '-'
    for i in 1..parts.len() {
        let first = parts[..i].join("-");
        let second = parts[i..].join("-");

        // Try to parse both as dates
        if let (Some(from), Some(to)) = (try_parse_date_spec(&first), try_parse_date_spec(&second)) {
            if let (Some((f_start, _)), Some((_, t_end))) = (from, to) {
                return Some((f_start, t_end));
            }
        }
    }

    None
}

fn try_parse_date_spec(s: &str) -> Option<Option<(NaiveDate, NaiveDate)>> {
    if s.is_empty() {
        return None;
    }

    // Check if it looks like a date (starts with 4-digit year or similar)
    let parts: Vec<&str> = s.split('/').collect();
    if parts.is_empty() {
        return None;
    }

    // Year must be 4 digits
    if parts[0].len() != 4 || !parts[0].chars().all(|c| c.is_ascii_digit()) {
        return None;
    }

    Some(Some(parse_date_range_end(s)))
}

fn parse_date_range_end(s: &str) -> (NaiveDate, NaiveDate) {
    // Handle T separator for datetime precision
    let (date_part, time_part) = if let Some(t_pos) = s.find('T') {
        (&s[..t_pos], Some(&s[t_pos+1..]))
    } else {
        (s, None)
    };

    let parts: Vec<&str> = date_part.split('/').collect();

    let year: i32 = parts.get(0).and_then(|p| p.parse().ok()).unwrap_or(2000);

    if parts.len() == 1 {
        // Year only
        let from = NaiveDate::from_ymd_opt(year, 1, 1).unwrap_or_default();
        let to = NaiveDate::from_ymd_opt(year, 12, 31).unwrap_or_default();
        return (from, to);
    }

    let month: u32 = parts.get(1).and_then(|p| p.parse().ok()).unwrap_or(1);

    if parts.len() == 2 {
        // Year/Month only
        let from = NaiveDate::from_ymd_opt(year, month, 1).unwrap_or_default();
        let last_day = days_in_month(year, month);
        let to = NaiveDate::from_ymd_opt(year, month, last_day).unwrap_or_default();
        return (from, to);
    }

    let day: u32 = parts.get(2).and_then(|p| p.parse().ok()).unwrap_or(1);
    let date = NaiveDate::from_ymd_opt(year, month, day).unwrap_or_default();

    // If time part exists, we'd need NaiveDateTime comparison, but for now use just date
    (date, date)
}

fn days_in_month(year: i32, month: u32) -> u32 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if year % 4 == 0 && (year % 100 != 0 || year % 400 == 0) { 29 } else { 28 },
        _ => 30,
    }
}

// Time filter
pub struct TimeFilter {
    spec: String,
    filter_type: TimeFilterType,
}

enum TimeFilterType {
    After(NaiveTime),
    Before(NaiveTime),
    Exact(NaiveTime, NaiveTime),
}

impl TimeFilter {
    pub fn parse(s: &str) -> Self {
        let s = s.trim();

        if s.starts_with('>') {
            let time = parse_time(&s[1..]);
            return TimeFilter { spec: s.to_string(), filter_type: TimeFilterType::After(time) };
        }
        if s.starts_with('<') {
            let time = parse_time(&s[1..]);
            return TimeFilter { spec: s.to_string(), filter_type: TimeFilterType::Before(time) };
        }

        let time = parse_time(s);
        TimeFilter { spec: s.to_string(), filter_type: TimeFilterType::Exact(time, time) }
    }

    pub fn matches(&self, entry: &LogEntry) -> bool {
        match &self.filter_type {
            TimeFilterType::After(t) => entry.time > *t,
            TimeFilterType::Before(t) => entry.time < *t,
            TimeFilterType::Exact(from, to) => entry.time >= *from && entry.time <= *to,
        }
    }
}

fn parse_time(s: &str) -> NaiveTime {
    let parts: Vec<&str> = s.split(':').collect();
    let h: u32 = parts.get(0).and_then(|p| p.parse().ok()).unwrap_or(0);
    let m: u32 = parts.get(1).and_then(|p| p.parse().ok()).unwrap_or(0);
    let sec: u32 = parts.get(2).and_then(|p| p.parse().ok()).unwrap_or(0);
    NaiveTime::from_hms_opt(h, m, sec).unwrap_or_default()
}

// String filter (for IP)
pub struct StringFilter {
    spec: String,
    negate: bool,
    pattern: StringPattern,
}

enum StringPattern {
    Exact(String),
    StartsWith(String),
    Regex(Regex),
}

impl StringFilter {
    pub fn parse(s: &str) -> Self {
        let (negate, rest) = if s.starts_with('!') {
            (true, &s[1..])
        } else {
            (false, s)
        };

        let pattern = if rest.starts_with('^') {
            StringPattern::StartsWith(rest[1..].to_string())
        } else if is_regex(rest) {
            match Regex::new(rest) {
                Ok(r) => StringPattern::Regex(r),
                Err(_) => StringPattern::Exact(rest.to_string()),
            }
        } else {
            StringPattern::Exact(rest.to_string())
        };

        StringFilter { spec: s.to_string(), negate, pattern }
    }

    pub fn matches(&self, s: &str) -> bool {
        let result = match &self.pattern {
            StringPattern::Exact(exact) => s == exact,
            StringPattern::StartsWith(prefix) => s.starts_with(prefix.as_str()),
            StringPattern::Regex(r) => r.is_match(s),
        };
        if self.negate { !result } else { result }
    }
}

fn is_regex(s: &str) -> bool {
    s.chars().any(|c| ".*+?[](){}|\\^$".contains(c))
}

// Method filter
pub struct MethodFilter {
    negate: bool,
    method: String,
    is_other: bool,
    is_none: bool,
}

impl MethodFilter {
    pub fn parse(s: &str) -> Self {
        let (negate, rest) = if s.starts_with('!') {
            (true, &s[1..])
        } else {
            (false, s)
        };

        let is_other = rest.eq_ignore_ascii_case("other");
        let is_none = rest.eq_ignore_ascii_case("none");

        MethodFilter {
            negate,
            method: rest.to_uppercase(),
            is_other,
            is_none,
        }
    }

    pub fn matches(&self, method: &str) -> bool {
        let standard_methods = ["GET", "POST", "PUT", "DELETE", "HEAD", "OPTIONS", "PATCH", "CONNECT", "TRACE"];
        let result = if self.is_other {
            !standard_methods.contains(&method)
        } else if self.is_none {
            method.is_empty()
        } else {
            method.eq_ignore_ascii_case(&self.method)
        };
        if self.negate { !result } else { result }
    }
}

// Path filter (also used for referer)
pub struct PathFilter {
    spec: String,
    clauses: Vec<PathClause>,
    logic: PathLogic,
}

#[derive(Clone)]
struct PathClause {
    negate: bool,
    pattern: CompiledPattern,
}

#[derive(Clone)]
enum CompiledPattern {
    Contains(String),
    Regex(Regex),
}

#[derive(Clone)]
enum PathLogic {
    And,
    Complex(String), // for | & operators
}

impl PathFilter {
    pub fn parse(s: &str) -> Self {
        // Simple comma-separated clauses (AND logic)
        let mut clauses = Vec::new();

        // Check for complex logic with | & ()
        if s.contains('|') || (s.contains('&') && s.contains('(')) {
            // Complex expression - simplified: just use contains for everything
            // This is a simplification
            let clause = parse_path_clause(s);
            clauses.push(clause);
        } else {
            // Simple comma-separated AND clauses
            for part in s.split(',') {
                let part = part.trim();
                if !part.is_empty() {
                    clauses.push(parse_path_clause(part));
                }
            }
        }

        PathFilter {
            spec: s.to_string(),
            clauses,
            logic: PathLogic::And,
        }
    }

    pub fn matches(&self, s: &str) -> bool {
        // All clauses must match (AND logic)
        for clause in &self.clauses {
            let m = match &clause.pattern {
                CompiledPattern::Contains(sub) => s.contains(sub.as_str()),
                CompiledPattern::Regex(r) => r.is_match(s),
            };
            let result = if clause.negate { !m } else { m };
            if !result { return false; }
        }
        true
    }
}

fn parse_path_clause(s: &str) -> PathClause {
    let (negate, rest) = if s.starts_with('!') {
        (true, &s[1..])
    } else {
        (false, s)
    };

    let pattern = if is_regex(rest) {
        match Regex::new(rest) {
            Ok(r) => CompiledPattern::Regex(r),
            Err(_) => CompiledPattern::Contains(rest.to_string()),
        }
    } else {
        CompiledPattern::Contains(rest.to_string())
    };

    PathClause { negate, pattern }
}

// Status filter
pub struct StatusFilter {
    spec: String,
    ranges: Vec<StatusRange>,
    negated_ranges: Vec<StatusRange>,
}

#[derive(Clone)]
struct StatusRange {
    from: u16,
    to: u16,
}

impl StatusFilter {
    pub fn parse(s: &str) -> Self {
        let mut ranges = Vec::new();
        let mut negated_ranges = Vec::new();

        for part in s.split(',') {
            let part = part.trim();
            let (negate, rest) = if part.starts_with('!') {
                (true, &part[1..])
            } else {
                (false, part)
            };

            let range = parse_status_range(rest);
            if negate {
                negated_ranges.push(range);
            } else {
                ranges.push(range);
            }
        }

        StatusFilter { spec: s.to_string(), ranges, negated_ranges }
    }

    pub fn matches(&self, status: u16) -> bool {
        // Check if matches any negated range - if so, reject
        for neg in &self.negated_ranges {
            if status >= neg.from && status <= neg.to {
                return false;
            }
        }

        // If no positive ranges, accept everything not negated
        if self.ranges.is_empty() {
            return true;
        }

        // Check if matches any positive range
        for range in &self.ranges {
            if status >= range.from && status <= range.to {
                return true;
            }
        }

        false
    }
}

fn parse_status_range(s: &str) -> StatusRange {
    // Can be: "404", "4xx", "402-420"
    if s.contains('-') && s.len() > 4 {
        // Range like "402-420"
        let parts: Vec<&str> = s.splitn(2, '-').collect();
        let from: u16 = parts[0].parse().unwrap_or(0);
        let to: u16 = parts[1].parse().unwrap_or(999);
        return StatusRange { from, to };
    }

    if s.ends_with("xx") || s.ends_with("XX") {
        // Class like "4xx"
        let class: u16 = s.chars().next().and_then(|c| c.to_digit(10)).unwrap_or(0) as u16;
        return StatusRange { from: class * 100, to: class * 100 + 99 };
    }

    // Single status
    let code: u16 = s.parse().unwrap_or(0);
    StatusRange { from: code, to: code }
}
