        let spaces_needed = inner_width.saturating_sub(zero_str.len() + max_str.len());
        println!("├──────────┼────┼─────┼{}┤", "─".repeat(bar_width + 2));

        for (i, date) in dates.iter().enumerate() {
            let hits = hits_per_day[i];
            let bytes = bytes_per_day[i];
            let val = if self.key_is_bytes { bytes } else { hits };
            let bar = make_bar(val, max_val, bar_width);
            println!("│{}/{:02}/{:02}│{:4}│{:>5}│{}│",
                date.year_ce().1, date.month(), date.day(),
                hits,
                format_bytes(bytes),
                bar,
            );
        }
        println!("└──────────┴────┴─────┴{}┘", "─".repeat(bar_width + 2));
    }

    fn print_time_table(&self, entries: &[LogEntry]) {
        let mut hits_per_hour = vec![0u64; 24];
        let mut bytes_per_hour = vec![0u64; 24];

        for entry in entries {
            let h = entry.time.hour() as usize;
            hits_per_hour[h] += 1;
            bytes_per_hour[h] += entry.bytes_sent;
        }

        let key_values = if self.key_is_bytes { &bytes_per_hour } else { &hits_per_hour };
        let max_val = key_values.iter().max().copied().unwrap_or(1);

        let bar_width = 20usize;

        println!("┌────┬────┬─────┬{}┐", "─".repeat(bar_width + 2));
        let max_str = format_bytes(max_val as u64);
        let inner = format!("0{:>fill$}{}", "", max_str, fill = bar_width + 1 - max_str.len());
        println!("│hour│hits│bytes│{}│", inner);
        println!("├────┼────┼─────┼{}┤", "─".repeat(bar_width + 2));

        for h in 0..24 {
            let hits = hits_per_hour[h];
            let bytes = bytes_per_hour[h];
            let val = if self.key_is_bytes { bytes } else { hits };
            let bar = make_bar(val, max_val, bar_width);
            println!("│{:<4}│{:^4}│{:>5}│{}│", h, hits, format_bytes(bytes), bar);
        }
        println!("└────┴────┴─────┴{}┘", "─".repeat(bar_width + 2));
    }

    fn print_status_table(&self, entries: &[LogEntry], dates: &[NaiveDate], 
                          date_index: &HashMap<NaiveDate, usize>, 
                          show_histogram: bool, num_days: usize) {
        // Aggregate by status
        let mut status_data: BTreeMap<u16, (u64, u64, Vec<u64>)> = BTreeMap::new();

        for entry in entries {
            let e = status_data.entry(entry.status).or_insert((0, 0, vec![0; num_days]));
            e.0 += 1;
            e.1 += entry.bytes_sent;
            if let Some(&idx) = date_index.get(&entry.date) {
                e.2[idx] += 1;
            }
        }

        let total_hits = entries.len() as f64;

        if self.args.length == 0 {
            // Show class summary
            let mut class_pcts = [0.0f64; 5]; // 1xx, 2xx, 3xx, 4xx, 5xx
            for (status, (hits, _, _)) in &status_data {
                let class = (*status / 100) as usize;
                if class < 6 && class > 0 {
                    class_pcts[class - 1] += *hits as f64 / total_hits * 100.0;
                }
            }

            println!("HTTP status codes:");
            let cols = ["1xx", "2xx", "3xx", "4xx", "5xx"];
            let mut active_cols = Vec::new();
            for (i, &pct) in class_pcts.iter().enumerate() {
                if pct > 0.0 {
                    active_cols.push((cols[i], pct));
                }
            }

            if active_cols.is_empty() {
                return;
            }

            let sep: String = active_cols.iter().map(|_| "─────").collect::<Vec<_>>().join("┬");
            println!("┌{}┐", sep.replace("┬", "┬"));

            let header: String = active_cols.iter().map(|(n, _)| format!(" {} ", n)).collect::<Vec<_>>().join("│");
            println!("│{}│", header);

            let sep2: String = active_cols.iter().map(|_| "─────").collect::<Vec<_>>().join("┼");
            println!("├{}┤", sep2.replace("┼", "┼"));

            let values: String = active_cols.iter().map(|(_, p)| format!("{:4.1}%", p)).collect::<Vec<_>>().join("│");
            println!("│{}│", values);

            let sep3: String = active_cols.iter().map(|_| "─────").collect::<Vec<_>>().join("┴");
            println!("└{}┘", sep3.replace("┴", "┴"));
            return;
        }

        // Sort statuses by hits (descending)
        let mut sorted: Vec<(u16, u64, u64, Vec<u64>)> = status_data.into_iter()
            .map(|(s, (h, b, d))| (s, h, b, d))
            .collect();

        if self.key_is_bytes {
            sorted.sort_by(|a, b| b.2.cmp(&a.2));
        } else {
            sorted.sort_by(|a, b| b.1.cmp(&a.1));
        }

        if show_histogram {
            // Format with days histogram
            let n_status = sorted.len();

            println!("HTTP status codes");

            // Build table
            let max_key = sorted.iter().map(|(_, h, b, _)| if self.key_is_bytes { *b } else { *h }).max().unwrap_or(1);

            let days_width = num_days;
            let trend_width = 5;

            // Status col width = 6 "status"
            // hits = 4, % = 5, bytes = 5, days = num_days, trend = 5
            let sep1 = "─".repeat(6);
            let sep2 = "─".repeat(4);
            let sep3 = format!("{:─<5}", "");
            let sep4 = "─".repeat(5);
            let sep5 = "─".repeat(days_width);
            let sep6 = "─".repeat(trend_width);

            println!("┌{}┬{}┬{}┬{}┬{}┬{}┐", sep1, sep2, sep3, sep4, sep5, sep6);

            let days_header = format!("{:^width$}", "days", width = days_width);
            println!("│{:^6}│{:^4}│{:^5}│{:^5}│{}│{:^5}│", "status", "hits", "%", "bytes", days_header, "trend");

            let sep1 = "─".repeat(6);
            let sep2 = "─".repeat(4);
            let sep3 = format!("{:─<5}", "");
            let sep4 = "─".repeat(5);
            let sep5 = "─".repeat(days_width);

            println!("├{}┼{}┼{}┼{}┼{}┼{}┤", sep1, sep2, sep3, sep4, sep5, sep6);

            for (status, hits, bytes, days_vec) in &sorted {
                let pct = *hits as f64 / total_hits * 100.0;
                let key_val = if self.key_is_bytes { *bytes } else { *hits };
                let days_bar = make_mini_histogram(days_vec, max_key, days_width);
                let trend = compute_trend_str(days_vec, &vec![entries.len() as u64; num_days], entries, dates, date_index, *hits, total_hits as u64);

                println!("│ {:<4} │{:>4}│{:>4.1}%│{:>5}│{}│{}│",
                    status, hits, pct, format_bytes(*bytes), days_bar, trend);
            }

            let sep5 = "─".repeat(days_width);
            println!("└{}┴{}┴{}┴{}┴{}┴{}┘", 
                "─".repeat(6), "─".repeat(4), "─".repeat(5), "─".repeat(5), sep5, "─".repeat(trend_width));
        } else {
            // Short format with % and # column
            let n_status = sorted.len();
            println!("{} HTTP status codes.", n_status);

            println!("┌───┬──────┬────┬{}┬─────┐", "─".repeat(6));
            println!("│ # │status│hits│{:^6}│bytes│", "%");
            println!("├───┼──────┼────┼{}┼─────┤", "─".repeat(6));

            for (i, (status, hits, bytes, _)) in sorted.iter().enumerate().take(self.max_rows) {
                let pct = *hits as f64 / total_hits * 100.0;
                println!("│{:3}│{:<6}│{:4}│{:>5.1}%│{:>5}│",
                    i + 1, status, hits, pct, format_bytes(*bytes));
            }
            println!("└───┴──────┴────┴{}┴─────┘", "─".repeat(6));
        }
    }

