        // Aggregate by referer (excluding "-")
        let mut ref_data: HashMap<String, (u64, u64, Vec<u64>)> = HashMap::new();

        for entry in entries {
            if entry.referer == "-" {
                continue;
            }
            let e = ref_data.entry(entry.referer.clone()).or_insert((0, 0, vec![0; num_days]));
            e.0 += 1;
            e.1 += entry.bytes_sent;
            if let Some(&idx) = date_index.get(&entry.date) {
                e.2[idx] += 1;
            }
        }

        let total_refs = ref_data.len();
        let total_hits = entries.len() as f64;

        if total_refs == 0 {
            println!("0 referrers : none");
            return;
        }

        let mut sorted: Vec<(String, u64, u64, Vec<u64>)> = ref_data.into_iter()
            .map(|(r, (h, b, d))| (r, h, b, d))
            .collect();

        if self.key_is_bytes {
            sorted.sort_by(|a, b| b.2.cmp(&a.2).then(a.0.cmp(&b.0)));
        } else {
            sorted.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
        }

        let display_count = sorted.len().min(self.max_rows);

        let max_ref_width = sorted.iter().take(display_count).map(|(r, _, _, _)| r.len()).max().unwrap_or(8);

        if show_histogram {
            if total_refs > display_count {
                println!("{} referrers. {} most frequent:", total_refs, display_count);
            } else {
                println!("{} referrers", total_refs);
            }

            // Target 50 chars total
            let target_width = 50usize;
            let fixed = 7 + 3 + 4 + 5 + num_days + 5; // separators + # + hits + bytes + days + trend
            let ref_col_width = (target_width.saturating_sub(fixed)).max(max_ref_width.min(target_width - 20));

            print_histogram_table(
                &sorted.iter().take(display_count).map(|(r, h, b, d)| (r.as_str(), *h, *b, d.as_slice())).collect::<Vec<_>>(),
                "referrer",
                ref_col_width,
                max_ref_width,
                total_hits,
                self.key_is_bytes,
                num_days,
                entries,
                dates,
                date_index,
            );
        } else {
            if total_refs > display_count {
                println!("{} referrers. {} most frequent:", total_refs, display_count);
            } else {
                println!("{} referrers.", total_refs);
            }

            print_simple_table(
                &sorted.iter().take(display_count).map(|(r, h, b, d)| (r.as_str(), *h, *b)).collect::<Vec<_>>(),
                "referrer",
                total_hits,
                self.max_rows,
            );
        }

        // Changes mode
        if self.args.changes {
            let (more, less) = compute_changes(&sorted, entries, dates, date_index, self.key_is_bytes);

            if more.is_empty() {
                println!("More popular referrers : none");
            } else {
                println!("More popular referrers");
                let max_ref_width = more.iter().map(|(r, _, _, _)| r.len()).max().unwrap_or(8);
                let fixed = 7 + 3 + 4 + 5 + num_days + 5;
                let ref_col_width = (target_width_for(num_days).saturating_sub(fixed)).max(max_ref_width.min(50));
