                    &more.iter().map(|(r, h, b, d)| (r.as_str(), *h, *b, d.as_slice())).collect::<Vec<_>>(),
                    "referrer",
                    ref_col_width,
                    max_ref_width,
                    total_hits,
                    self.key_is_bytes,
                    num_days,
                    entries,
                    dates,
                    date_index,
