            } else {
                println!("Less popular referrers");
                let max_ref_width = less.iter().map(|(r, _, _, _)| r.len()).max().unwrap_or(8);
                let fixed = 7 + 3 + 4 + 5 + num_days + 5;
                let ref_col_width = (target_width_for(num_days).saturating_sub(fixed)).max(max_ref_width.min(50));
                print_histogram_table(
                    &less.iter().map(|(r, h, b, d)| (r.as_str(), *h, *b, d.as_slice())).collect::<Vec<_>>(),
