fn wrap_days_bar(days: &[u64], num_days: usize, chunk_size: usize, num_chunks: usize) -> Vec<String> {
    let bar = make_mini_histogram_days(days, num_days);
    let bar_chars: Vec<char> = bar.chars().collect();

    let mut result = Vec::new();
    let mut pos = 0;
    for _ in 0..num_chunks {
        let end = (pos + chunk_size).min(bar_chars.len());
        let chunk: String = bar_chars[pos..end].iter().collect();
        let padded = format!("{:<width$}", chunk, width = num_days);
        result.push(padded);
        pos = end;
    }

    result
}

fn print_simple_table(
    rows: &[(&str, u64, u64)],
    col_name: &str,
    total_hits: f64,
