            println!("│{:3}│{}│{:4}│{:>4.1}%│{:>5}│",
                i + 1, padded, hits, pct, format_bytes(*bytes));
        } else {
            let name_chunks: Vec<&str> = name.as_bytes().chunks(col_width)
                .map(|c| std::str::from_utf8(c).unwrap_or(""))
                .collect();
            for (chunk_i, chunk) in name_chunks.iter().enumerate() {
                let padded = format!("{:<width$}", chunk, width = col_width);
                if chunk_i == 0 {
