                }
            }
        }
    }

    println!("└{}┴{}┴{}┴{}┴{}┘", sep_num, sep_name, sep_hits, sep_pct, sep_bytes);
}

pub fn format_bytes(bytes: u64) -> String {
    if bytes >= 1_000_000_000 {
        format!("{:.1}G", bytes as f64 / 1_000_000_000.0)
    } else if bytes >= 1_000_000 {
        format!("{:.1}M", bytes as f64 / 1_000_000.0)
    } else if bytes >= 1_000 {
        format!("{}K", bytes / 1_000)
    } else {
        format!("{}", bytes)
    }
}

fn make_bar(value: u64, max: u64, width: usize) -> String {
    if max == 0 {
        return " ".repeat(width);
    }

    let EIGHTHS: &[char] = &[' ', '▏', '▎', '▍', '▌', '▋', '▊', '▉', '█'];

    let total_eighths = ((value as f64 / max as f64 * width as f64 * 8.0).round()) as usize;
    let full_blocks = total_eighths / 8;
    let partial = total_eighths % 8;

    let mut s = String::new();
    for _ in 0..full_blocks {
        s.push('█');
    }
    if partial > 0 && full_blocks < width {
        s.push(EIGHTHS[partial]);
    }

    // Pad to width
    while s.chars().count() < width {
        s.push(' ');
    }

    s
}

fn make_mini_histogram(days: &[u64], max_val_hint: u64, width: usize) -> String {
    make_mini_histogram_days(days, width)
}

fn make_mini_histogram_days(days: &[u64], width: usize) -> String {
    if days.is_empty() {
        return " ".repeat(width);
    }

    let BARS: &[char] = &[' ', '▁', '▂', '▃', '▄', '▅', '▆', '▇'];

    let max_val = days.iter().max().copied().unwrap_or(0);
    if max_val == 0 {
        return " ".repeat(width);
    }

    let mut s = String::new();
    for &v in days.iter().take(width) {
        let idx = (v as f64 / max_val as f64 * 7.0).round() as usize;
        let idx = idx.min(7);
        s.push(BARS[idx]);
    }

    // Pad if needed
    while s.len() < width {
        s.push(' ');
    }

    s
}

pub fn is_resource_path(path: &str) -> bool {
    // Extract extension
    let path_no_query = path.split('?').next().unwrap_or(path);

    // Check for resource extensions
    if let Some(dot_pos) = path_no_query.rfind('.') {
        let ext = &path_no_query[dot_pos+1..].to_lowercase();
        let ext = ext.split('?').next().unwrap_or(ext);

        return matches!(ext,
            "png" | "jpg" | "jpeg" | "gif" | "svg" | "webp" | "ico" |
            "css" | "js" | "woff2" |
            "map"
        );
    }

    false
}

