    fn print_method_table(&self, entries: &[LogEntry], dates: &[NaiveDate],
                          date_index: &HashMap<NaiveDate, usize>,
                          show_histogram: bool, num_days: usize) {
        // Aggregate by method
        let mut method_data: HashMap<String, (u64, u64, Vec<u64>)> = HashMap::new();

        for entry in entries {
            let e = method_data.entry(entry.method.clone()).or_insert((0, 0, vec![0; num_days]));
            e.0 += 1;
            e.1 += entry.bytes_sent;
            if let Some(&idx) = date_index.get(&entry.date) {
                e.2[idx] += 1;
            }
        }

        let total_hits = entries.len() as f64;

        let mut sorted: Vec<(String, u64, u64, Vec<u64>)> = method_data.into_iter()
            .map(|(m, (h, b, d))| (m, h, b, d))
            .collect();

        if self.key_is_bytes {
            sorted.sort_by(|a, b| b.2.cmp(&a.2));
        } else {
            sorted.sort_by(|a, b| b.1.cmp(&a.1));
        }

        let max_method_width = sorted.iter().map(|(m, _, _, _)| m.len()).max().unwrap_or(6);
        let method_width = max_method_width.max(6);

