            println!("┌{}┬────┬─────┬─────┬{}┬─────┐", sep_m, "─".repeat(days_width));
            let days_header = format!("{:^width$}", "days", width = days_width);
            println!("│{:^width$}│hits│  %  │bytes│{}│trend│", "method", width = method_width, days_header);
            println!("├{}┼────┼─────┼─────┼{}┼─────┤", sep_m, "─".repeat(days_width));

            let max_key = sorted.iter().map(|(_, h, b, _)| if self.key_is_bytes { *b } else { *h }).max().unwrap_or(1);

            for (method, hits, bytes, days_vec) in &sorted {
                let pct = *hits as f64 / total_hits * 100.0;
                let days_bar = make_mini_histogram(days_vec, max_key, days_width);
                let trend = compute_trend_for_path(days_vec, entries, dates, date_index, *hits);

                println!("│{:^width$}│{:4}│{:>4.1}%│{:>5}│{}│{}│",
                    method, hits, pct, format_bytes(*bytes), days_bar, trend, width = method_width);
            }
            println!("└{}┴────┴─────┴─────┴{}┴─────┘", sep_m, "─".repeat(days_width));
        } else {
