            let n = sorted.len();
            println!("┌{}┬────┬─────┬─────┐", "─".repeat(method_width));
            println!("│{:^width$}│hits│  %  │bytes│", "method", width = method_width);
            println!("├{}┼────┼─────┼─────┤", "─".repeat(method_width));

            for (method, hits, bytes, _) in &sorted {
                let pct = *hits as f64 / total_hits * 100.0;
                println!("│{:^width$}│{:4}│{:>4.1}%│{:>5}│",
                    method, hits, pct, format_bytes(*bytes), width = method_width);
            }
            println!("└{}┴────┴─────┴─────┘", "─".repeat(method_width));
        }
    }

