fn get_date_range(from: NaiveDate, to: NaiveDate) -> Vec<NaiveDate> {
    let mut dates = Vec::new();
    let mut current = from;
    while current <= to {
        dates.push(current);
        current = current.succ_opt().unwrap_or(current);
        if current == from { break; } // Safety check
    }
    dates
}

fn target_width_for(_num_days: usize) -> usize {
    50
}

fn compute_changes(
    sorted: &[(String, u64, u64, Vec<u64>)],
    entries: &[LogEntry],
    dates: &[NaiveDate],
    date_index: &HashMap<NaiveDate, usize>,
    key_is_bytes: bool,
) -> (Vec<(String, u64, u64, Vec<u64>)>, Vec<(String, u64, u64, Vec<u64>)>) {
    let num_days = dates.len();
    if num_days < 4 {
        return (vec![], vec![]);
    }

    let mut more = Vec::new();
    let mut less = Vec::new();

    let half = num_days / 2;

    // Total per day
    let mut total_per_day = vec![0u64; num_days];
    for entry in entries {
        if let Some(&idx) = date_index.get(&entry.date) {
            total_per_day[idx] += 1;
        }
    }

    let total_first: u64 = total_per_day[..half].iter().sum();
    let total_second: u64 = total_per_day[half..].iter().sum();

    for (name, hits, bytes, days) in sorted {
        let first: u64 = days[..half].iter().sum();
        let second: u64 = days[half..].iter().sum();

        if total_first == 0 || total_second == 0 || first == 0 {
            continue;
        }

        let share_first = first as f64 / total_first as f64;
        let share_second = second as f64 / total_second as f64;

        if share_second > share_first {
            let ratio = share_second / share_first;
            if ratio >= 1.5 {
                more.push((name.clone(), *hits, *bytes, days.clone()));
            }
        } else if share_first > 0.0 {
            let ratio = share_first / share_second;
            if ratio >= 1.5 {
                less.push((name.clone(), *hits, *bytes, days.clone()));
            }
        }
    }

    (more, less)
}

fn compute_trend_for_path(
    days: &[u64],
    entries: &[LogEntry],
    dates: &[NaiveDate],
    date_index: &HashMap<NaiveDate, usize>,
    total_hits: u64,
) -> String {
    let num_days = days.len();
    if num_days < 4 {
        return "     ".to_string();
    }

    let half = num_days / 2;

    // Total hits per day
    let mut total_per_day = vec![0u64; num_days];
    for entry in entries {
        if let Some(&idx) = date_index.get(&entry.date) {
            total_per_day[idx] += 1;
        }
    }

    let total_first: u64 = total_per_day[..half].iter().sum();
    let total_second: u64 = total_per_day[half..].iter().sum();

    if total_first == 0 || total_second == 0 {
        return "     ".to_string();
    }

    let first: u64 = days[..half].iter().sum();
    let second: u64 = days[half..].iter().sum();

    if first == 0 {
        return "     ".to_string();
    }

    let share_first = first as f64 / total_first as f64;
    let share_second = second as f64 / total_second as f64;

    let ratio = if share_second > share_first {
        share_second / share_first
    } else {
        share_first / share_second
    };

    // Compute significance based on hit count
    // Chi-square-like: (obs - exp)^2 / exp 
    // Simple approach: use ratio and difference
    let diff = (share_second - share_first).abs();

    // Thresholds based on experimentation
    // Single arrow: ratio >= 1.5 and some significance
    // Double arrow: ratio >= 3.0 and higher significance

    let significance = diff * ratio;

    if share_second > share_first {
        if significance >= 0.5 {
            " ➚ ➚ ".to_string()
        } else if significance >= 0.2 || ratio >= 1.5 {
            "  ➚  ".to_string()
        } else {
            "     ".to_string()
        }
    } else {
        if significance >= 0.5 {
            " ➘ ➘ ".to_string()
        } else if significance >= 0.2 || ratio >= 1.5 {
            "  ➘  ".to_string()
        } else {
            "     ".to_string()
        }
    }
}

fn compute_trend_str(
    days: &[u64],
    total_per_day: &[u64],
    entries: &[LogEntry],
    dates: &[NaiveDate],
    date_index: &HashMap<NaiveDate, usize>,
    hits: u64,
    total_hits: u64,
) -> String {
    compute_trend_for_path(days, entries, dates, date_index, hits)
}

fn print_histogram_table(
    rows: &[(&str, u64, u64, &[u64])],
    col_name: &str,
    col_width: usize,
    max_content_width: usize,
    total_hits: f64,
    key_is_bytes: bool,
    num_days: usize,
    entries: &[LogEntry],
    dates: &[NaiveDate],
    date_index: &HashMap<NaiveDate, usize>,
) {
    // Fixed cols: # (3), hits (4), bytes (5), days (num_days), trend (5), separators (7)
    let fixed = 7 + 3 + 4 + 5 + num_days + 5;
    let effective_col = col_width.min(max_content_width);

    // Build separator lines
    let sep_num = "─".repeat(3);
    let sep_name = "─".repeat(col_width);
    let sep_hits = "─".repeat(4);
    let sep_bytes = "─".repeat(5);
    let sep_days = "─".repeat(num_days);
    let sep_trend = "─".repeat(5);

    println!("┌{}┬{}┬{}┬{}┬{}┬{}┐", sep_num, sep_name, sep_hits, sep_bytes, sep_days, sep_trend);

    let days_header = format!("{:^width$}", "days", width = num_days);
    println!("│ # │{:<width$}│hits│bytes│{}│trend│", col_name, days_header, width = col_width);

    println!("├{}┼{}┼{}┼{}┼{}┼{}┤", sep_num, sep_name, sep_hits, sep_bytes, sep_days, sep_trend);

    for (i, (name, hits, bytes, days_vec)) in rows.iter().enumerate() {
        let trend = compute_trend_for_path(days_vec, entries, dates, date_index, *hits);

        // Handle wrapping of long names
        let days_bar = make_mini_histogram_days(days_vec, num_days);

        if name.len() <= col_width {
            let padded_name = format!("{:<width$}", name, width = col_width);
            println!("│{:3}│{}│{:4}│{:>5}│{}│{}│",
                i + 1, padded_name, hits, format_bytes(*bytes), days_bar, trend);
        } else {
            // Wrap the name across multiple rows, and also wrap the days bar
            let name_chunks: Vec<&str> = name.as_bytes().chunks(col_width)
                .map(|c| std::str::from_utf8(c).unwrap_or(""))
                .collect();
            let days_chunks: Vec<String> = wrap_days_bar(days_vec, num_days, col_width, name_chunks.len());

            for (chunk_i, chunk) in name_chunks.iter().enumerate() {
                if chunk_i == 0 {
                    let padded = format!("{:<width$}", chunk, width = col_width);
                    let d_bar = days_chunks.get(0).cloned().unwrap_or_else(|| " ".repeat(num_days));
                    println!("│{:3}│{}│{:4}│{:>5}│{}│{}│",
                        i + 1, padded, hits, format_bytes(*bytes), d_bar, trend);
                } else {
                    let padded = format!("{:<width$}", chunk, width = col_width);
                    let d_bar = days_chunks.get(chunk_i).cloned().unwrap_or_else(|| " ".repeat(num_days));
                    println!("│   │{}│    │     │{}│     │",
                        padded, d_bar);
                }
            }
        }
    }

    println!("└{}┴{}┴{}┴{}┴{}┴{}┘", sep_num, sep_name, sep_hits, sep_bytes, sep_days, sep_trend);
}

fn wrap_days_bar(days: &[u64], num_days: usize, chunk_size: usize, num_chunks: usize) -> Vec<String> {
    let bar = make_mini_histogram_days(days, num_days);
    let bar_chars: Vec<char> = bar.chars().collect();

    let mut result = Vec::new();
    let mut pos = 0;
    for _ in 0..num_chunks {
        let end = (pos + chunk_size).min(bar_chars.len());
        let chunk: String = bar_chars[pos..end].iter().collect();
        let padded = format!("{:<width$}", chunk, width = num_days);
        result.push(padded);
        pos = end;
    }

    result
}

fn print_simple_table(
    rows: &[(&str, u64, u64)],
    col_name: &str,
    total_hits: f64,
    max_rows: usize,
) {
    let max_col_width = rows.iter().map(|(n, _, _)| n.len()).max().unwrap_or(col_name.len());
    let target_total = 50usize;
    let fixed = 7 + 3 + 4 + 5 + 5; // # + name + hits + % + bytes + separators
    let col_width = (target_total.saturating_sub(fixed)).max(max_col_width.min(27));

    let sep_num = "─".repeat(3);
    let sep_name = "─".repeat(col_width);
    let sep_hits = "─".repeat(4);
    let sep_pct = "─".repeat(5);
    let sep_bytes = "─".repeat(5);

    println!("┌{}┬{}┬{}┬{}┬{}┐", sep_num, sep_name, sep_hits, sep_pct, sep_bytes);
    println!("│ # │{:<width$}│hits│  %  │bytes│", col_name, width = col_width);
    println!("├{}┼{}┼{}┼{}┼{}┤", sep_num, sep_name, sep_hits, sep_pct, sep_bytes);

    for (i, (name, hits, bytes)) in rows.iter().enumerate().take(max_rows) {
        let pct = *hits as f64 / total_hits * 100.0;

        if name.len() <= col_width {
            let padded = format!("{:<width$}", name, width = col_width);
            println!("│{:3}│{}│{:4}│{:>4.1}%│{:>5}│",
                i + 1, padded, hits, pct, format_bytes(*bytes));
        } else {
            let name_chunks: Vec<&str> = name.as_bytes().chunks(col_width)
                .map(|c| std::str::from_utf8(c).unwrap_or(""))
                .collect();
            for (chunk_i, chunk) in name_chunks.iter().enumerate() {
                let padded = format!("{:<width$}", chunk, width = col_width);
                if chunk_i == 0 {
                    println!("│{:3}│{}│{:4}│{:>4.1}%│{:>5}│",
                        i + 1, padded, hits, pct, format_bytes(*bytes));
                } else {
                    println!("│   │{}│    │     │     │", padded);
                }
            }
        }
    }

    println!("└{}┴{}┴{}┴{}┴{}┘", sep_num, sep_name, sep_hits, sep_pct, sep_bytes);
}

pub fn format_bytes(bytes: u64) -> String {
    if bytes >= 1_000_000_000 {
        format!("{:.1}G", bytes as f64 / 1_000_000_000.0)
    } else if bytes >= 1_000_000 {
        format!("{:.1}M", bytes as f64 / 1_000_000.0)
    } else if bytes >= 1_000 {
        format!("{}K", bytes / 1_000)
    } else {
        format!("{}", bytes)
    }
}

fn make_bar(value: u64, max: u64, width: usize) -> String {
    if max == 0 {
        return " ".repeat(width);
    }

    let EIGHTHS: &[char] = &[' ', '▏', '▎', '▍', '▌', '▋', '▊', '▉', '█'];

    let total_eighths = ((value as f64 / max as f64 * width as f64 * 8.0).round()) as usize;
    let full_blocks = total_eighths / 8;
    let partial = total_eighths % 8;

    let mut s = String::new();
    for _ in 0..full_blocks {
        s.push('█');
    }
    if partial > 0 && full_blocks < width {
        s.push(EIGHTHS[partial]);
    }

    // Pad to width
    while s.chars().count() < width {
        s.push(' ');
    }

    s
}

fn make_mini_histogram(days: &[u64], max_val_hint: u64, width: usize) -> String {
    make_mini_histogram_days(days, width)
}

fn make_mini_histogram_days(days: &[u64], width: usize) -> String {
    if days.is_empty() {
        return " ".repeat(width);
    }

    let BARS: &[char] = &[' ', '▁', '▂', '▃', '▄', '▅', '▆', '▇'];

    let max_val = days.iter().max().copied().unwrap_or(0);
    if max_val == 0 {
        return " ".repeat(width);
    }

    let mut s = String::new();
    for &v in days.iter().take(width) {
        let idx = (v as f64 / max_val as f64 * 7.0).round() as usize;
        let idx = idx.min(7);
        s.push(BARS[idx]);
    }

    // Pad if needed
    while s.len() < width {
        s.push(' ');
    }

    s
}

pub fn is_resource_path(path: &str) -> bool {
    // Extract extension
    let path_no_query = path.split('?').next().unwrap_or(path);

    // Check for resource extensions
    if let Some(dot_pos) = path_no_query.rfind('.') {
        let ext = &path_no_query[dot_pos+1..].to_lowercase();
        let ext = ext.split('?').next().unwrap_or(ext);

        return matches!(ext,
            "png" | "jpg" | "jpeg" | "gif" | "svg" | "webp" | "ico" |
            "css" | "js" | "woff2" |
            "map"
        );
    }

    false
}

