fn get_date_range(from: NaiveDate, to: NaiveDate) -> Vec<NaiveDate> {
    let mut dates = Vec::new();
    let mut current = from;
    while current <= to {
        dates.push(current);
        current = current.succ_opt().unwrap_or(current);
        if current == from { break; } // Safety check
    }
    dates
}

fn target_width_for(_num_days: usize) -> usize {
    50
}

fn compute_changes(
    sorted: &[(String, u64, u64, Vec<u64>)],
    entries: &[LogEntry],
    dates: &[NaiveDate],
    date_index: &HashMap<NaiveDate, usize>,
    key_is_bytes: bool,
) -> (Vec<(String, u64, u64, Vec<u64>)>, Vec<(String, u64, u64, Vec<u64>)>) {
    let num_days = dates.len();
    if num_days < 4 {
        return (vec![], vec![]);
    }

    let mut more = Vec::new();
    let mut less = Vec::new();

    let half = num_days / 2;

    // Total per day
    let mut total_per_day = vec![0u64; num_days];
    for entry in entries {
        if let Some(&idx) = date_index.get(&entry.date) {
            total_per_day[idx] += 1;
        }
    }

    let total_first: u64 = total_per_day[..half].iter().sum();
    let total_second: u64 = total_per_day[half..].iter().sum();

    for (name, hits, bytes, days) in sorted {
        let first: u64 = days[..half].iter().sum();
        let second: u64 = days[half..].iter().sum();

        if total_first == 0 || total_second == 0 || first == 0 {
            continue;
        }

        let share_first = first as f64 / total_first as f64;
        let share_second = second as f64 / total_second as f64;

        if share_second > share_first {
            let ratio = share_second / share_first;
            if ratio >= 1.5 {
                more.push((name.clone(), *hits, *bytes, days.clone()));
            }
        } else if share_first > 0.0 {
            let ratio = share_first / share_second;
            if ratio >= 1.5 {
                less.push((name.clone(), *hits, *bytes, days.clone()));
            }
        }
    }

    (more, less)
}

fn compute_trend_for_path(
    days: &[u64],
    entries: &[LogEntry],
    dates: &[NaiveDate],
    date_index: &HashMap<NaiveDate, usize>,
    total_hits: u64,
) -> String {
    let num_days = days.len();
    if num_days < 4 {
        return "     ".to_string();
    }

    let half = num_days / 2;

    // Total hits per day
    let mut total_per_day = vec![0u64; num_days];
    for entry in entries {
        if let Some(&idx) = date_index.get(&entry.date) {
            total_per_day[idx] += 1;
        }
    }

    let total_first: u64 = total_per_day[..half].iter().sum();
    let total_second: u64 = total_per_day[half..].iter().sum();

    if total_first == 0 || total_second == 0 {
        return "     ".to_string();
    }

    let first: u64 = days[..half].iter().sum();
    let second: u64 = days[half..].iter().sum();

    if first == 0 {
        return "     ".to_string();
    }

    let share_first = first as f64 / total_first as f64;
    let share_second = second as f64 / total_second as f64;

    let ratio = if share_second > share_first {
        share_second / share_first
    } else {
        share_first / share_second
    };

    // Compute significance based on hit count
    // Chi-square-like: (obs - exp)^2 / exp 
    // Simple approach: use ratio and difference
    let diff = (share_second - share_first).abs();

    // Thresholds based on experimentation
    // Single arrow: ratio >= 1.5 and some significance
    // Double arrow: ratio >= 3.0 and higher significance

    let significance = diff * ratio;

    if share_second > share_first {
        if significance >= 0.5 {
            " ➚ ➚ ".to_string()
        } else if significance >= 0.2 || ratio >= 1.5 {
            "  ➚  ".to_string()
        } else {
            "     ".to_string()
        }
    } else {
        if significance >= 0.5 {
            " ➘ ➘ ".to_string()
        } else if significance >= 0.2 || ratio >= 1.5 {
            "  ➘  ".to_string()
        } else {
            "     ".to_string()
        }
    }
}

fn compute_trend_str(
    days: &[u64],
