    result = []
    for v in days_values[:num_days]:
        idx = round(v / max_val * 7)
        idx = min(7, max(0, idx))
        result.append(BARS[idx])
    while len(result) < num_days:
        result.append(' ')
    return ''.join(result)


def is_resource_path(path):
    """Check if path is a resource (image, css, js, etc.)."""
    p = path.split('?')[0]
    dot = p.rfind('.')
    if dot >= 0:
        ext = p[dot+1:].lower()
        return ext in RESOURCE_EXTENSIONS
    return False


def parse_log_line(line):
    """Parse an nginx combined log format line."""
    # Format: ip - user [date:time +tz] "METHOD path HTTP/x.x" status bytes "referer" "agent"
    # We use a regex for reliable parsing
    pattern = r'^(\S+) \S+ \S+ \[(\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+) [^\]]+\] "([A-Z]+) (\S+)[^"]*" (\d+) (\d+|-) "([^"]*)"'
    m = re.match(pattern, line)
    if not m:
        return None

    ip = m.group(1)
    day = int(m.group(2))
    month = MONTHS.get(m.group(3), 1)
    year = int(m.group(4))
    hour = int(m.group(5))
    minute = int(m.group(6))
    second = int(m.group(7))
    method = m.group(8)
    path = m.group(9)
    status = int(m.group(10))
    bytes_str = m.group(11)
    bytes_sent = int(bytes_str) if bytes_str != '-' else 0
    referer = m.group(12)

    try:
        d = date(year, month, day)
        t = time(hour, minute, second)
    except ValueError:
        return None

    return {
        'ip': ip,
        'date': d,
        'time': t,
        'method': method,
        'path': path,
        'status': status,
        'bytes': bytes_sent,
        'referer': referer,
        'date_str': f"{year}/{month:02d}/{day:02d}",
        'time_str': f"{hour:02d}:{minute:02d}:{second:02d}",
        'raw': line,
    }


class StatusFilter:
    def __init__(self, spec):
        self.spec = spec
        self.positive = []
        self.negative = []

        for part in spec.split(','):
            part = part.strip()
            negate = part.startswith('!')
            if negate:
                part = part[1:]

            r = self._parse_range(part)
            if negate:
                self.negative.append(r)
            else:
                self.positive.append(r)

    def _parse_range(self, s):
        s = s.strip()
        if re.match(r'^\d+$', s):
            v = int(s)
            return (v, v)
        if re.match(r'^[1-9]xx$', s, re.I):
            cls = int(s[0]) * 100
            return (cls, cls + 99)
        if re.match(r'^\d+-\d+$', s):
            a, b = s.split('-')
            return (int(a), int(b))
        return (0, 0)

    def matches(self, status):
        # Check negatives first
        for lo, hi in self.negative:
            if lo <= status <= hi:
                return False

        if not self.positive:
            return True

        for lo, hi in self.positive:
            if lo <= status <= hi:
                return True

        return False


class PathFilter:
    def __init__(self, spec):
        self.spec = spec
        self.clauses = []

        # Parse comma-separated clauses with potential | & operators
        # Simple approach: split by comma for AND logic
        for part in spec.split(','):
            part = part.strip()
            if not part:
                continue
            negate = part.startswith('!')
            if negate:
                part = part[1:]

            try:
                r = re.compile(part)
                self.clauses.append((negate, r, None))
            except re.error:
                self.clauses.append((negate, None, part))

    def matches(self, s):
        for negate, regex, plain in self.clauses:
            if regex:
                result = bool(regex.search(s))
            else:
                result = (plain or '') in s

            if negate:
                result = not result

            if not result:
                return False

        return True


class DateFilter:
    def __init__(self, spec):
        self.spec = spec
        self._parse(spec)

    def _parse(self, s):
        s = s.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]

        self.after = s.startswith('>')
        self.before = s.startswith('<')
        if self.after or self.before:
            s = s[1:]

        # Try to parse as range
        self.range_from = None
        self.range_to = None

        # Check for range separator (dash between two date specs)
        # Format: YYYY/MM/DD-YYYY/MM/DD or with T for time
        range_match = re.match(r'^(\d{4}(?:/\d{1,2}(?:/\d{1,2}(?:T\d{2}:\d{2}(?::\d{2})?)?)?)?)[-](\d{4}(?:/\d{1,2}(?:/\d{1,2}(?:T\d{2}:\d{2}(?::\d{2})?)?)?)?)$', s)

        if range_match:
            self.range_from = self._parse_date_start(range_match.group(1))
            self.range_to = self._parse_date_end(range_match.group(2))
        else:
            self.range_from = self._parse_date_start(s)
            self.range_to = self._parse_date_end(s)

    def _parse_date_start(self, s):
        # Parse date spec and return the START of the period
        parts = s.split('T')[0].split('/')
        if not parts or not re.match(r'^\d{4}$', parts[0]):
            return date.min

        year = int(parts[0])
        if len(parts) == 1:
            return date(year, 1, 1)
        month = int(parts[1])
        if len(parts) == 2:
            return date(year, month, 1)
        day = int(parts[2])
        try:
            return date(year, month, day)
        except ValueError:
            return date.min

    def _parse_date_end(self, s):
        # Parse date spec and return the END of the period
        parts = s.split('T')[0].split('/')
        if not parts or not re.match(r'^\d{4}$', parts[0]):
            return date.max

        year = int(parts[0])
        if len(parts) == 1:
            # Last day of year
            return date(year, 12, 31)
        month = int(parts[1])
        if len(parts) == 2:
            # Last day of month
            import calendar
            last_day = calendar.monthrange(year, month)[1]
            return date(year, month, last_day)
        day = int(parts[2])
        try:
            return date(year, month, day)
        except ValueError:
            return date.max

    def matches(self, entry):
        d = entry['date']

        if self.after:
            result = d > self.range_from
        elif self.before:
            result = d < self.range_to
        else:
            result = self.range_from <= d <= self.range_to

        return not result if self.negate else result


class TimeFilter:
    def __init__(self, spec):
        self.spec = spec
        s = spec.strip()
        self.after = s.startswith('>')
        self.before = s.startswith('<')
        if self.after or self.before:
            s = s[1:]
        parts = s.split(':')
        h = int(parts[0]) if parts else 0
        m = int(parts[1]) if len(parts) > 1 else 0
        sec = int(parts[2]) if len(parts) > 2 else 0
        self.t = time(h, m, sec)

    def matches(self, entry):
        t = entry['time']
        if self.after:
            return t > self.t
        elif self.before:
            return t < self.t
        return t == self.t


class IpFilter:
    def __init__(self, spec):
        self.spec = spec
        s = spec.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]

        if s.startswith('^'):
            self.prefix = s[1:]
            self.regex = None
            self.exact = None
        elif any(c in s for c in '.*+?[](){}|\\^$'):
            try:
                self.regex = re.compile(s)
            except:
                self.regex = None
            self.exact = None
            self.prefix = None
        else:
            self.exact = s
            self.regex = None
            self.prefix = None

    def matches(self, entry):
        ip = entry['ip']
        if self.exact:
            result = ip == self.exact
        elif self.prefix:
            result = ip.startswith(self.prefix)
        elif self.regex:
            result = bool(self.regex.search(ip))
        else:
            result = True
        return not result if self.negate else result


class MethodFilter:
    def __init__(self, spec):
        self.spec = spec
        s = spec.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]
        self.is_other = s.lower() == 'other'
        self.is_none = s.lower() == 'none'
        self.method = s.upper()
        self.STANDARD = {'GET', 'POST', 'PUT', 'DELETE', 'HEAD', 'OPTIONS', 'PATCH', 'CONNECT', 'TRACE'}

    def matches(self, entry):
        m = entry['method']
        if self.is_other:
            result = m not in self.STANDARD
        elif self.is_none:
            result = not m
        else:
            result = m.upper() == self.method
        return not result if self.negate else result


def parse_fields(spec, default_fields=None, all_fields=None):
    if default_fields is None:
        default_fields = ['date', 'status', 'referer', 'path']
    if all_fields is None:
        all_fields = ['date', 'time', 'method', 'status', 'ip', 'referer', 'path']

    if spec is None:
        return default_fields[:]

    FIELD_MAP = {
        'date': 'date', 'd': 'date',
        'time': 'time', 
        'method': 'method', 'm': 'method',
        'status': 'status', 's': 'status',
        'ip': 'ip', 'i': 'ip',
        'ref': 'referer', 'referer': 'referer', 'referrer': 'referer', 'r': 'referer',
        'path': 'path', 'p': 'path',
        'all': None, 'a': None,
    }

    spec = spec.strip()

    # Find first operator position
    first_op = -1
    for i, c in enumerate(spec):
        if c in '+-':
            first_op = i
            break

    if first_op == -1:
        # No operators
        if spec.lower() in ('all', 'a'):
            return all_fields[:]
        # Simple field list
        fields = []
        for part in spec.split(','):
            part = part.strip().lower()
            if part in FIELD_MAP:
                f = FIELD_MAP[part]
                if f and f not in fields:
                    fields.append(f)
        return fields

    if first_op == 0:
        base = default_fields[:]
    else:
        base_spec = spec[:first_op].strip().lower()
        if base_spec in ('all', 'a'):
            base = all_fields[:]
        else:
            base = []
            for part in base_spec.split(','):
                part = part.strip().lower()
                if part in FIELD_MAP:
                    f = FIELD_MAP[part]
                    if f and f not in base:
                        base.append(f)

    # Parse operators
    rest = spec[first_op:]
    i = 0
    while i < len(rest):
        op = rest[i]
        i += 1
        # Find end of field name
        j = i
        while j < len(rest) and rest[j] not in '+-':
            j += 1
        field_name = rest[i:j].strip().lower()
        i = j

        if field_name in FIELD_MAP:
            f = FIELD_MAP[field_name]
            if f:
                if op == '+':
                    base = [x for x in base if x != f]
                    base.append(f)
                elif op == '-':
                    base = [x for x in base if x != f]

    return base


def collect_files(paths, no_name_check=False):
    """Collect all log files from given paths."""
    files = []
    for path in paths:
        p = Path(path)
        if p.is_file():
            if no_name_check or is_log_filename(p.name):
                files.append(p)
        elif p.is_dir():
            dir_files = []
            for f in p.iterdir():
                if f.is_file() and (no_name_check or is_log_filename(f.name)):
                    dir_files.append(f)
            dir_files.sort()
            files.extend(dir_files)
    return files


def is_log_filename(name):
    return name.startswith('access') or ('.log' in name and not name.startswith('.'))


def read_file(path, filters, collect_raw=False):
    """Read a log file and return matching entries."""
    entries = []
    raw_lines = []

    try:
        if str(path).endswith('.gz'):
            f = gzip.open(path, 'rt', encoding='utf-8', errors='replace')
        else:
            f = open(path, 'r', encoding='utf-8', errors='replace')

        with f:
            for line in f:
                line = line.rstrip('\n\r')
                if not line:
                    continue
                entry = parse_log_line(line)
                if entry is None:
                    continue
                if matches_filters(entry, filters):
                    if collect_raw:
                        raw_lines.append(line)
                    entries.append(entry)
    except Exception as e:
        pass

    return entries, raw_lines


def matches_filters(entry, filters):
    for f in filters:
        if not f.matches(entry):
            return False
    return True


def build_filters(args):
    """Build list of filter objects from args."""
    filters = []
    if args.date:
        filters.append(DateFilter(args.date))
    if hasattr(args, 'time_filter') and args.time_filter:
        filters.append(TimeFilter(args.time_filter))
    if args.ip:
        filters.append(IpFilter(args.ip))
    if args.method:
        filters.append(MethodFilter(args.method))
    if args.path:
        filters.append(PathFilter(args.path))
    if args.referer:
        filters.append(PathFilter(args.referer))  # Note: using PathFilter for referer too
    if args.status:
        filters.append(StatusFilter(args.status))
    return filters


def print_progress(current, total, use_color, force_erase=False):
    """Print a progress bar to stderr."""
    width = 40
    filled = current * width // total if total > 0 else 0

    bar = '█' * filled + ' ' * (width - filled)

    sys.stderr.write(f"\x1b7\x1b[2K{current:3} / {total} ")
    if use_color:
        sys.stderr.write(f"\x1b[48;5;5m\x1b[38;5;11m{bar}\x1b[49m\x1b[39m")
    else:
        sys.stderr.write(bar)
    sys.stderr.write("\x1b8")
    sys.stderr.flush()


def get_date_range(min_date, max_date):
    """Return sorted list of all dates between min and max inclusive."""
    dates = []
    d = min_date
    while d <= max_date:
        dates.append(d)
        d += timedelta(days=1)
    return dates


def compute_trend(days_values, total_per_day):
    """Compute trend string (➚, ➘, etc.) based on share change."""
    n = len(days_values)
    if n < 4:
        return '     '

    half = n // 2

    total_first = sum(total_per_day[:half])
    total_second = sum(total_per_day[half:])

    if total_first == 0 or total_second == 0:
        return '     '

    first = sum(days_values[:half])
    second = sum(days_values[half:])

    if first == 0 and second == 0:
        return '     '

    if first == 0:
        # New entry
        return '  ➚  '

    share_first = first / total_first
    share_second = second / total_second

    diff = share_second - share_first

    if share_first > 0:
        ratio = share_second / share_first if share_second > share_first else share_first / share_second
    else:
        ratio = float('inf')

    significance = abs(diff) * ratio

    # Use chi-square-like test
    # Expected in second half if no change:
    exp_second = first * total_second / total_first
    if exp_second > 0:
        chi2 = (second - exp_second) ** 2 / exp_second
    else:
        chi2 = 0

    if diff > 0:
        # Increasing
        if chi2 >= 10 and ratio >= 3.0:
            return ' ➚ ➚ '
        elif chi2 >= 3.5 or (ratio >= 2.0 and abs(diff) >= 0.15):
            return '  ➚  '
        else:
            return '     '
    elif diff < 0:
        # Decreasing
        if chi2 >= 10 and ratio >= 3.0:
            return ' ➘ ➘ '
        elif chi2 >= 3.5 or (ratio >= 2.0 and abs(diff) >= 0.15):
            return '  ➘  '
        else:
            return '     '
    else:
        return '     '


class TableRenderer:
    """Renders tables similar to rhit output."""

    TARGET_WIDTH = 50

    def __init__(self, args, use_color):
        self.args = args
        self.use_color = use_color
        self.key_is_bytes = args.key.startswith('b')

        max_rows_map = {0: 10, 1: 50, 2: 100, 3: 150, 4: 200, 5: 250, 6: 300}
        self.max_rows = max_rows_map.get(args.length, 50)

    def render_all(self, entries, fields, filters, n_files, display_path, total_before_filter):
        """Render all requested fields."""
        if not entries:
            sys.stdout.write(f"0 hits and 0 bytes\n")
            return

        total_hits = len(entries)
        total_bytes = sum(e['bytes'] for e in entries)

        min_date = min(e['date'] for e in entries)
        max_date = max(e['date'] for e in entries)

        # Summary line
        sys.stdout.write(f"{total_hits} hits and {format_bytes(total_bytes)} from "
                        f"{min_date.year}/{min_date.month:02d}/{min_date.day:02d} to "
                        f"{max_date.year}/{max_date.month:02d}/{max_date.day:02d}\n")

        # Filter info
        if total_before_filter > 0 and total_hits < total_before_filter:
            # Determine filter name  
            filter_names = []
            if self.args.date:
                filter_names.append(f"date on pattern {self.args.date}")
            if getattr(self.args, 'time_filter', None):
                filter_names.append(f"time on pattern {self.args.time_filter}")
            if self.args.ip:
                filter_names.append(f"ip on pattern {self.args.ip}")
            if self.args.method:
                filter_names.append(f"method on pattern {self.args.method}")
            if self.args.path:
                filter_names.append(f"path on pattern {self.args.path}")
            if self.args.referer:
                filter_names.append(f"referer on pattern {self.args.referer}")
            if self.args.status:
                filter_names.append(f"status on pattern {self.args.status}")

            if filter_names:
                pct = (total_before_filter - total_hits) / total_before_filter * 100
                filter_desc = "Filtering by " + filter_names[0] + f" removed {pct:.2f}%"
                # Wrap at ~43 chars to match original
                self._print_wrapped(filter_desc, 43)
                sys.stdout.write(f"\nof total lines\n")
                total_bytes_all = total_bytes  # we don't have the before-filter bytes
                sys.stdout.write(f" ==> hits: {total_hits}, bytes sent: {format_bytes(total_bytes)}\n")

        # Build date range
        dates = get_date_range(min_date, max_date)
        num_days = len(dates)
        date_index = {d: i for i, d in enumerate(dates)}

        # Compute total per day (for trend calculation)
        total_per_day = [0] * num_days
        for e in entries:
            idx = date_index.get(e['date'])
            if idx is not None:
                total_per_day[idx] += 1

        show_histogram = num_days >= 4

        for field in fields:
            if field == 'date':
                self._render_date_table(entries, dates, date_index, num_days)
            elif field == 'time':
                self._render_time_table(entries, num_days)
            elif field == 'method':
                self._render_method_table(entries, dates, date_index, num_days, total_per_day, show_histogram)
            elif field == 'status':
                self._render_status_table(entries, dates, date_index, num_days, total_per_day, show_histogram)
            elif field == 'ip':
                self._render_ip_table(entries, dates, date_index, num_days, total_per_day, show_histogram)
            elif field == 'referer':
                self._render_referer_table(entries, dates, date_index, num_days, total_per_day, show_histogram)
            elif field == 'path':
                self._render_path_table(entries, dates, date_index, num_days, total_per_day, show_histogram)

    def _print_wrapped(self, text, width):
        """Print text wrapped at width chars."""
        while len(text) > width:
            # Find last space before width
            pos = text.rfind(' ', 0, width)
            if pos < 0:
                pos = width
            sys.stdout.write(text[:pos] + '\n')
            text = text[pos:].lstrip()
        sys.stdout.write(text)

    def _render_date_table(self, entries, dates, date_index, num_days):
        hits_per_day = [0] * num_days
        bytes_per_day = [0] * num_days

        for e in entries:
            idx = date_index.get(e['date'])
            if idx is not None:
                hits_per_day[idx] += 1
                bytes_per_day[idx] += e['bytes']

        key_vals = bytes_per_day if self.key_is_bytes else hits_per_day
        max_val = max(key_vals) if key_vals else 1

        bar_width = 20
        max_str = format_bytes(max_val)
        inner = f"0{' ' * (bar_width - 1 - len(max_str))}{max_str}"

        sys.stdout.write(f"┌──────────┬────┬─────┬{'─' * (bar_width + 2)}┐\n")
        sys.stdout.write(f"│   date   │hits│bytes│{inner}│\n")
        sys.stdout.write(f"├──────────┼────┼─────┼{'─' * (bar_width + 2)}┤\n")

        for i, d in enumerate(dates):
            hits = hits_per_day[i]
            bts = bytes_per_day[i]
            key_v = bts if self.key_is_bytes else hits
            bar = make_bar(key_v, max_val, bar_width)
            sys.stdout.write(f"│{d.year}/{d.month:02d}/{d.day:02d}│{hits:4}│{format_bytes(bts):>5}│{bar}│\n")

        sys.stdout.write(f"└──────────┴────┴─────┴{'─' * (bar_width + 2)}┘\n")

    def _render_time_table(self, entries, num_days):
        hits_per_hour = [0] * 24
        bytes_per_hour = [0] * 24

        for e in entries:
            h = e['time'].hour
            hits_per_hour[h] += 1
            bytes_per_hour[h] += e['bytes']

        key_vals = bytes_per_hour if self.key_is_bytes else hits_per_hour
        max_val = max(key_vals) if any(key_vals) else 1

        bar_width = 20
        max_str = format_bytes(max_val)
        inner = f"0{' ' * (bar_width - 1 - len(max_str))}{max_str}"

        sys.stdout.write(f"┌────┬────┬─────┬{'─' * (bar_width + 2)}┐\n")
        sys.stdout.write(f"│hour│hits│bytes│{inner}│\n")
        sys.stdout.write(f"├────┼────┼─────┼{'─' * (bar_width + 2)}┤\n")

        for h in range(24):
            hits = hits_per_hour[h]
            bts = bytes_per_hour[h]
            key_v = bts if self.key_is_bytes else hits
            bar = make_bar(key_v, max_val, bar_width)
            sys.stdout.write(f"│{h:<4}│{hits:^4}│{format_bytes(bts):>5}│{bar}│\n")

        sys.stdout.write(f"└────┴────┴─────┴{'─' * (bar_width + 2)}┘\n")

    def _aggregate_by(self, entries, key_fn, date_index, num_days):
        """Aggregate entries by a key function."""
        data = defaultdict(lambda: [0, 0, [0] * num_days])

        for e in entries:
            k = key_fn(e)
            d = data[k]
            d[0] += 1
            d[1] += e['bytes']
            idx = date_index.get(e['date'])
            if idx is not None:
                d[2][idx] += 1

        return data

    def _sort_by_key(self, data_dict):
        """Sort dict items by key (hits or bytes)."""
        items = list(data_dict.items())
        if self.key_is_bytes:
            items.sort(key=lambda x: (-x[1][1], x[0]))
        else:
            items.sort(key=lambda x: (-x[1][0], x[0]))
        return items

    def _render_method_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        data = self._aggregate_by(entries, lambda e: e['method'], date_index, num_days)
        sorted_items = self._sort_by_key(data)

        total_hits = len(entries)

        sys.stdout.write("methods\n")

        if show_histogram:
            self._print_histogram_table(
                sorted_items, 'method', total_hits, total_per_day, num_days,
                center_col=True
            )
        else:
            self._print_pct_table(sorted_items, 'method', total_hits)

    def _render_status_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        data = self._aggregate_by(entries, lambda e: str(e['status']), date_index, num_days)

        # Sort numerically
        sorted_items = list(data.items())
        if self.key_is_bytes:
            sorted_items.sort(key=lambda x: (-x[1][1], int(x[0])))
        else:
            sorted_items.sort(key=lambda x: (-x[1][0], int(x[0])))

        total_hits = len(entries)
        n_status = len(sorted_items)

        if self.args.length == 0:
            # Show class summary
            self._render_status_class_summary(entries, total_hits)
            return

        if show_histogram:
            sys.stdout.write("HTTP status codes\n")
            # Status table uses different format
            self._print_status_histogram_table(sorted_items, total_hits, total_per_day, num_days)
        else:
            sys.stdout.write(f"{n_status} HTTP status codes.\n")
            self._print_status_pct_table(sorted_items, total_hits)

    def _render_status_class_summary(self, entries, total_hits):
        classes = defaultdict(int)
        for e in entries:
            cls = e['status'] // 100
            classes[cls] += 1

        cols = []
        for cls in [1, 2, 3, 4, 5]:
            if classes[cls] > 0:
                pct = classes[cls] / total_hits * 100
                cols.append((f"{cls}xx", f"{pct:.1f}%"))

        if not cols:
            return

        sys.stdout.write("HTTP status codes:\n")
        sep = '┬'.join(['─────'] * len(cols))
        sys.stdout.write(f"┌{sep}┐\n")
        header = '│'.join(f" {h} " for h, _ in cols)
        sys.stdout.write(f"│{header}│\n")
        sep2 = '┼'.join(['─────'] * len(cols))
        sys.stdout.write(f"├{sep2}┤\n")
        values = '│'.join(f"{v:>5}" for _, v in cols)
        sys.stdout.write(f"│{values}│\n")
        sep3 = '┴'.join(['─────'] * len(cols))
        sys.stdout.write(f"└{sep3}┘\n")

    def _print_status_histogram_table(self, sorted_items, total_hits, total_per_day, num_days):
        days_w = num_days
        trend_w = 5
        status_w = 6
        hits_w = 4
        pct_w = 5 + (1 if total_hits >= 100 else 0)  # adjust for 100%

        # Determine % column width
        max_pct_str = f"{max(v[0] for _, v in sorted_items) / total_hits * 100:.1f}%"
        pct_w = max(5, len(max_pct_str))

        bytes_w = 5

        sys.stdout.write(f"┌{'─'*status_w}┬{'─'*hits_w}┬{'─'*pct_w}┬{'─'*bytes_w}┬{'─'*days_w}┬{'─'*trend_w}┐\n")
        days_hdr = f"{'days':^{days_w}}"
        sys.stdout.write(f"│{'status':^{status_w}}│{'hits':^{hits_w}}│{'%':^{pct_w}}│{'bytes':^{bytes_w}}│{days_hdr}│{'trend':^{trend_w}}│\n")
        sys.stdout.write(f"├{'─'*status_w}┼{'─'*hits_w}┼{'─'*pct_w}┼{'─'*bytes_w}┼{'─'*days_w}┼{'─'*trend_w}┤\n")

        max_key = max((v[1] if self.key_is_bytes else v[0]) for _, v in sorted_items) if sorted_items else 1

        for status_str, (hits, bts, days_v) in sorted_items:
            pct = hits / total_hits * 100
            days_bar = make_mini_bar(days_v, num_days)
            trend = compute_trend(days_v, total_per_day)

            sys.stdout.write(f"│ {int(status_str):^4} │{hits:>{hits_w}}│{pct:.1f}%│{format_bytes(bts):>{bytes_w}}│{days_bar}│{trend}│\n")

        sys.stdout.write(f"└{'─'*status_w}┴{'─'*hits_w}┴{'─'*pct_w}┴{'─'*bytes_w}┴{'─'*days_w}┴{'─'*trend_w}┘\n")

    def _print_status_pct_table(self, sorted_items, total_hits):
        # Show as numbered list with %
        n = len(sorted_items)

        max_pct_str = f"{100.0:.1f}%"
        pct_w = max(5, len(max_pct_str))

        sys.stdout.write(f"┌───┬──────┬────┬{'─'*pct_w}┬─────┐\n")
        sys.stdout.write(f"│ # │status│hits│{'%':^{pct_w}}│bytes│\n")
        sys.stdout.write(f"├───┼──────┼────┼{'─'*pct_w}┼─────┤\n")

        for i, (status_str, (hits, bts, _)) in enumerate(sorted_items[:self.max_rows]):
            pct = hits / total_hits * 100
            pct_str = f"{pct:.1f}%"
            sys.stdout.write(f"│{i+1:3}│{status_str:<6}│{hits:4}│{pct_str:>{pct_w}}│{format_bytes(bts):>5}│\n")

        sys.stdout.write(f"└───┴──────┴────┴{'─'*pct_w}┴─────┘\n")

    def _print_pct_table(self, sorted_items, col_name, total_hits):
        """Print a simple numbered table with % column."""
        max_name_len = max((len(k) for k, _ in sorted_items), default=len(col_name))

        target = self.TARGET_WIDTH
        fixed = 3 + 1 + 4 + 1 + 5 + 1 + 5 + 1 + 7  # # + hits + % + bytes + seps
        name_w = max(len(col_name), min(max_name_len, target - fixed))

        sep_num = '─' * 3
        sep_name = '─' * name_w
        sep_hits = '─' * 4
        sep_pct = '─' * 5
        sep_bytes = '─' * 5

        sys.stdout.write(f"┌{sep_num}┬{sep_name}┬{sep_hits}┬{sep_pct}┬{sep_bytes}┐\n")
        sys.stdout.write(f"│ # │{col_name:<{name_w}}│hits│  %  │bytes│\n")
        sys.stdout.write(f"├{sep_num}┼{sep_name}┼{sep_hits}┼{sep_pct}┼{sep_bytes}┤\n")

        for i, (name, (hits, bts, _)) in enumerate(sorted_items[:self.max_rows]):
            pct = hits / total_hits * 100
            pct_str = f"{pct:.1f}%"

            if len(name) <= name_w:
                sys.stdout.write(f"│{i+1:3}│{name:<{name_w}}│{hits:4}│{pct_str:>5}│{format_bytes(bts):>5}│\n")
            else:
                # Wrap
                chunks = [name[j:j+name_w] for j in range(0, len(name), name_w)]
                for ci, chunk in enumerate(chunks):
                    padded = f"{chunk:<{name_w}}"
                    if ci == 0:
                        sys.stdout.write(f"│{i+1:3}│{padded}│{hits:4}│{pct_str:>5}│{format_bytes(bts):>5}│\n")
                    else:
                        sys.stdout.write(f"│   │{padded}│    │     │     │\n")

        sys.stdout.write(f"└{sep_num}┴{sep_name}┴{sep_hits}┴{sep_pct}┴{sep_bytes}┘\n")

    def _print_histogram_table(self, sorted_items, col_name, total_hits, total_per_day, num_days,
                                center_col=False, header_prefix=''):
        """Print a table with days histogram."""
        max_name_len = max((len(k) for k, _ in sorted_items), default=len(col_name))

        target = self.TARGET_WIDTH
        # Fixed: # (3) + hits (4) + bytes (5) + days (num_days) + trend (5) + 7 seps
        fixed = 3 + 4 + 5 + num_days + 5 + 7
        name_w = max(len(col_name), min(max_name_len, target - fixed))

        days_w = num_days
        trend_w = 5

        sep_num = '─' * 3
        sep_name = '─' * name_w
        sep_hits = '─' * 4
        sep_bytes = '─' * 5
        sep_days = '─' * days_w
        sep_trend = '─' * trend_w

        sys.stdout.write(f"┌{sep_num}┬{sep_name}┬{sep_hits}┬{sep_bytes}┬{sep_days}┬{sep_trend}┐\n")
        days_hdr = f"{'days':^{days_w}}"
        if center_col:
            sys.stdout.write(f"│ # │{col_name:^{name_w}}│hits│bytes│{days_hdr}│trend│\n")
        else:
            sys.stdout.write(f"│ # │{col_name:<{name_w}}│hits│bytes│{days_hdr}│trend│\n")
        sys.stdout.write(f"├{sep_num}┼{sep_name}┼{sep_hits}┼{sep_bytes}┼{sep_days}┼{sep_trend}┤\n")

        for i, (name, (hits, bts, days_v)) in enumerate(sorted_items[:self.max_rows]):
            days_bar = make_mini_bar(days_v, days_w)
            trend = compute_trend(days_v, total_per_day)

            if len(name) <= name_w:
                if center_col:
                    padded = f"{name:^{name_w}}"
                else:
                    padded = f"{name:<{name_w}}"
                sys.stdout.write(f"│{i+1:3}│{padded}│{hits:4}│{format_bytes(bts):>5}│{days_bar}│{trend}│\n")
            else:
                # Wrap
                chunks = [name[j:j+name_w] for j in range(0, len(name), name_w)]
                days_bar_chars = list(days_bar)
                for ci, chunk in enumerate(chunks):
                    # Days bar wraps too
                    d_start = ci * name_w
                    d_end = d_start + days_w
                    # Actually the days bar stays intact per row but the name wraps
                    if ci == 0:
                        padded = f"{chunk:<{name_w}}"
                        sys.stdout.write(f"│{i+1:3}│{padded}│{hits:4}│{format_bytes(bts):>5}│{days_bar}│{trend}│\n")
                    else:
                        padded = f"{chunk:<{name_w}}"
                        # Continuation rows for days bar
                        # When name wraps, the days bar also needs to show continuation
                        d_bar_cont = ' ' * days_w
                        # Handle wrapped days bar
                        sys.stdout.write(f"│   │{padded}│    │     │{d_bar_cont}│     │\n")

        sys.stdout.write(f"└{sep_num}┴{sep_name}┴{sep_hits}┴{sep_bytes}┴{sep_days}┴{sep_trend}┘\n")

    def _render_ip_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        data = self._aggregate_by(entries, lambda e: e['ip'], date_index, num_days)
        sorted_items = self._sort_by_key(data)

        total_ips = len(sorted_items)
        total_hits = len(entries)
        display_count = min(total_ips, self.max_rows)

        if total_ips > display_count:
            sys.stdout.write(f"{total_ips} remote IP addresses. {display_count} most frequent:\n")
        else:
            sys.stdout.write(f"{total_ips} remote IP addresses\n")

        if show_histogram:
            self._print_histogram_table(
                sorted_items[:display_count], 'IP address', total_hits,
                total_per_day, num_days
            )
        else:
            self._print_pct_table(sorted_items[:display_count], 'IP address', total_hits)

    def _render_referer_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        # Filter out "-" referers
        ref_entries = [e for e in entries if e['referer'] != '-']
        data = self._aggregate_by(ref_entries, lambda e: e['referer'], date_index, num_days)
        sorted_items = self._sort_by_key(data)

        total_refs = len(sorted_items)
        total_hits = len(entries)
        display_count = min(total_refs, self.max_rows)

        if total_refs == 0:
            sys.stdout.write("0 referrers : none\n")
            return

        if show_histogram:
            if total_refs > display_count:
                sys.stdout.write(f"{total_refs} referrers. {display_count} most frequent:\n")
            else:
                sys.stdout.write(f"{total_refs} referrers\n")

            self._print_histogram_table(
                sorted_items[:display_count], 'referrer', total_hits,
                total_per_day, num_days
            )
        else:
            if total_refs > display_count:
                sys.stdout.write(f"{total_refs} referrers. {display_count} most frequent:\n")
            else:
                sys.stdout.write(f"{total_refs} referrers.\n")

            self._print_pct_table(sorted_items[:display_count], 'referrer', total_hits)

        if self.args.changes and show_histogram:
            self._render_changes_tables(sorted_items, 'referrers', total_hits, total_per_day, num_days)

    def _render_path_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        include_resources = self.args.all

        data = self._aggregate_by(entries, lambda e: e['path'], date_index, num_days)

        total_path_count = len(data)

        if not include_resources:
            data = {k: v for k, v in data.items() if not is_resource_path(k)}

        filtered_count = len(data)
        sorted_items = self._sort_by_key(data)

        total_hits = len(entries)
        display_count = min(filtered_count, self.max_rows)

        resources_note = "" if include_resources else " (excluding resources like images, css, \netc.)"

        if show_histogram:
            if filtered_count > display_count:
                sys.stdout.write(f"{filtered_count} paths{resources_note}. {display_count} most frequent:\n")
            else:
                sys.stdout.write(f"{filtered_count} paths{resources_note}\n")

            self._print_histogram_table(
                sorted_items[:display_count], 'path', total_hits,
                total_per_day, num_days
            )
        else:
            if filtered_count > display_count:
                sys.stdout.write(f"{filtered_count} paths{resources_note}. {display_count} most frequent:\n")
            else:
                sys.stdout.write(f"{filtered_count} paths{resources_note}.\n")

            self._print_pct_table(sorted_items[:display_count], 'path', total_hits)

        if self.args.changes and show_histogram:
            self._render_changes_tables(sorted_items, 'paths', total_hits, total_per_day, num_days)

    def _render_changes_tables(self, sorted_items, item_type, total_hits, total_per_day, num_days):
        """Render 'More popular' and 'Less popular' tables."""
        half = num_days // 2

        total_first = sum(total_per_day[:half])
        total_second = sum(total_per_day[half:])

        more_items = []
        less_items = []

        for name, (hits, bts, days_v) in sorted_items:
            first = sum(days_v[:half])
            second = sum(days_v[half:])

            if total_first == 0 or total_second == 0 or first == 0:
                continue

            share_first = first / total_first
            share_second = second / total_second

            if share_second > share_first:
                # More popular
                more_items.append((name, (hits, bts, days_v)))
            elif share_second < share_first:
                # Less popular
                less_items.append((name, (hits, bts, days_v)))

        col_name = item_type.rstrip('s')  # "paths" -> "path", "referrers" -> "referrer"

        if not more_items:
            sys.stdout.write(f"More popular {item_type} : none\n")
        else:
            sys.stdout.write(f"More popular {item_type}\n")
            self._print_histogram_table(more_items, col_name, total_hits, total_per_day, num_days)

        if not less_items:
            sys.stdout.write(f"Less popular {item_type} : none\n")
        else:
            sys.stdout.write(f"Less popular {item_type}\n")
            self._print_histogram_table(less_items, col_name, total_hits, total_per_day, num_days)


def setup_arg_parser():
    """Set up the argument parser."""
    parser = argparse.ArgumentParser(
        prog='rhit',
        description=f'rhit {VERSION}\n\nRhit analyzes your nginx logs.\n\nComplete documentation at https://dystroy.org/rhit',
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument('--version', action='version', version=f'rhit {VERSION}')
    parser.add_argument('--color', default='auto', choices=['auto', 'yes', 'no'])
    parser.add_argument('-k', '--key', default='hits', metavar='KEY',
                       help='Key used in sorting and histogram, either hits or bytes')
    parser.add_argument('-l', '--length', type=int, default=1, metavar='LENGTH',
                       help='Detail level, from 0 to 6')
    parser.add_argument('-f', '--fields', metavar='FIELDS',
                       help='Comma separated list of hit fields to display')
    parser.add_argument('-c', '--changes', action='store_true',
                       help='Add tables with more popular and less popular entries')
    parser.add_argument('-d', '--date', metavar='DATE',
                       help='Filter the dates')
    parser.add_argument('-t', '--time', dest='time_filter', metavar='TIME',
                       help='Filter the time of the day')
    parser.add_argument('-i', '--ip', metavar='IP',
                       help='Remote IP filter')
    parser.add_argument('-m', '--method', metavar='METHOD',
                       help='HTTP method to filter by')
    parser.add_argument('-p', '--path', metavar='PATH',
                       help='Pattern for path filtering')
    parser.add_argument('-r', '--referer', metavar='REFERER',
                       help='Referrer filter')
    parser.add_argument('-s', '--status', metavar='STATUS',
                       help='Status filter')
    parser.add_argument('-a', '--all', action='store_true',
                       help='Show all paths, including resources')
    parser.add_argument('--no-name-check', action='store_true',
                       help='Try to open all files, whatever their names')
    parser.add_argument('-o', '--output', metavar='OUTPUT',
                       choices=['tables', 't', 'raw', 'r', 'csv', 'c', 'json', 'j'],
                       help='Output format')
    parser.add_argument('--silent-load', action='store_true',
                       help="Don't print anything during load")
    parser.add_argument('files', nargs='*', metavar='FILES',
                       help='The log file or folder to analyze')

    return parser


def main():
    parser = setup_arg_parser()
    args = parser.parse_args()

    # Determine color
    if args.color == 'auto':
        use_color = sys.stderr.isatty()
    elif args.color == 'yes':
        use_color = True
    else:
        use_color = False

    # Normalize output mode
    output_map = {'t': 'tables', 'r': 'raw', 'c': 'csv', 'j': 'json'}
    if args.output:
        args.output = output_map.get(args.output, args.output)
    else:
        args.output = 'tables'

    # Find log files
    if args.files:
        paths = args.files
    else:
        default_path = '/var/log/nginx'
        if os.path.exists(default_path):
            paths = [default_path]
        else:
            print("No nginx log found at default location, do you have nginx set up?")
            print("If necessary, provide the path to the log file(s) as argument.")
            print("More information with 'rhit --help'.")
            print(f'Error: PathNotFound("{default_path}")')
            sys.exit(0)

    # Collect files
    files = collect_files(paths, args.no_name_check)

    if not files:
        print("No log files found")
        sys.exit(1)

    n_files = len(files)

    # Display path
    if args.files:
        if len(args.files) == 1:
            display_path = str(args.files[0])
        else:
            display_path = str(args.files[0])
    else:
        display_path = '/var/log/nginx'

    # Build filters
    filters = build_filters(args)

    # Parse fields
    fields = parse_fields(args.fields)

    # Collect all entries (need total before filter for filter info)
    # Read without filters to get total
    no_filter_entries = []
    collect_raw = (args.output == 'raw')

    all_entries = []
    all_raw = []

    for i, f in enumerate(files):
        if not args.silent_load:
            print_progress(i, n_files, use_color)

        entries, raw = read_file(f, filters, collect_raw)
        all_entries.extend(entries)
        all_raw.extend(raw)

    if not args.silent_load:
        print_progress(n_files, n_files, use_color)
        sys.stderr.write("\x1b7\x1b[2K\x1b8")
        sys.stderr.flush()

    file_word = "file" if n_files == 1 else "files"

    if args.output == 'raw':
        for line in all_raw:
            sys.stdout.write(line + '\n')
        sys.stderr.write(f"I've read {n_files} {file_word} in \"{display_path}\"\n")
        return

    if args.output == 'csv':
        w = csv.writer(sys.stdout)
        w.writerow(['date', 'time', 'remote address', 'method', 'path', 'status', 'bytes sent', 'referer'])
        for e in all_entries:
            w.writerow([
                e['date_str'], e['time_str'], e['ip'], e['method'],
                e['path'], str(e['status']), str(e['bytes']), e['referer']
            ])
        sys.stderr.write(f"I've read {n_files} {file_word} in \"{display_path}\"\n")
        return

    if args.output == 'json':
        sys.stdout.write('[\n')
        for i, e in enumerate(all_entries):
            comma = ',' if i < len(all_entries) - 1 else ''
            sys.stdout.write(f'  {{\n')
            sys.stdout.write(f'    "date": "{e["date_str"]}",\n')
            sys.stdout.write(f'    "time": "{e["time_str"]}",\n')
            sys.stdout.write(f'    "remote_addr": "{e["ip"]}",\n')
            sys.stdout.write(f'    "method": "{e["method"]}",\n')
            sys.stdout.write(f'    "path": "{e["path"]}",\n')
            sys.stdout.write(f'    "status": "{e["status"]}",\n')
            sys.stdout.write(f'    "bytes_sent": {e["bytes"]},\n')
            sys.stdout.write(f'    "referer": "{e["referer"]}"\n')
            sys.stdout.write(f'  }}{comma}\n')
        sys.stdout.write(']\n')
        sys.stderr.write(f"I've read {n_files} {file_word} in \"{display_path}\"\n")
        return

    # Tables output
    sys.stderr.write(f"I've read {n_files} {file_word} in \"{display_path}\"\n")

    renderer = TableRenderer(args, use_color)
    renderer.render_all(all_entries, fields, filters, n_files, display_path, 0)


if __name__ == '__main__':
    main()
