    status = int(m.group(10))
    bytes_str = m.group(11)
    bytes_sent = int(bytes_str) if bytes_str != '-' else 0
    referer = m.group(12)

    try:
        d = date(year, month, day)
        t = time(hour, minute, second)
    except ValueError:
        return None

