class StatusFilter:
    def __init__(self, spec):
        self.spec = spec
        self.positive = []
        self.negative = []

        for part in spec.split(','):
            part = part.strip()
            negate = part.startswith('!')
            if negate:
                part = part[1:]

            r = self._parse_range(part)
            if negate:
                self.negative.append(r)
            else:
                self.positive.append(r)

    def _parse_range(self, s):
        s = s.strip()
        if re.match(r'^\d+$', s):
            v = int(s)
            return (v, v)
        if re.match(r'^[1-9]xx$', s, re.I):
            cls = int(s[0]) * 100
            return (cls, cls + 99)
        if re.match(r'^\d+-\d+$', s):
            a, b = s.split('-')
            return (int(a), int(b))
        return (0, 0)

    def matches(self, status):
        # Check negatives first
        for lo, hi in self.negative:
            if lo <= status <= hi:
                return False

        if not self.positive:
            return True

        for lo, hi in self.positive:
            if lo <= status <= hi:
                return True

        return False


class PathFilter:
    def __init__(self, spec):
