            if negate:
                part = part[1:]

            try:
                r = re.compile(part)
                self.clauses.append((negate, r, None))
            except re.error:
                self.clauses.append((negate, None, part))

    def matches(self, s):
        for negate, regex, plain in self.clauses:
            if regex:
                result = bool(regex.search(s))
            else:
                result = (plain or '') in s

            if negate:
                result = not result

            if not result:
