            self.prefix = None
        else:
            self.exact = s
            self.regex = None
            self.prefix = None

    def matches(self, entry):
        ip = entry['ip']
        if self.exact:
            result = ip == self.exact
        elif self.prefix:
            result = ip.startswith(self.prefix)
        elif self.regex:
