def format_bytes(n):
    """Format byte count in human-readable form."""
    if n >= 1_000_000_000:
        v = n / 1_000_000_000
        return f"{v:.1f}G"
    elif n >= 1_000_000:
        v = n / 1_000_000
        return f"{v:.1f}M"
    elif n >= 1_000:
        return f"{n // 1000}K"
    else:
