def parse_log_line(line):
    """Parse an nginx combined log format line."""
    # Format: ip - user [date:time +tz] "METHOD path HTTP/x.x" status bytes "referer" "agent"
    # We use a regex for reliable parsing
    pattern = r'^(\S+) \S+ \S+ \[(\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+) [^\]]+\] "([A-Z]+) (\S+)[^"]*" (\d+) (\d+|-) "([^"]*)"'
    m = re.match(pattern, line)
    if not m:
        return None

    ip = m.group(1)
    day = int(m.group(2))
    month = MONTHS.get(m.group(3), 1)
    year = int(m.group(4))
    hour = int(m.group(5))
    minute = int(m.group(6))
    second = int(m.group(7))
    method = m.group(8)
    path = m.group(9)
    status = int(m.group(10))
    bytes_str = m.group(11)
    bytes_sent = int(bytes_str) if bytes_str != '-' else 0
    referer = m.group(12)

    try:
        d = date(year, month, day)
        t = time(hour, minute, second)
    except ValueError:
        return None

    return {
        'ip': ip,
        'date': d,
        'time': t,
        'method': method,
        'path': path,
        'status': status,
        'bytes': bytes_sent,
        'referer': referer,
        'date_str': f"{year}/{month:02d}/{day:02d}",
        'time_str': f"{hour:02d}:{minute:02d}:{second:02d}",
        'raw': line,
    }


class StatusFilter:
    def __init__(self, spec):
        self.spec = spec
        self.positive = []
        self.negative = []

        for part in spec.split(','):
            part = part.strip()
            negate = part.startswith('!')
            if negate:
                part = part[1:]

            r = self._parse_range(part)
            if negate:
                self.negative.append(r)
            else:
                self.positive.append(r)

    def _parse_range(self, s):
        s = s.strip()
        if re.match(r'^\d+$', s):
            v = int(s)
            return (v, v)
        if re.match(r'^[1-9]xx$', s, re.I):
            cls = int(s[0]) * 100
            return (cls, cls + 99)
        if re.match(r'^\d+-\d+$', s):
            a, b = s.split('-')
            return (int(a), int(b))
        return (0, 0)

    def matches(self, status):
        # Check negatives first
        for lo, hi in self.negative:
            if lo <= status <= hi:
                return False

        if not self.positive:
            return True

        for lo, hi in self.positive:
            if lo <= status <= hi:
                return True

        return False


class PathFilter:
    def __init__(self, spec):
        self.spec = spec
        self.clauses = []

        # Parse comma-separated clauses with potential | & operators
        # Simple approach: split by comma for AND logic
        for part in spec.split(','):
            part = part.strip()
            if not part:
                continue
            negate = part.startswith('!')
            if negate:
                part = part[1:]

            try:
                r = re.compile(part)
                self.clauses.append((negate, r, None))
            except re.error:
                self.clauses.append((negate, None, part))

    def matches(self, s):
        for negate, regex, plain in self.clauses:
            if regex:
                result = bool(regex.search(s))
            else:
                result = (plain or '') in s

            if negate:
                result = not result

            if not result:
                return False

        return True


class DateFilter:
    def __init__(self, spec):
        self.spec = spec
        self._parse(spec)

    def _parse(self, s):
        s = s.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]

        self.after = s.startswith('>')
        self.before = s.startswith('<')
        if self.after or self.before:
            s = s[1:]

        # Try to parse as range
        self.range_from = None
        self.range_to = None

        # Check for range separator (dash between two date specs)
        # Format: YYYY/MM/DD-YYYY/MM/DD or with T for time
        range_match = re.match(r'^(\d{4}(?:/\d{1,2}(?:/\d{1,2}(?:T\d{2}:\d{2}(?::\d{2})?)?)?)?)[-](\d{4}(?:/\d{1,2}(?:/\d{1,2}(?:T\d{2}:\d{2}(?::\d{2})?)?)?)?)$', s)

        if range_match:
            self.range_from = self._parse_date_start(range_match.group(1))
            self.range_to = self._parse_date_end(range_match.group(2))
        else:
            self.range_from = self._parse_date_start(s)
            self.range_to = self._parse_date_end(s)

    def _parse_date_start(self, s):
        # Parse date spec and return the START of the period
        parts = s.split('T')[0].split('/')
        if not parts or not re.match(r'^\d{4}$', parts[0]):
            return date.min

        year = int(parts[0])
        if len(parts) == 1:
            return date(year, 1, 1)
        month = int(parts[1])
        if len(parts) == 2:
            return date(year, month, 1)
        day = int(parts[2])
        try:
            return date(year, month, day)
        except ValueError:
            return date.min

    def _parse_date_end(self, s):
        # Parse date spec and return the END of the period
        parts = s.split('T')[0].split('/')
        if not parts or not re.match(r'^\d{4}$', parts[0]):
            return date.max

        year = int(parts[0])
        if len(parts) == 1:
            # Last day of year
            return date(year, 12, 31)
        month = int(parts[1])
        if len(parts) == 2:
            # Last day of month
            import calendar
            last_day = calendar.monthrange(year, month)[1]
            return date(year, month, last_day)
        day = int(parts[2])
        try:
            return date(year, month, day)
        except ValueError:
            return date.max

    def matches(self, entry):
        d = entry['date']

        if self.after:
            result = d > self.range_from
        elif self.before:
            result = d < self.range_to
        else:
            result = self.range_from <= d <= self.range_to

        return not result if self.negate else result


class TimeFilter:
    def __init__(self, spec):
        self.spec = spec
        s = spec.strip()
        self.after = s.startswith('>')
        self.before = s.startswith('<')
        if self.after or self.before:
            s = s[1:]
        parts = s.split(':')
        h = int(parts[0]) if parts else 0
        m = int(parts[1]) if len(parts) > 1 else 0
        sec = int(parts[2]) if len(parts) > 2 else 0
        self.t = time(h, m, sec)

    def matches(self, entry):
        t = entry['time']
        if self.after:
            return t > self.t
        elif self.before:
            return t < self.t
        return t == self.t


class IpFilter:
    def __init__(self, spec):
        self.spec = spec
        s = spec.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]

        if s.startswith('^'):
            self.prefix = s[1:]
            self.regex = None
            self.exact = None
        elif any(c in s for c in '.*+?[](){}|\\^$'):
            try:
                self.regex = re.compile(s)
            except:
                self.regex = None
            self.exact = None
            self.prefix = None
        else:
            self.exact = s
            self.regex = None
            self.prefix = None

    def matches(self, entry):
        ip = entry['ip']
        if self.exact:
            result = ip == self.exact
        elif self.prefix:
            result = ip.startswith(self.prefix)
        elif self.regex:
            result = bool(self.regex.search(ip))
        else:
            result = True
        return not result if self.negate else result


class MethodFilter:
    def __init__(self, spec):
        self.spec = spec
        s = spec.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]
        self.is_other = s.lower() == 'other'
        self.is_none = s.lower() == 'none'
        self.method = s.upper()
        self.STANDARD = {'GET', 'POST', 'PUT', 'DELETE', 'HEAD', 'OPTIONS', 'PATCH', 'CONNECT', 'TRACE'}

    def matches(self, entry):
        m = entry['method']
        if self.is_other:
            result = m not in self.STANDARD
        elif self.is_none:
            result = not m
        else:
            result = m.upper() == self.method
        return not result if self.negate else result


def parse_fields(spec, default_fields=None, all_fields=None):
    if default_fields is None:
        default_fields = ['date', 'status', 'referer', 'path']
    if all_fields is None:
        all_fields = ['date', 'time', 'method', 'status', 'ip', 'referer', 'path']

    if spec is None:
        return default_fields[:]

    FIELD_MAP = {
        'date': 'date', 'd': 'date',
        'time': 'time', 
        'method': 'method', 'm': 'method',
        'status': 'status', 's': 'status',
        'ip': 'ip', 'i': 'ip',
        'ref': 'referer', 'referer': 'referer', 'referrer': 'referer', 'r': 'referer',
        'path': 'path', 'p': 'path',
        'all': None, 'a': None,
    }

    spec = spec.strip()

    # Find first operator position
    first_op = -1
    for i, c in enumerate(spec):
        if c in '+-':
            first_op = i
            break

    if first_op == -1:
        # No operators
        if spec.lower() in ('all', 'a'):
            return all_fields[:]
        # Simple field list
        fields = []
        for part in spec.split(','):
            part = part.strip().lower()
            if part in FIELD_MAP:
                f = FIELD_MAP[part]
                if f and f not in fields:
                    fields.append(f)
        return fields

    if first_op == 0:
        base = default_fields[:]
    else:
        base_spec = spec[:first_op].strip().lower()
        if base_spec in ('all', 'a'):
            base = all_fields[:]
        else:
            base = []
            for part in base_spec.split(','):
                part = part.strip().lower()
                if part in FIELD_MAP:
                    f = FIELD_MAP[part]
                    if f and f not in base:
                        base.append(f)

    # Parse operators
    rest = spec[first_op:]
    i = 0
    while i < len(rest):
        op = rest[i]
        i += 1
        # Find end of field name
        j = i
        while j < len(rest) and rest[j] not in '+-':
            j += 1
        field_name = rest[i:j].strip().lower()
        i = j

        if field_name in FIELD_MAP:
            f = FIELD_MAP[field_name]
            if f:
                if op == '+':
                    base = [x for x in base if x != f]
                    base.append(f)
                elif op == '-':
                    base = [x for x in base if x != f]

    return base


def collect_files(paths, no_name_check=False):
    """Collect all log files from given paths."""
    files = []
    for path in paths:
        p = Path(path)
        if p.is_file():
            if no_name_check or is_log_filename(p.name):
                files.append(p)
        elif p.is_dir():
            dir_files = []
            for f in p.iterdir():
                if f.is_file() and (no_name_check or is_log_filename(f.name)):
                    dir_files.append(f)
            dir_files.sort()
            files.extend(dir_files)
    return files


def is_log_filename(name):
    return name.startswith('access') or ('.log' in name and not name.startswith('.'))


def read_file(path, filters, collect_raw=False):
    """Read a log file and return matching entries."""
    entries = []
    raw_lines = []

    try:
        if str(path).endswith('.gz'):
            f = gzip.open(path, 'rt', encoding='utf-8', errors='replace')
        else:
            f = open(path, 'r', encoding='utf-8', errors='replace')

        with f:
            for line in f:
                line = line.rstrip('\n\r')
                if not line:
                    continue
                entry = parse_log_line(line)
                if entry is None:
                    continue
                if matches_filters(entry, filters):
                    if collect_raw:
                        raw_lines.append(line)
                    entries.append(entry)
    except Exception as e:
        pass

    return entries, raw_lines


def matches_filters(entry, filters):
    for f in filters:
        if not f.matches(entry):
            return False
    return True


def build_filters(args):
    """Build list of filter objects from args."""
    filters = []
    if args.date:
        filters.append(DateFilter(args.date))
    if hasattr(args, 'time_filter') and args.time_filter:
        filters.append(TimeFilter(args.time_filter))
    if args.ip:
        filters.append(IpFilter(args.ip))
    if args.method:
        filters.append(MethodFilter(args.method))
    if args.path:
        filters.append(PathFilter(args.path))
    if args.referer:
        filters.append(PathFilter(args.referer))  # Note: using PathFilter for referer too
    if args.status:
        filters.append(StatusFilter(args.status))
    return filters


def print_progress(current, total, use_color, force_erase=False):
    """Print a progress bar to stderr."""
    width = 40
    filled = current * width // total if total > 0 else 0

    bar = '█' * filled + ' ' * (width - filled)

    sys.stderr.write(f"\x1b7\x1b[2K{current:3} / {total} ")
    if use_color:
        sys.stderr.write(f"\x1b[48;5;5m\x1b[38;5;11m{bar}\x1b[49m\x1b[39m")
    else:
        sys.stderr.write(bar)
    sys.stderr.write("\x1b8")
    sys.stderr.flush()


def get_date_range(min_date, max_date):
    """Return sorted list of all dates between min and max inclusive."""
    dates = []
    d = min_date
    while d <= max_date:
        dates.append(d)
        d += timedelta(days=1)
    return dates


def compute_trend(days_values, total_per_day):
    """Compute trend string (➚, ➘, etc.) based on share change."""
    n = len(days_values)
    if n < 4:
        return '     '

    half = n // 2

    total_first = sum(total_per_day[:half])
    total_second = sum(total_per_day[half:])

    if total_first == 0 or total_second == 0:
        return '     '

    first = sum(days_values[:half])
    second = sum(days_values[half:])

    if first == 0 and second == 0:
        return '     '

    if first == 0:
        # New entry
        return '  ➚  '

    share_first = first / total_first
    share_second = second / total_second

    diff = share_second - share_first

    if share_first > 0:
        ratio = share_second / share_first if share_second > share_first else share_first / share_second
    else:
        ratio = float('inf')

    significance = abs(diff) * ratio

    # Use chi-square-like test
    # Expected in second half if no change:
    exp_second = first * total_second / total_first
    if exp_second > 0:
        chi2 = (second - exp_second) ** 2 / exp_second
    else:
        chi2 = 0

    if diff > 0:
        # Increasing
        if chi2 >= 10 and ratio >= 3.0:
            return ' ➚ ➚ '
        elif chi2 >= 3.5 or (ratio >= 2.0 and abs(diff) >= 0.15):
            return '  ➚  '
        else:
            return '     '
    elif diff < 0:
        # Decreasing
        if chi2 >= 10 and ratio >= 3.0:
            return ' ➘ ➘ '
        elif chi2 >= 3.5 or (ratio >= 2.0 and abs(diff) >= 0.15):
            return '  ➘  '
        else:
            return '     '
    else:
        return '     '


class TableRenderer:
    """Renders tables similar to rhit output."""

