    def _print_wrapped(self, text, width):
        """Print text wrapped at width chars."""
        while len(text) > width:
            # Find last space before width
            pos = text.rfind(' ', 0, width)
            if pos < 0:
                pos = width
            sys.stdout.write(text[:pos] + '\n')
            text = text[pos:].lstrip()
        sys.stdout.write(text)

    def _render_date_table(self, entries, dates, date_index, num_days):
        hits_per_day = [0] * num_days
        bytes_per_day = [0] * num_days

        for e in entries:
            idx = date_index.get(e['date'])
            if idx is not None:
                hits_per_day[idx] += 1
                bytes_per_day[idx] += e['bytes']

        key_vals = bytes_per_day if self.key_is_bytes else hits_per_day
        max_val = max(key_vals) if key_vals else 1

        bar_width = 20
        max_str = format_bytes(max_val)
        inner = f"0{' ' * (bar_width - 1 - len(max_str))}{max_str}"

        sys.stdout.write(f"┌──────────┬────┬─────┬{'─' * (bar_width + 2)}┐\n")
        sys.stdout.write(f"│   date   │hits│bytes│{inner}│\n")
        sys.stdout.write(f"├──────────┼────┼─────┼{'─' * (bar_width + 2)}┤\n")

        for i, d in enumerate(dates):
            hits = hits_per_day[i]
            bts = bytes_per_day[i]
            key_v = bts if self.key_is_bytes else hits
            bar = make_bar(key_v, max_val, bar_width)
            sys.stdout.write(f"│{d.year}/{d.month:02d}/{d.day:02d}│{hits:4}│{format_bytes(bts):>5}│{bar}│\n")

        sys.stdout.write(f"└──────────┴────┴─────┴{'─' * (bar_width + 2)}┘\n")

    def _render_time_table(self, entries, num_days):
        hits_per_hour = [0] * 24
        bytes_per_hour = [0] * 24

        for e in entries:
            h = e['time'].hour
            hits_per_hour[h] += 1
            bytes_per_hour[h] += e['bytes']

        key_vals = bytes_per_hour if self.key_is_bytes else hits_per_hour
        max_val = max(key_vals) if any(key_vals) else 1

        bar_width = 20
        max_str = format_bytes(max_val)
        inner = f"0{' ' * (bar_width - 1 - len(max_str))}{max_str}"

        sys.stdout.write(f"┌────┬────┬─────┬{'─' * (bar_width + 2)}┐\n")
        sys.stdout.write(f"│hour│hits│bytes│{inner}│\n")
        sys.stdout.write(f"├────┼────┼─────┼{'─' * (bar_width + 2)}┤\n")

        for h in range(24):
            hits = hits_per_hour[h]
            bts = bytes_per_hour[h]
            key_v = bts if self.key_is_bytes else hits
            bar = make_bar(key_v, max_val, bar_width)
            sys.stdout.write(f"│{h:<4}│{hits:^4}│{format_bytes(bts):>5}│{bar}│\n")

        sys.stdout.write(f"└────┴────┴─────┴{'─' * (bar_width + 2)}┘\n")

    def _aggregate_by(self, entries, key_fn, date_index, num_days):
        """Aggregate entries by a key function."""
        data = defaultdict(lambda: [0, 0, [0] * num_days])

        for e in entries:
            k = key_fn(e)
            d = data[k]
            d[0] += 1
            d[1] += e['bytes']
            idx = date_index.get(e['date'])
            if idx is not None:
                d[2][idx] += 1

        return data

    def _sort_by_key(self, data_dict):
        """Sort dict items by key (hits or bytes)."""
        items = list(data_dict.items())
        if self.key_is_bytes:
            items.sort(key=lambda x: (-x[1][1], x[0]))
        else:
            items.sort(key=lambda x: (-x[1][0], x[0]))
        return items

    def _render_method_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        data = self._aggregate_by(entries, lambda e: e['method'], date_index, num_days)
        sorted_items = self._sort_by_key(data)

        total_hits = len(entries)

        sys.stdout.write("methods\n")

        if show_histogram:
            self._print_histogram_table(
                sorted_items, 'method', total_hits, total_per_day, num_days,
                center_col=True
            )
        else:
            self._print_pct_table(sorted_items, 'method', total_hits)

    def _render_status_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        data = self._aggregate_by(entries, lambda e: str(e['status']), date_index, num_days)

        # Sort numerically
        sorted_items = list(data.items())
        if self.key_is_bytes:
            sorted_items.sort(key=lambda x: (-x[1][1], int(x[0])))
        else:
            sorted_items.sort(key=lambda x: (-x[1][0], int(x[0])))

        total_hits = len(entries)
        n_status = len(sorted_items)

        if self.args.length == 0:
            # Show class summary
            self._render_status_class_summary(entries, total_hits)
            return

        if show_histogram:
            sys.stdout.write("HTTP status codes\n")
            # Status table uses different format
            self._print_status_histogram_table(sorted_items, total_hits, total_per_day, num_days)
        else:
            sys.stdout.write(f"{n_status} HTTP status codes.\n")
            self._print_status_pct_table(sorted_items, total_hits)

    def _render_status_class_summary(self, entries, total_hits):
        classes = defaultdict(int)
        for e in entries:
            cls = e['status'] // 100
            classes[cls] += 1

        cols = []
        for cls in [1, 2, 3, 4, 5]:
            if classes[cls] > 0:
                pct = classes[cls] / total_hits * 100
                cols.append((f"{cls}xx", f"{pct:.1f}%"))

        if not cols:
            return

        sys.stdout.write("HTTP status codes:\n")
        sep = '┬'.join(['─────'] * len(cols))
        sys.stdout.write(f"┌{sep}┐\n")
        header = '│'.join(f" {h} " for h, _ in cols)
        sys.stdout.write(f"│{header}│\n")
        sep2 = '┼'.join(['─────'] * len(cols))
        sys.stdout.write(f"├{sep2}┤\n")
        values = '│'.join(f"{v:>5}" for _, v in cols)
        sys.stdout.write(f"│{values}│\n")
        sep3 = '┴'.join(['─────'] * len(cols))
        sys.stdout.write(f"└{sep3}┘\n")

    def _print_status_histogram_table(self, sorted_items, total_hits, total_per_day, num_days):
        days_w = num_days
        trend_w = 5
        status_w = 6
        hits_w = 4
        pct_w = 5 + (1 if total_hits >= 100 else 0)  # adjust for 100%

        # Determine % column width
        max_pct_str = f"{max(v[0] for _, v in sorted_items) / total_hits * 100:.1f}%"
        pct_w = max(5, len(max_pct_str))

        bytes_w = 5

        sys.stdout.write(f"┌{'─'*status_w}┬{'─'*hits_w}┬{'─'*pct_w}┬{'─'*bytes_w}┬{'─'*days_w}┬{'─'*trend_w}┐\n")
        days_hdr = f"{'days':^{days_w}}"
        sys.stdout.write(f"│{'status':^{status_w}}│{'hits':^{hits_w}}│{'%':^{pct_w}}│{'bytes':^{bytes_w}}│{days_hdr}│{'trend':^{trend_w}}│\n")
        sys.stdout.write(f"├{'─'*status_w}┼{'─'*hits_w}┼{'─'*pct_w}┼{'─'*bytes_w}┼{'─'*days_w}┼{'─'*trend_w}┤\n")

        max_key = max((v[1] if self.key_is_bytes else v[0]) for _, v in sorted_items) if sorted_items else 1

        for status_str, (hits, bts, days_v) in sorted_items:
            pct = hits / total_hits * 100
            days_bar = make_mini_bar(days_v, num_days)
            trend = compute_trend(days_v, total_per_day)

            sys.stdout.write(f"│ {int(status_str):^4} │{hits:>{hits_w}}│{pct:.1f}%│{format_bytes(bts):>{bytes_w}}│{days_bar}│{trend}│\n")

        sys.stdout.write(f"└{'─'*status_w}┴{'─'*hits_w}┴{'─'*pct_w}┴{'─'*bytes_w}┴{'─'*days_w}┴{'─'*trend_w}┘\n")

    def _print_status_pct_table(self, sorted_items, total_hits):
        # Show as numbered list with %
        n = len(sorted_items)

        max_pct_str = f"{100.0:.1f}%"
        pct_w = max(5, len(max_pct_str))

        sys.stdout.write(f"┌───┬──────┬────┬{'─'*pct_w}┬─────┐\n")
        sys.stdout.write(f"│ # │status│hits│{'%':^{pct_w}}│bytes│\n")
        sys.stdout.write(f"├───┼──────┼────┼{'─'*pct_w}┼─────┤\n")

        for i, (status_str, (hits, bts, _)) in enumerate(sorted_items[:self.max_rows]):
            pct = hits / total_hits * 100
            pct_str = f"{pct:.1f}%"
            sys.stdout.write(f"│{i+1:3}│{status_str:<6}│{hits:4}│{pct_str:>{pct_w}}│{format_bytes(bts):>5}│\n")

        sys.stdout.write(f"└───┴──────┴────┴{'─'*pct_w}┴─────┘\n")

    def _print_pct_table(self, sorted_items, col_name, total_hits):
        """Print a simple numbered table with % column."""
        max_name_len = max((len(k) for k, _ in sorted_items), default=len(col_name))

        target = self.TARGET_WIDTH
        fixed = 3 + 1 + 4 + 1 + 5 + 1 + 5 + 1 + 7  # # + hits + % + bytes + seps
        name_w = max(len(col_name), min(max_name_len, target - fixed))

        sep_num = '─' * 3
        sep_name = '─' * name_w
        sep_hits = '─' * 4
        sep_pct = '─' * 5
        sep_bytes = '─' * 5

        sys.stdout.write(f"┌{sep_num}┬{sep_name}┬{sep_hits}┬{sep_pct}┬{sep_bytes}┐\n")
        sys.stdout.write(f"│ # │{col_name:<{name_w}}│hits│  %  │bytes│\n")
        sys.stdout.write(f"├{sep_num}┼{sep_name}┼{sep_hits}┼{sep_pct}┼{sep_bytes}┤\n")

        for i, (name, (hits, bts, _)) in enumerate(sorted_items[:self.max_rows]):
            pct = hits / total_hits * 100
            pct_str = f"{pct:.1f}%"

            if len(name) <= name_w:
                sys.stdout.write(f"│{i+1:3}│{name:<{name_w}}│{hits:4}│{pct_str:>5}│{format_bytes(bts):>5}│\n")
            else:
                # Wrap
                chunks = [name[j:j+name_w] for j in range(0, len(name), name_w)]
                for ci, chunk in enumerate(chunks):
                    padded = f"{chunk:<{name_w}}"
                    if ci == 0:
                        sys.stdout.write(f"│{i+1:3}│{padded}│{hits:4}│{pct_str:>5}│{format_bytes(bts):>5}│\n")
                    else:
                        sys.stdout.write(f"│   │{padded}│    │     │     │\n")

        sys.stdout.write(f"└{sep_num}┴{sep_name}┴{sep_hits}┴{sep_pct}┴{sep_bytes}┘\n")

    def _print_histogram_table(self, sorted_items, col_name, total_hits, total_per_day, num_days,
                                center_col=False, header_prefix=''):
        """Print a table with days histogram."""
        max_name_len = max((len(k) for k, _ in sorted_items), default=len(col_name))

        target = self.TARGET_WIDTH
        # Fixed: # (3) + hits (4) + bytes (5) + days (num_days) + trend (5) + 7 seps
        fixed = 3 + 4 + 5 + num_days + 5 + 7
        name_w = max(len(col_name), min(max_name_len, target - fixed))

        days_w = num_days
        trend_w = 5

        sep_num = '─' * 3
        sep_name = '─' * name_w
        sep_hits = '─' * 4
        sep_bytes = '─' * 5
        sep_days = '─' * days_w
        sep_trend = '─' * trend_w

        sys.stdout.write(f"┌{sep_num}┬{sep_name}┬{sep_hits}┬{sep_bytes}┬{sep_days}┬{sep_trend}┐\n")
        days_hdr = f"{'days':^{days_w}}"
        if center_col:
            sys.stdout.write(f"│ # │{col_name:^{name_w}}│hits│bytes│{days_hdr}│trend│\n")
        else:
            sys.stdout.write(f"│ # │{col_name:<{name_w}}│hits│bytes│{days_hdr}│trend│\n")
        sys.stdout.write(f"├{sep_num}┼{sep_name}┼{sep_hits}┼{sep_bytes}┼{sep_days}┼{sep_trend}┤\n")

        for i, (name, (hits, bts, days_v)) in enumerate(sorted_items[:self.max_rows]):
            days_bar = make_mini_bar(days_v, days_w)
            trend = compute_trend(days_v, total_per_day)

            if len(name) <= name_w:
                if center_col:
                    padded = f"{name:^{name_w}}"
                else:
                    padded = f"{name:<{name_w}}"
                sys.stdout.write(f"│{i+1:3}│{padded}│{hits:4}│{format_bytes(bts):>5}│{days_bar}│{trend}│\n")
            else:
                # Wrap
                chunks = [name[j:j+name_w] for j in range(0, len(name), name_w)]
                days_bar_chars = list(days_bar)
                for ci, chunk in enumerate(chunks):
                    # Days bar wraps too
                    d_start = ci * name_w
                    d_end = d_start + days_w
                    # Actually the days bar stays intact per row but the name wraps
                    if ci == 0:
                        padded = f"{chunk:<{name_w}}"
                        sys.stdout.write(f"│{i+1:3}│{padded}│{hits:4}│{format_bytes(bts):>5}│{days_bar}│{trend}│\n")
                    else:
                        padded = f"{chunk:<{name_w}}"
                        # Continuation rows for days bar
                        # When name wraps, the days bar also needs to show continuation
                        d_bar_cont = ' ' * days_w
                        # Handle wrapped days bar
                        sys.stdout.write(f"│   │{padded}│    │     │{d_bar_cont}│     │\n")

        sys.stdout.write(f"└{sep_num}┴{sep_name}┴{sep_hits}┴{sep_bytes}┴{sep_days}┴{sep_trend}┘\n")

    def _render_ip_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        data = self._aggregate_by(entries, lambda e: e['ip'], date_index, num_days)
        sorted_items = self._sort_by_key(data)

        total_ips = len(sorted_items)
        total_hits = len(entries)
        display_count = min(total_ips, self.max_rows)

        if total_ips > display_count:
            sys.stdout.write(f"{total_ips} remote IP addresses. {display_count} most frequent:\n")
        else:
            sys.stdout.write(f"{total_ips} remote IP addresses\n")

        if show_histogram:
            self._print_histogram_table(
                sorted_items[:display_count], 'IP address', total_hits,
                total_per_day, num_days
            )
        else:
            self._print_pct_table(sorted_items[:display_count], 'IP address', total_hits)

    def _render_referer_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        # Filter out "-" referers
        ref_entries = [e for e in entries if e['referer'] != '-']
        data = self._aggregate_by(ref_entries, lambda e: e['referer'], date_index, num_days)
        sorted_items = self._sort_by_key(data)

        total_refs = len(sorted_items)
        total_hits = len(entries)
        display_count = min(total_refs, self.max_rows)

        if total_refs == 0:
            sys.stdout.write("0 referrers : none\n")
            return

        if show_histogram:
            if total_refs > display_count:
                sys.stdout.write(f"{total_refs} referrers. {display_count} most frequent:\n")
            else:
                sys.stdout.write(f"{total_refs} referrers\n")

            self._print_histogram_table(
                sorted_items[:display_count], 'referrer', total_hits,
                total_per_day, num_days
            )
        else:
            if total_refs > display_count:
                sys.stdout.write(f"{total_refs} referrers. {display_count} most frequent:\n")
            else:
                sys.stdout.write(f"{total_refs} referrers.\n")

            self._print_pct_table(sorted_items[:display_count], 'referrer', total_hits)

        if self.args.changes and show_histogram:
            self._render_changes_tables(sorted_items, 'referrers', total_hits, total_per_day, num_days)

    def _render_path_table(self, entries, dates, date_index, num_days, total_per_day, show_histogram):
        include_resources = self.args.all

        data = self._aggregate_by(entries, lambda e: e['path'], date_index, num_days)

        total_path_count = len(data)

        if not include_resources:
            data = {k: v for k, v in data.items() if not is_resource_path(k)}

        filtered_count = len(data)
        sorted_items = self._sort_by_key(data)

        total_hits = len(entries)
        display_count = min(filtered_count, self.max_rows)

        resources_note = "" if include_resources else " (excluding resources like images, css, \netc.)"

        if show_histogram:
            if filtered_count > display_count:
                sys.stdout.write(f"{filtered_count} paths{resources_note}. {display_count} most frequent:\n")
            else:
                sys.stdout.write(f"{filtered_count} paths{resources_note}\n")

            self._print_histogram_table(
                sorted_items[:display_count], 'path', total_hits,
                total_per_day, num_days
            )
        else:
            if filtered_count > display_count:
                sys.stdout.write(f"{filtered_count} paths{resources_note}. {display_count} most frequent:\n")
            else:
                sys.stdout.write(f"{filtered_count} paths{resources_note}.\n")

            self._print_pct_table(sorted_items[:display_count], 'path', total_hits)

        if self.args.changes and show_histogram:
            self._render_changes_tables(sorted_items, 'paths', total_hits, total_per_day, num_days)

    def _render_changes_tables(self, sorted_items, item_type, total_hits, total_per_day, num_days):
        """Render 'More popular' and 'Less popular' tables."""
        half = num_days // 2

        total_first = sum(total_per_day[:half])
        total_second = sum(total_per_day[half:])

        more_items = []
        less_items = []

        for name, (hits, bts, days_v) in sorted_items:
            first = sum(days_v[:half])
            second = sum(days_v[half:])

            if total_first == 0 or total_second == 0 or first == 0:
                continue

            share_first = first / total_first
            share_second = second / total_second

            if share_second > share_first:
                # More popular
                more_items.append((name, (hits, bts, days_v)))
            elif share_second < share_first:
                # Less popular
                less_items.append((name, (hits, bts, days_v)))

        col_name = item_type.rstrip('s')  # "paths" -> "path", "referrers" -> "referrer"

        if not more_items:
            sys.stdout.write(f"More popular {item_type} : none\n")
        else:
            sys.stdout.write(f"More popular {item_type}\n")
            self._print_histogram_table(more_items, col_name, total_hits, total_per_day, num_days)

        if not less_items:
            sys.stdout.write(f"Less popular {item_type} : none\n")
        else:
            sys.stdout.write(f"Less popular {item_type}\n")
            self._print_histogram_table(less_items, col_name, total_hits, total_per_day, num_days)


def setup_arg_parser():
    """Set up the argument parser."""
    parser = argparse.ArgumentParser(
        prog='rhit',
        description=f'rhit {VERSION}\n\nRhit analyzes your nginx logs.\n\nComplete documentation at https://dystroy.org/rhit',
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument('--version', action='version', version=f'rhit {VERSION}')
    parser.add_argument('--color', default='auto', choices=['auto', 'yes', 'no'])
    parser.add_argument('-k', '--key', default='hits', metavar='KEY',
                       help='Key used in sorting and histogram, either hits or bytes')
    parser.add_argument('-l', '--length', type=int, default=1, metavar='LENGTH',
                       help='Detail level, from 0 to 6')
    parser.add_argument('-f', '--fields', metavar='FIELDS',
                       help='Comma separated list of hit fields to display')
    parser.add_argument('-c', '--changes', action='store_true',
                       help='Add tables with more popular and less popular entries')
    parser.add_argument('-d', '--date', metavar='DATE',
                       help='Filter the dates')
    parser.add_argument('-t', '--time', dest='time_filter', metavar='TIME',
                       help='Filter the time of the day')
    parser.add_argument('-i', '--ip', metavar='IP',
                       help='Remote IP filter')
    parser.add_argument('-m', '--method', metavar='METHOD',
                       help='HTTP method to filter by')
    parser.add_argument('-p', '--path', metavar='PATH',
                       help='Pattern for path filtering')
    parser.add_argument('-r', '--referer', metavar='REFERER',
                       help='Referrer filter')
    parser.add_argument('-s', '--status', metavar='STATUS',
                       help='Status filter')
    parser.add_argument('-a', '--all', action='store_true',
                       help='Show all paths, including resources')
    parser.add_argument('--no-name-check', action='store_true',
                       help='Try to open all files, whatever their names')
    parser.add_argument('-o', '--output', metavar='OUTPUT',
                       choices=['tables', 't', 'raw', 'r', 'csv', 'c', 'json', 'j'],
                       help='Output format')
    parser.add_argument('--silent-load', action='store_true',
                       help="Don't print anything during load")
    parser.add_argument('files', nargs='*', metavar='FILES',
                       help='The log file or folder to analyze')

    return parser


def main():
    parser = setup_arg_parser()
    args = parser.parse_args()

    # Determine color
    if args.color == 'auto':
        use_color = sys.stderr.isatty()
    elif args.color == 'yes':
        use_color = True
    else:
        use_color = False

    # Normalize output mode
    output_map = {'t': 'tables', 'r': 'raw', 'c': 'csv', 'j': 'json'}
    if args.output:
        args.output = output_map.get(args.output, args.output)
    else:
        args.output = 'tables'

    # Find log files
    if args.files:
        paths = args.files
    else:
        default_path = '/var/log/nginx'
        if os.path.exists(default_path):
            paths = [default_path]
        else:
            print("No nginx log found at default location, do you have nginx set up?")
            print("If necessary, provide the path to the log file(s) as argument.")
            print("More information with 'rhit --help'.")
            print(f'Error: PathNotFound("{default_path}")')
            sys.exit(0)

    # Collect files
    files = collect_files(paths, args.no_name_check)

    if not files:
        print("No log files found")
        sys.exit(1)

    n_files = len(files)

    # Display path
    if args.files:
        if len(args.files) == 1:
            display_path = str(args.files[0])
        else:
            display_path = str(args.files[0])
    else:
        display_path = '/var/log/nginx'

    # Build filters
    filters = build_filters(args)

    # Parse fields
    fields = parse_fields(args.fields)

    # Collect all entries (need total before filter for filter info)
    # Read without filters to get total
    no_filter_entries = []
    collect_raw = (args.output == 'raw')

    all_entries = []
    all_raw = []

    for i, f in enumerate(files):
        if not args.silent_load:
            print_progress(i, n_files, use_color)

        entries, raw = read_file(f, filters, collect_raw)
        all_entries.extend(entries)
        all_raw.extend(raw)

    if not args.silent_load:
        print_progress(n_files, n_files, use_color)
        sys.stderr.write("\x1b7\x1b[2K\x1b8")
