        sys.stderr.write(f"I've read {n_files} {file_word} in \"{display_path}\"\n")
        return

    if args.output == 'csv':
        w = csv.writer(sys.stdout)
        w.writerow(['date', 'time', 'remote address', 'method', 'path', 'status', 'bytes sent', 'referer'])
        for e in all_entries:
            w.writerow([
                e['date_str'], e['time_str'], e['ip'], e['method'],
                e['path'], str(e['status']), str(e['bytes']), e['referer']
            ])
        sys.stderr.write(f"I've read {n_files} {file_word} in \"{display_path}\"\n")
        return

    if args.output == 'json':
        sys.stdout.write('[\n')
        for i, e in enumerate(all_entries):
            comma = ',' if i < len(all_entries) - 1 else ''
            sys.stdout.write(f'  {{\n')
            sys.stdout.write(f'    "date": "{e["date_str"]}",\n')
            sys.stdout.write(f'    "time": "{e["time_str"]}",\n')
            sys.stdout.write(f'    "remote_addr": "{e["ip"]}",\n')
            sys.stdout.write(f'    "method": "{e["method"]}",\n')
            sys.stdout.write(f'    "path": "{e["path"]}",\n')
            sys.stdout.write(f'    "status": "{e["status"]}",\n')
            sys.stdout.write(f'    "bytes_sent": {e["bytes"]},\n')
            sys.stdout.write(f'    "referer": "{e["referer"]}"\n')
            sys.stdout.write(f'  }}{comma}\n')
        sys.stdout.write(']\n')
        sys.stderr.write(f"I've read {n_files} {file_word} in \"{display_path}\"\n")
        return

    # Tables output
    sys.stderr.write(f"I've read {n_files} {file_word} in \"{display_path}\"\n")

    renderer = TableRenderer(args, use_color)
    renderer.render_all(all_entries, fields, filters, n_files, display_path, 0)


