#!/usr/bin/env python3
"""rhit 2.0.4 - nginx log analyzer"""

import argparse
import gzip
import json
import os
import re
import sys
from collections import defaultdict
from datetime import date, timedelta, time
from pathlib import Path

VERSION = "2.0.4"

MONTHS = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
}

RESOURCE_EXTENSIONS = frozenset([
    'png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'ico',
    'css', 'js', 'woff2', 'map'
])

LOG_PATTERN = re.compile(
    r'^(\S+) \S+ \S+ \[(\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+) [^\]]*\] '
    r'"(\S+) (\S+)[^"]*" (\d+) (\d+|-) "([^"]*)"'
)


def format_bytes(n):
    """Format byte count."""
    if n < 10000:
        return str(n)
    elif n < 1_000_000:
        k = round(n / 1000)
        if k >= 1000:
            m = n / 1_000_000
            if m < 10:
                return f'{m:.1f}M'
            return f'{round(m)}M'
        return f'{k}K'
    elif n < 1_000_000_000:
        m_val = n / 1_000_000
        m_round = round(m_val, 1)
        if m_round >= 1000:
            g = n / 1_000_000_000
            if g < 10:
                return f'{g:.1f}G'
            return f'{round(g)}G'
        if m_round >= 10:
            return f'{round(m_round)}M'
        return f'{m_round:.1f}M'
    else:
        g = n / 1_000_000_000
        g_round = round(g, 1)
        if g_round >= 10:
            return f'{round(g_round)}G'
        return f'{g_round:.1f}G'


def make_bar(value, max_val, width=20):
    """Make a horizontal bar chart."""
    EIGHTHS = [' ', '\u258f', '\u258e', '\u258d', '\u258c', '\u258b', '\u258a', '\u2589', '\u2588']
    if max_val == 0:
        return ' ' * width
    total_eighths = round(value / max_val * width * 8)
    full = total_eighths // 8
    partial = total_eighths % 8
    s = '\u2588' * full
    if partial > 0 and full < width:
        s += EIGHTHS[partial]
    return s.ljust(width)


def make_mini_bar(days_values, num_days):
    """Make a mini histogram bar."""
    BARS = [' ', '\u2581', '\u2582', '\u2583', '\u2584', '\u2585', '\u2586', '\u2587']
    max_val = max(days_values) if days_values else 0
    if max_val == 0:
        return ' ' * num_days
    result = []
    for i in range(num_days):
        v = days_values[i] if i < len(days_values) else 0
        idx = round(v / max_val * 7)
        idx = min(7, max(0, idx))
        result.append(BARS[idx])
    return ''.join(result)


def is_resource_path(path):
    p = path.split('?')[0].split('#')[0]
    dot = p.rfind('.')
    if dot >= 0:
        ext = p[dot+1:].lower()
        return ext in RESOURCE_EXTENSIONS
    return False


def parse_log_line(line):
    m = LOG_PATTERN.match(line)
    if not m:
        return None
    try:
        ip = m.group(1)
        day = int(m.group(2))
        month = MONTHS.get(m.group(3), 0)
        if month == 0:
            return None
        year = int(m.group(4))
        hour = int(m.group(5))
        minute = int(m.group(6))
        second = int(m.group(7))
        method = m.group(8)
        path = m.group(9)
        status = int(m.group(10))
        bs = m.group(11)
        bytes_sent = int(bs) if bs != '-' else 0
        referer = m.group(12)

        d = date(year, month, day)
        t = time(hour, minute, second)

        return {
            'ip': ip,
            'date': d,
            'time': t,
            'method': method,
            'path': path,
            'status': status,
            'bytes': bytes_sent,
            'referer': referer,
            'date_str': f"{year}/{month:02d}/{day:02d}",
            'time_str': f"{hour:02d}:{minute:02d}:{second:02d}",
        }
    except (ValueError, TypeError):
        return None


# ===== FILTERS =====

class StatusFilter:
    def __init__(self, spec):
        self.spec = spec
        self.positive = []
        self.negative = []
        for part in spec.split(','):
            part = part.strip()
            neg = part.startswith('!')
            if neg:
                part = part[1:]
            r = self._parse_range(part)
            (self.negative if neg else self.positive).append(r)

    def _parse_range(self, s):
        s = s.strip()
        if re.match(r'^\d+$', s):
            v = int(s); return (v, v)
        if re.match(r'^[1-9]xx$', s, re.I):
            cls = int(s[0]) * 100; return (cls, cls + 99)
        if re.match(r'^\d+-\d+$', s):
            a, b = s.split('-'); return (int(a), int(b))
        return (0, 0)

    def matches(self, entry):
        status = entry['status']
        for lo, hi in self.negative:
            if lo <= status <= hi:
                return False
        if not self.positive:
            return True
        for lo, hi in self.positive:
            if lo <= status <= hi:
                return True
        return False


class PathFilter:
    def __init__(self, spec):
        self.spec = spec
        self.clauses = []
        for part in spec.split(','):
            part = part.strip()
            if not part:
                continue
            neg = part.startswith('!')
            if neg:
                part = part[1:]
            # Handle complex | & operators by treating as regex
            try:
                r = re.compile(part)
                self.clauses.append((neg, r, None))
            except re.error:
                self.clauses.append((neg, None, part))

    def matches(self, s):
        for neg, regex, plain in self.clauses:
            result = regex.search(s) is not None if regex else ((plain or '') in s)
            if neg:
                result = not result
            if not result:
                return False
        return True


class RefererFilter(PathFilter):
    def matches(self, entry):
        return super().matches(entry['referer'])


class PathFilterEntry(PathFilter):
    def matches(self, entry):
        return super().matches(entry['path'])


class DateFilter:
    def __init__(self, spec):
        self.spec = spec
        s = spec.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]
        self.after = s.startswith('>')
        self.before = s.startswith('<')
        if self.after or self.before:
            s = s[1:]

        # Check for range (two dates separated by -)
        # Pattern: YYYY/... - YYYY/...
        range_re = re.match(
            r'^(\d{4}(?:/\d{1,2}(?:/\d{1,2}(?:T\d{2}:\d{2}(?::\d{2})?)?)?)?)'
            r'-(\d{4}(?:/\d{1,2}(?:/\d{1,2}(?:T\d{2}:\d{2}(?::\d{2})?)?)?)?)$', s)

        if range_re:
            self.d_from = self._parse_start(range_re.group(1))
            self.d_to = self._parse_end(range_re.group(2))
        else:
            self.d_from = self._parse_start(s)
            self.d_to = self._parse_end(s)

    def _parse_start(self, s):
        s = s.split('T')[0]
        parts = s.split('/')
        try:
            y = int(parts[0])
            if len(parts) == 1:
                return date(y, 1, 1)
            mo = int(parts[1])
            if len(parts) == 2:
                return date(y, mo, 1)
            return date(y, mo, int(parts[2]))
        except (ValueError, IndexError):
            return date.min

    def _parse_end(self, s):
        s = s.split('T')[0]
        parts = s.split('/')
        try:
            y = int(parts[0])
            if len(parts) == 1:
                return date(y, 12, 31)
            mo = int(parts[1])
            if len(parts) == 2:
                import calendar
                return date(y, mo, calendar.monthrange(y, mo)[1])
            return date(y, mo, int(parts[2]))
        except (ValueError, IndexError):
            return date.max

    def matches(self, entry):
        d = entry['date']
        if self.after:
            result = d > self.d_from
        elif self.before:
            result = d < self.d_to
        else:
            result = self.d_from <= d <= self.d_to
        return not result if self.negate else result


class TimeFilter:
    def __init__(self, spec):
        s = spec.strip()
        self.after = s.startswith('>')
        self.before = s.startswith('<')
        if self.after or self.before:
            s = s[1:]
        parts = s.split(':')
        h = int(parts[0]) if parts else 0
        m = int(parts[1]) if len(parts) > 1 else 0
        sec = int(parts[2]) if len(parts) > 2 else 0
        self.t = time(h, m, sec)

    def matches(self, entry):
        t = entry['time']
        if self.after:
            return t > self.t
        elif self.before:
            return t < self.t
        return t == self.t


class IpFilter:
    def __init__(self, spec):
        s = spec.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]
        if s.startswith('^'):
            self.prefix = s[1:]
            self.regex = None
            self.exact = None
        elif any(c in s for c in r'.*+?[](){}|\\^$'):
            try:
                self.regex = re.compile(s)
            except:
                self.regex = None
            self.exact = None
            self.prefix = None
        else:
            self.exact = s
            self.regex = None
            self.prefix = None

    def matches(self, entry):
        ip = entry['ip']
        if self.exact is not None:
            result = ip == self.exact
        elif self.prefix is not None:
            result = ip.startswith(self.prefix)
        elif self.regex:
            result = bool(self.regex.search(ip))
        else:
            result = True
        return not result if self.negate else result


class MethodFilter:
    STANDARD = {'GET', 'POST', 'PUT', 'DELETE', 'HEAD', 'OPTIONS', 'PATCH', 'CONNECT', 'TRACE'}

    def __init__(self, spec):
        s = spec.strip()
        self.negate = s.startswith('!')
        if self.negate:
            s = s[1:]
        self.is_other = s.lower() == 'other'
        self.is_none = s.lower() == 'none'
        self.method = s.upper()

    def matches(self, entry):
        m = entry['method']
        if self.is_other:
            result = m not in self.STANDARD
        elif self.is_none:
            result = not m
        else:
            result = m.upper() == self.method
        return not result if self.negate else result


def build_filters(args):
    filters = []
    if args.date:
        filters.append(DateFilter(args.date))
    if getattr(args, 'time_filter', None):
        filters.append(TimeFilter(args.time_filter))
    if args.ip:
        filters.append(IpFilter(args.ip))
    if args.method:
        filters.append(MethodFilter(args.method))
    if args.path:
        filters.append(PathFilterEntry(args.path))
    if args.referer:
        filters.append(RefererFilter(args.referer))
    if args.status:
        filters.append(StatusFilter(args.status))
    return filters


def matches_all(entry, filters):
    for f in filters:
        if not f.matches(entry):
            return False
    return True


# ===== FIELDS =====

def parse_fields(spec):
    DEFAULT = ['date', 'status', 'referer', 'path']
    ALL = ['date', 'time', 'method', 'status', 'ip', 'referer', 'path']
    FIELD_MAP = {
        'date': 'date', 'd': 'date',
        'time': 'time', 't': 'time',
        'method': 'method', 'm': 'method',
        'status': 'status', 's': 'status',
        'ip': 'ip', 'i': 'ip',
        'ref': 'referer', 'referer': 'referer', 'referrer': 'referer', 'r': 'referer',
        'path': 'path', 'p': 'path',
    }

    if spec is None:
        return DEFAULT[:]

    spec = spec.strip()

    # Find first + or - operator
    first_op = -1
    for i, c in enumerate(spec):
        if c in '+-':
            first_op = i
            break

    if first_op == -1:
        if spec.lower() in ('all', 'a'):
            return ALL[:]
        fields = []
        for part in spec.split(','):
            f = FIELD_MAP.get(part.strip().lower())
            if f and f not in fields:
                fields.append(f)
        return fields

    if first_op == 0:
        base = DEFAULT[:]
    else:
        base_spec = spec[:first_op].strip().lower()
        if base_spec in ('all', 'a'):
            base = ALL[:]
        else:
            base = []
            for part in base_spec.split(','):
                f = FIELD_MAP.get(part.strip().lower())
                if f and f not in base:
                    base.append(f)

    rest = spec[first_op:]
    i = 0
    while i < len(rest):
        op = rest[i]
        i += 1
        j = i
        while j < len(rest) and rest[j] not in '+-':
            j += 1
        fname = rest[i:j].strip().lower()
        i = j
        f = FIELD_MAP.get(fname)
        if f:
            if op == '+':
                base = [x for x in base if x != f]
                base.append(f)
            elif op == '-':
                base = [x for x in base if x != f]

    return base


# ===== FILE COLLECTION =====

def collect_files(paths, no_name_check=False):
    files = []
    for path in paths:
        p = Path(path)
        if p.is_file():
            if no_name_check or _is_log_file(p.name):
                files.append(p)
        elif p.is_dir():
            dir_files = sorted(
                f for f in p.iterdir()
                if f.is_file() and (no_name_check or _is_log_file(f.name))
            )
            files.extend(dir_files)
    return files


def _is_log_file(name):
    return name.startswith('access') or ('.log' in name and not name.startswith('.'))


def read_file(path, filters, collect_raw=False):
    entries = []
    raw_lines = []
    try:
        opener = gzip.open if str(path).endswith('.gz') else open
        with opener(path, 'rt', encoding='utf-8', errors='replace') as f:
            for line in f:
                line = line.rstrip('\n\r')
                if not line:
                    continue
                entry = parse_log_line(line)
                if entry is None:
                    continue
                if matches_all(entry, filters):
                    if collect_raw:
                        raw_lines.append(line)
                    entries.append(entry)
    except Exception:
        pass
    return entries, raw_lines


# ===== PROGRESS =====

def print_progress(current, total, use_color):
    width = 40
    filled = current * width // total if total > 0 else 0
    bar = '\u2588' * filled + ' ' * (width - filled)
    sys.stderr.write(f"\x1b7\x1b[2K{current:3} / {total} ")
    if use_color:
        sys.stderr.write(f"\x1b[48;5;5m\x1b[38;5;11m{bar}\x1b[49m\x1b[39m")
    else:
        sys.stderr.write(bar)
    sys.stderr.write("\x1b8")
    sys.stderr.flush()


# ===== DATE RANGE =====

def get_date_range(min_date, max_date):
    dates = []
    d = min_date
    while d <= max_date:
        dates.append(d)
        d += timedelta(days=1)
    return dates


# ===== TREND =====

def compute_trend(days_values, total_per_day):
    """Compute trend arrows."""
    n = len(days_values)
    if n < 4:
        return '     '

    half = n // 2
    total_first = sum(total_per_day[:half])
    total_second = sum(total_per_day[half:])

    if total_first == 0 or total_second == 0:
        return '     '

    first = sum(days_values[:half])
    second = sum(days_values[half:])

    if first == 0 and second == 0:
        return '     '
    if first == 0:
        return '  \u279a  '

    share_first = first / total_first
    share_second = second / total_second
    diff = share_second - share_first

    # Chi-square-like test
    exp_second = first * total_second / total_first
    if exp_second > 0:
        chi2 = (second - exp_second) ** 2 / exp_second
    else:
        chi2 = 0

    abs_diff = abs(diff)

    if diff > 0:
        # Increasing
        if chi2 >= 10 and share_second / share_first >= 3.0:
            return ' \u279a \u279a '
        elif chi2 >= 3.5 or (share_second / share_first >= 2.0 and abs_diff >= 0.1):
            return '  \u279a  '
        else:
            return '     '
    else:
        # Decreasing
        ratio = share_first / share_second if share_second > 0 else float('inf')
        if chi2 >= 10 and ratio >= 3.0:
            return ' \u2198 \u2198 '
        elif chi2 >= 3.5 or (ratio >= 2.0 and abs_diff >= 0.1):
            return '  \u2198  '
        else:
            return '     '


# ===== TABLE RENDERING =====

class Renderer:
    TARGET = 50

    def __init__(self, args, use_color):
        self.args = args
        self.use_color = use_color
        self.key_bytes = args.key.startswith('b')
        rows_map = {0: 10, 1: 50, 2: 100, 3: 150, 4: 200, 5: 250, 6: 300}
        self.max_rows = rows_map.get(args.length, 50)

    def render(self, entries, fields, total_before, filters_active):
        if not entries:
            sys.stdout.write("0 hits and 0 bytes\n")
            return

        total_hits = len(entries)
        total_bytes = sum(e['bytes'] for e in entries)
        min_d = min(e['date'] for e in entries)
        max_d = max(e['date'] for e in entries)

        sys.stdout.write(
            f"{total_hits} hits and {format_bytes(total_bytes)} from "
            f"{min_d.year}/{min_d.month:02d}/{min_d.day:02d} to "
            f"{max_d.year}/{max_d.month:02d}/{max_d.day:02d}\n"
        )

        # Filter summary
        if filters_active and total_before > 0 and total_hits < total_before:
            pct = (total_before - total_hits) / total_before * 100
            # Build filter description
            desc_parts = []
            if self.args.date:
                desc_parts.append(f"date on pattern {self.args.date}")
            if getattr(self.args, 'time_filter', None):
                desc_parts.append(f"time on pattern {self.args.time_filter}")
            if self.args.ip:
                desc_parts.append(f"ip on pattern {self.args.ip}")
            if self.args.method:
                desc_parts.append(f"method on pattern {self.args.method}")
            if self.args.path:
                desc_parts.append(f"path on pattern {self.args.path}")
            if self.args.referer:
                desc_parts.append(f"referer on pattern {self.args.referer}")
            if self.args.status:
                desc_parts.append(f"status on pattern {self.args.status}")

            if desc_parts:
                desc = "Filtering by " + desc_parts[0] + f" removed {pct:.2f}%"
                # Wrap at ~43 chars
                self._write_wrapped(desc, 43)
                sys.stdout.write("\nof total lines\n")
                sys.stdout.write(f" ==> hits: {total_hits}, bytes sent: {format_bytes(total_bytes)}\n")

        dates = get_date_range(min_d, max_d)
        num_days = len(dates)
        date_idx = {d: i for i, d in enumerate(dates)}

        total_per_day = [0] * num_days
        for e in entries:
            i = date_idx.get(e['date'])
            if i is not None:
                total_per_day[i] += 1

        show_hist = num_days >= 4

        for field in fields:
            if field == 'date':
                self._date_table(entries, dates, date_idx, num_days)
            elif field == 'time':
                self._time_table(entries)
            elif field == 'method':
                self._method_table(entries, date_idx, num_days, total_per_day, show_hist)
            elif field == 'status':
                self._status_table(entries, date_idx, num_days, total_per_day, show_hist)
            elif field == 'ip':
                self._ip_table(entries, date_idx, num_days, total_per_day, show_hist)
            elif field == 'referer':
                self._referer_table(entries, date_idx, num_days, total_per_day, show_hist)
            elif field == 'path':
                self._path_table(entries, date_idx, num_days, total_per_day, show_hist)

    def _write_wrapped(self, text, width):
        while len(text) > width:
            pos = text.rfind(' ', 0, width)
            if pos < 0:
                pos = width
            sys.stdout.write(text[:pos] + '\n')
            text = text[pos:].lstrip()
        if text:
            sys.stdout.write(text)

    def _agg(self, entries, key_fn, date_idx, num_days):
        data = {}
        for e in entries:
            k = key_fn(e)
            if k not in data:
                data[k] = [0, 0, [0]*num_days]
            d = data[k]
            d[0] += 1
            d[1] += e['bytes']
            i = date_idx.get(e['date'])
            if i is not None:
                d[2][i] += 1
        return data

    def _sort(self, data):
        items = list(data.items())
        if self.key_bytes:
            items.sort(key=lambda x: (-x[1][1], x[0]))
        else:
            items.sort(key=lambda x: (-x[1][0], x[0]))
        return items

    def _date_table(self, entries, dates, date_idx, num_days):
        hits = [0]*num_days
        bts = [0]*num_days
        for e in entries:
            i = date_idx.get(e['date'])
            if i is not None:
                hits[i] += 1
                bts[i] += e['bytes']

        key_v = bts if self.key_bytes else hits
        max_v = max(key_v) if key_v else 1

        BW = 20
        max_s = format_bytes(max_v)
        inner = f"0{' ' * (BW - 1 - len(max_s))}{max_s}"

        sys.stdout.write(f"\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u252c{'\u2500'*(BW+2)}\u2510\n")
        sys.stdout.write(f"\u2502   date   \u2502hits\u2502bytes\u2502{inner}\u2502\n")
        sys.stdout.write(f"\u251c{'\u2500'*10}\u253c{'\u2500'*4}\u253c{'\u2500'*5}\u253c{'\u2500'*(BW+2)}\u2524\n")
        for i, d in enumerate(dates):
            h = hits[i]
            b = bts[i]
            v = bts[i] if self.key_bytes else hits[i]
            bar = make_bar(v, max_v, BW)
            sys.stdout.write(f"\u2502{d.year}/{d.month:02d}/{d.day:02d}\u2502{h:4}\u2502{format_bytes(b):>5}\u2502{bar}\u2502\n")
        sys.stdout.write(f"\u2514{'\u2500'*10}\u2534{'\u2500'*4}\u2534{'\u2500'*5}\u2534{'\u2500'*(BW+2)}\u2518\n")

    def _time_table(self, entries):
        hits = [0]*24
        bts = [0]*24
        for e in entries:
            h = e['time'].hour
            hits[h] += 1
            bts[h] += e['bytes']

        key_v = bts if self.key_bytes else hits
        max_v = max(key_v) if any(key_v) else 1

        BW = 20
        max_s = format_bytes(max_v)
        inner = f"0{' ' * (BW - 1 - len(max_s))}{max_s}"

        sys.stdout.write(f"\u250c\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u252c\u2500\u2500\u2500\u2500\u2500\u252c{'\u2500'*(BW+2)}\u2510\n")
        sys.stdout.write(f"\u2502hour\u2502hits\u2502bytes\u2502{inner}\u2502\n")
        sys.stdout.write(f"\u251c{'\u2500'*4}\u253c{'\u2500'*4}\u253c{'\u2500'*5}\u253c{'\u2500'*(BW+2)}\u2524\n")
        for h in range(24):
            v = bts[h] if self.key_bytes else hits[h]
            bar = make_bar(v, max_v, BW)
            sys.stdout.write(f"\u2502{h:<4}\u2502{hits[h]:^4}\u2502{format_bytes(bts[h]):>5}\u2502{bar}\u2502\n")
        sys.stdout.write(f"\u2514{'\u2500'*4}\u2534{'\u2500'*4}\u2534{'\u2500'*5}\u2534{'\u2500'*(BW+2)}\u2518\n")

    def _status_table(self, entries, date_idx, num_days, total_per_day, show_hist):
        data = self._agg(entries, lambda e: str(e['status']), date_idx, num_days)
        total_hits = len(entries)
        n = len(data)

        if show_hist:
            if self.key_bytes:
                items = sorted(data.items(), key=lambda x: (-x[1][1], int(x[0])))
            else:
                items = sorted(data.items(), key=lambda x: (-x[1][0], int(x[0])))
        else:
            if self.key_bytes:
                items = sorted(data.items(), key=lambda x: (-x[1][1], int(x[0])))
            else:
                items = sorted(data.items(), key=lambda x: (-x[1][0], int(x[0])))

        if self.args.length == 0:
            self._status_class_table(entries, total_hits)
            return

        if show_hist:
            # Determine % column width
            max_pct = max(v[0]/total_hits*100 for _, v in items) if items else 0
            pct_w = len(f"{max_pct:.1f}%")
            pct_w = max(5, pct_w)

            dw = num_days
            sys.stdout.write("HTTP status codes\n")
            sys.stdout.write(f"\u250c{'\u2500'*6}\u252c{'\u2500'*4}\u252c{'\u2500'*pct_w}\u252c{'\u2500'*5}\u252c{'\u2500'*dw}\u252c{'\u2500'*5}\u2510\n")
            sys.stdout.write(f"\u2502{'status':^6}\u2502{'hits':^4}\u2502{'%':^{pct_w}}\u2502{'bytes':^5}\u2502{'days':^{dw}}\u2502{'trend':^5}\u2502\n")
            sys.stdout.write(f"\u251c{'\u2500'*6}\u253c{'\u2500'*4}\u253c{'\u2500'*pct_w}\u253c{'\u2500'*5}\u253c{'\u2500'*dw}\u253c{'\u2500'*5}\u2524\n")

            for sstr, (h, b, dv) in items:
                pct = h/total_hits*100
                pct_s = f"{pct:.1f}%"
                dbar = make_mini_bar(dv, dw)
                trend = compute_trend(dv, total_per_day)
                sys.stdout.write(f"\u2502 {int(sstr):^4} \u2502{h:>{4}}\u2502{pct_s:>{pct_w}}\u2502{format_bytes(b):>5}\u2502{dbar}\u2502{trend}\u2502\n")

            sys.stdout.write(f"\u2514{'\u2500'*6}\u2534{'\u2500'*4}\u2534{'\u2500'*pct_w}\u2534{'\u2500'*5}\u2534{'\u2500'*dw}\u2534{'\u2500'*5}\u2518\n")
        else:
            sys.stdout.write(f"{n} HTTP status codes.\n")
            # Determine % width
            max_pct = max(v[0]/total_hits*100 for _, v in items) if items else 0
            pct_w = len(f"{max_pct:.1f}%")
            pct_w = max(5, pct_w)

            sys.stdout.write(f"\u250c{'\u2500'*3}\u252c{'\u2500'*6}\u252c{'\u2500'*4}\u252c{'\u2500'*pct_w}\u252c{'\u2500'*5}\u2510\n")
            sys.stdout.write(f"\u2502 # \u2502status\u2502hits\u2502{'%':^{pct_w}}\u2502bytes\u2502\n")
            sys.stdout.write(f"\u251c{'\u2500'*3}\u253c{'\u2500'*6}\u253c{'\u2500'*4}\u253c{'\u2500'*pct_w}\u253c{'\u2500'*5}\u2524\n")

            for i, (sstr, (h, b, _)) in enumerate(items[:self.max_rows]):
                pct = h/total_hits*100
                pct_s = f"{pct:.1f}%"
                sys.stdout.write(f"\u2502{i+1:3}\u2502{sstr:<6}\u2502{h:4}\u2502{pct_s:>{pct_w}}\u2502{format_bytes(b):>5}\u2502\n")

            sys.stdout.write(f"\u2514{'\u2500'*3}\u2534{'\u2500'*6}\u2534{'\u2500'*4}\u2534{'\u2500'*pct_w}\u2534{'\u2500'*5}\u2518\n")

    def _status_class_table(self, entries, total_hits):
        classes = defaultdict(int)
        for e in entries:
            classes[e['status'] // 100] += 1

        cols = []
        for cls in [1, 2, 3, 4, 5]:
            if classes[cls] > 0:
                pct = classes[cls] / total_hits * 100
                cols.append((f"{cls}xx", f"{pct:.1f}%"))

        if not cols:
            return

        sys.stdout.write("HTTP status codes:\n")
        w = 5
        sep = '\u252c'.join(['\u2500'*w]*len(cols))
        sys.stdout.write(f"\u250c{sep}\u2510\n")
        header = '\u2502'.join(f" {h} " for h, _ in cols)
        sys.stdout.write(f"\u2502{header}\u2502\n")
        sep2 = '\u253c'.join(['\u2500'*w]*len(cols))
        sys.stdout.write(f"\u251c{sep2}\u2524\n")
        vals = '\u2502'.join(f"{v:>{w}}" for _, v in cols)
        sys.stdout.write(f"\u2502{vals}\u2502\n")
        sep3 = '\u2534'.join(['\u2500'*w]*len(cols))
        sys.stdout.write(f"\u2514{sep3}\u2518\n")

    def _method_table(self, entries, date_idx, num_days, total_per_day, show_hist):
        data = self._agg(entries, lambda e: e['method'], date_idx, num_days)
        items = self._sort(data)
        total_hits = len(entries)

        max_mw = max((len(k) for k, _ in items), default=6)
        mw = max(6, max_mw)

        sys.stdout.write("methods\n")

        if show_hist:
            dw = num_days
            sys.stdout.write(f"\u250c{'\u2500'*mw}\u252c{'\u2500'*4}\u252c{'\u2500'*5}\u252c{'\u2500'*5}\u252c{'\u2500'*dw}\u252c{'\u2500'*5}\u2510\n")
            sys.stdout.write(f"\u2502{'method':^{mw}}\u2502hits\u2502{'%':^5}\u2502bytes\u2502{'days':^{dw}}\u2502trend\u2502\n")
            sys.stdout.write(f"\u251c{'\u2500'*mw}\u253c{'\u2500'*4}\u253c{'\u2500'*5}\u253c{'\u2500'*5}\u253c{'\u2500'*dw}\u253c{'\u2500'*5}\u2524\n")
            for m, (h, b, dv) in items:
                pct = h/total_hits*100
                dbar = make_mini_bar(dv, dw)
                trend = compute_trend(dv, total_per_day)
                sys.stdout.write(f"\u2502{m:^{mw}}\u2502{h:4}\u2502{pct:.1f}%\u2502{format_bytes(b):>5}\u2502{dbar}\u2502{trend}\u2502\n")
            sys.stdout.write(f"\u2514{'\u2500'*mw}\u2534{'\u2500'*4}\u2534{'\u2500'*5}\u2534{'\u2500'*5}\u2534{'\u2500'*dw}\u2534{'\u2500'*5}\u2518\n")
        else:
            sys.stdout.write(f"\u250c{'\u2500'*mw}\u252c{'\u2500'*4}\u252c{'\u2500'*5}\u252c{'\u2500'*5}\u2510\n")
            sys.stdout.write(f"\u2502{'method':^{mw}}\u2502hits\u2502{'%':^5}\u2502bytes\u2502\n")
            sys.stdout.write(f"\u251c{'\u2500'*mw}\u253c{'\u2500'*4}\u253c{'\u2500'*5}\u253c{'\u2500'*5}\u2524\n")
            for m, (h, b, _) in items:
                pct = h/total_hits*100
                sys.stdout.write(f"\u2502{m:^{mw}}\u2502{h:4}\u2502{pct:.1f}%\u2502{format_bytes(b):>5}\u2502\n")
            sys.stdout.write(f"\u2514{'\u2500'*mw}\u2534{'\u2500'*4}\u2534{'\u2500'*5}\u2534{'\u2500'*5}\u2518\n")

    def _ip_table(self, entries, date_idx, num_days, total_per_day, show_hist):
        data = self._agg(entries, lambda e: e['ip'], date_idx, num_days)
        items = self._sort(data)
        total = len(data)
        total_hits = len(entries)
        show_n = min(total, self.max_rows)

        if total > show_n:
            sys.stdout.write(f"{total} remote IP addresses. {show_n} most frequent:\n")
        else:
            sys.stdout.write(f"{total} remote IP addresses\n")

        if show_hist:
            self._hist_table(items[:show_n], 'IP address', total_hits, num_days, total_per_day)
        else:
            self._pct_table(items[:show_n], 'IP address', total_hits)

    def _referer_table(self, entries, date_idx, num_days, total_per_day, show_hist):
        ref_entries = [e for e in entries if e['referer'] != '-']
        data = self._agg(ref_entries, lambda e: e['referer'], date_idx, num_days)
        items = self._sort(data)
        total = len(data)
        total_hits = len(entries)
        show_n = min(total, self.max_rows)

        if total == 0:
            sys.stdout.write("0 referrers : none\n")
            return

        if show_hist:
            if total > show_n:
                sys.stdout.write(f"{total} referrers. {show_n} most frequent:\n")
            else:
                sys.stdout.write(f"{total} referrers\n")
            self._hist_table(items[:show_n], 'referrer', total_hits, num_days, total_per_day)
        else:
            if total > show_n:
                sys.stdout.write(f"{total} referrers. {show_n} most frequent:\n")
            else:
                sys.stdout.write(f"{total} referrers.\n")
            self._pct_table(items[:show_n], 'referrer', total_hits)

        if self.args.changes and show_hist:
            self._changes_tables(items, 'referrers', 'referrer', total_hits, num_days, total_per_day)

    def _path_table(self, entries, date_idx, num_days, total_per_day, show_hist):
        all_data = self._agg(entries, lambda e: e['path'], date_idx, num_days)

        inc_res = self.args.all
        if not inc_res:
            data = {k: v for k, v in all_data.items() if not is_resource_path(k)}
        else:
            data = all_data

        items = self._sort(data)
        total = len(data)
        total_hits = len(entries)
        show_n = min(total, self.max_rows)

        note = '' if inc_res else ' (excluding resources like images, css, \netc.)'

        if show_hist:
            if total > show_n:
                sys.stdout.write(f"{total} paths{note}. {show_n} most frequent:\n")
            else:
                sys.stdout.write(f"{total} paths{note}\n")
            self._hist_table(items[:show_n], 'path', total_hits, num_days, total_per_day)
        else:
            if total > show_n:
                sys.stdout.write(f"{total} paths{note}. {show_n} most frequent:\n")
            else:
                sys.stdout.write(f"{total} paths{note}.\n")
            self._pct_table(items[:show_n], 'path', total_hits)

        if self.args.changes and show_hist:
            self._changes_tables(items, 'paths', 'path', total_hits, num_days, total_per_day)

    def _changes_tables(self, items, plural, singular, total_hits, num_days, total_per_day):
        half = num_days // 2
        tf = sum(total_per_day[:half])
        ts = sum(total_per_day[half:])

        if tf == 0 or ts == 0:
            return

        more, less = [], []
        for name, (h, b, dv) in items:
            f = sum(dv[:half])
            s = sum(dv[half:])
            if f == 0:
                continue
            sf = f / tf
            ss = s / ts
            diff = ss - sf
            if diff > 0:
                # Check if significant
                exp = f * ts / tf
                chi2 = (s - exp)**2 / exp if exp > 0 else 0
                if chi2 >= 3.5 or (ss/sf >= 2.0 and abs(diff) >= 0.1):
                    more.append((name, (h, b, dv)))
            elif diff < 0:
                exp = f * ts / tf
                chi2 = (s - exp)**2 / exp if exp > 0 else 0
                ratio = sf / ss if ss > 0 else float('inf')
                if chi2 >= 3.5 or (ratio >= 2.0 and abs(diff) >= 0.1):
                    less.append((name, (h, b, dv)))

        if not more:
            sys.stdout.write(f"More popular {plural} : none\n")
        else:
            sys.stdout.write(f"More popular {plural}\n")
            self._hist_table(more, singular, total_hits, num_days, total_per_day)

        if not less:
            sys.stdout.write(f"Less popular {plural} : none\n")
        else:
            sys.stdout.write(f"Less popular {plural}\n")
            self._hist_table(less, singular, total_hits, num_days, total_per_day)

    def _calc_col_width(self, items, col_name, num_days):
        """Calculate optimal content column width."""
        max_content = max((len(k) for k, _ in items), default=len(col_name))
        # Fixed: 3(#) + 4(hits) + 5(bytes) + num_days(days) + 5(trend) + 7(seps)
        fixed = 3 + 4 + 5 + num_days + 5 + 7
        available = self.TARGET - fixed
        col_w = min(max_content, max(len(col_name), available))
        return col_w, max_content

    def _hist_table(self, items, col_name, total_hits, num_days, total_per_day):
        col_w, max_content = self._calc_col_width(items, col_name, num_days)
        dw = num_days

        sys.stdout.write(f"\u250c{'\u2500'*3}\u252c{'\u2500'*col_w}\u252c{'\u2500'*4}\u252c{'\u2500'*5}\u252c{'\u2500'*dw}\u252c{'\u2500'*5}\u2510\n")
        sys.stdout.write(f"\u2502 # \u2502{col_name:<{col_w}}\u2502hits\u2502bytes\u2502{'days':^{dw}}\u2502trend\u2502\n")
        sys.stdout.write(f"\u251c{'\u2500'*3}\u253c{'\u2500'*col_w}\u253c{'\u2500'*4}\u253c{'\u2500'*5}\u253c{'\u2500'*dw}\u253c{'\u2500'*5}\u2524\n")

        for i, (name, (h, b, dv)) in enumerate(items):
            dbar = make_mini_bar(dv, dw)
            trend = compute_trend(dv, total_per_day)

            chunks = _wrap_str(name, col_w)
            for ci, chunk in enumerate(chunks):
                padded = f"{chunk:<{col_w}}"
                if ci == 0:
                    sys.stdout.write(f"\u2502{i+1:3}\u2502{padded}\u2502{h:4}\u2502{format_bytes(b):>5}\u2502{dbar}\u2502{trend}\u2502\n")
                else:
                    # Wrap continuation: days bar also wraps
                    bar_cont = ' ' * dw
                    sys.stdout.write(f"\u2502   \u2502{padded}\u2502    \u2502     \u2502{bar_cont}\u2502     \u2502\n")

        sys.stdout.write(f"\u2514{'\u2500'*3}\u2534{'\u2500'*col_w}\u2534{'\u2500'*4}\u2534{'\u2500'*5}\u2534{'\u2500'*dw}\u2534{'\u2500'*5}\u2518\n")

    def _pct_table(self, items, col_name, total_hits):
        max_content = max((len(k) for k, _ in items), default=len(col_name))
        # Fixed: 3(#) + 4(hits) + 5(%) + 5(bytes) + 7(seps)
        fixed = 3 + 4 + 5 + 5 + 7
        col_w = min(max_content, max(len(col_name), self.TARGET - fixed))

        # Determine % width
        max_pct = max(v[0]/total_hits*100 for _, v in items) if items else 100
        pct_w = max(5, len(f"{max_pct:.1f}%"))

        sys.stdout.write(f"\u250c{'\u2500'*3}\u252c{'\u2500'*col_w}\u252c{'\u2500'*4}\u252c{'\u2500'*pct_w}\u252c{'\u2500'*5}\u2510\n")
        sys.stdout.write(f"\u2502 # \u2502{col_name:<{col_w}}\u2502hits\u2502{'%':^{pct_w}}\u2502bytes\u2502\n")
        sys.stdout.write(f"\u251c{'\u2500'*3}\u253c{'\u2500'*col_w}\u253c{'\u2500'*4}\u253c{'\u2500'*pct_w}\u253c{'\u2500'*5}\u2524\n")

        for i, (name, (h, b, _)) in enumerate(items[:self.max_rows]):
            pct = h/total_hits*100
            pct_s = f"{pct:.1f}%"
            chunks = _wrap_str(name, col_w)
            for ci, chunk in enumerate(chunks):
                padded = f"{chunk:<{col_w}}"
                if ci == 0:
                    sys.stdout.write(f"\u2502{i+1:3}\u2502{padded}\u2502{h:4}\u2502{pct_s:>{pct_w}}\u2502{format_bytes(b):>5}\u2502\n")
                else:
                    sys.stdout.write(f"\u2502   \u2502{padded}\u2502    \u2502{' '*pct_w}\u2502     \u2502\n")

        sys.stdout.write(f"\u2514{'\u2500'*3}\u2534{'\u2500'*col_w}\u2534{'\u2500'*4}\u2534{'\u2500'*pct_w}\u2534{'\u2500'*5}\u2518\n")


def _wrap_str(s, width):
    """Wrap string into chunks of given width."""
    if len(s) <= width:
        return [s]
    chunks = []
    for i in range(0, len(s), width):
        chunks.append(s[i:i+width])
    return chunks


# ===== MAIN =====

def main():
    parser = argparse.ArgumentParser(
        prog='rhit',
        add_help=False,
    )
    parser.add_argument('--help', action='store_true')
    parser.add_argument('--version', action='store_true')
    parser.add_argument('--color', default='auto')
    parser.add_argument('-k', '--key', default='hits')
    parser.add_argument('-l', '--length', type=int, default=1)
    parser.add_argument('-f', '--fields', default=None)
    parser.add_argument('-c', '--changes', action='store_true')
    parser.add_argument('-d', '--date', default=None)
    parser.add_argument('-t', '--time', dest='time_filter', default=None)
    parser.add_argument('-i', '--ip', default=None)
    parser.add_argument('-m', '--method', default=None)
    parser.add_argument('-p', '--path', default=None)
    parser.add_argument('-r', '--referer', default=None)
    parser.add_argument('-s', '--status', default=None)
    parser.add_argument('-a', '--all', action='store_true')
    parser.add_argument('--no-name-check', action='store_true')
    parser.add_argument('-o', '--output', default=None)
    parser.add_argument('--silent-load', action='store_true')
    parser.add_argument('files', nargs='*')

    args = parser.parse_args()

    if args.version:
        print(f"rhit {VERSION}")
        return

    if args.help:
        # Print help similar to the original
        _print_help()
        return

    # Normalize output mode
    output_map = {'t': 'tables', 'r': 'raw', 'c': 'csv', 'j': 'json',
                  'tables': 'tables', 'raw': 'raw', 'csv': 'csv', 'json': 'json'}
    output = output_map.get(args.output or 'tables', 'tables')

    # Color
    if args.color == 'auto':
        use_color = sys.stderr.isatty()
    elif args.color in ('yes', 'y', '1', 'true'):
        use_color = True
    else:
        use_color = False

    # Find files
    if args.files:
        paths = args.files
    else:
        default = '/var/log/nginx'
        if os.path.exists(default):
            paths = [default]
        else:
            print("No nginx log found at default location, do you have nginx set up?")
            print("If necessary, provide the path to the log file(s) as argument.")
            print("More information with 'rhit --help'.")
            print(f'Error: PathNotFound("{default}")')
            return

    files = collect_files(paths, args.no_name_check)
    if not files:
        sys.stderr.write("No log files found\n")
        sys.exit(1)

    n = len(files)
    display_path = str(Path(paths[0]).resolve()) if len(paths) == 1 else str(paths[0])
    # Use the original path as given (not resolved)
    display_path = str(paths[0])

    filters = build_filters(args)
    fields = parse_fields(args.fields)

    collect_raw = (output == 'raw')
    all_entries = []
    all_raw = []

    for i, f in enumerate(files):
        if not args.silent_load:
            print_progress(i, n, use_color)
        entries, raw = read_file(f, filters, collect_raw)
        all_entries.extend(entries)
        all_raw.extend(raw)

    if not args.silent_load:
        print_progress(n, n, use_color)
        sys.stderr.write("\x1b7\x1b[2K\x1b8")
        sys.stderr.flush()

    fw = "file" if n == 1 else "files"

    if output == 'raw':
        for line in all_raw:
            sys.stdout.write(line + '\n')
        sys.stderr.write(f"I've read {n} {fw} in \"{display_path}\"\n")
        return

    if output == 'csv':
        import csv as csvmod
        w = csvmod.writer(sys.stdout)
        w.writerow(['date','time','remote address','method','path','status','bytes sent','referer'])
        for e in all_entries:
