#!/usr/bin/env python3
"""rhit 2.0.4 - nginx log analyzer"""

import argparse
import gzip
import os
import re
import sys
from collections import defaultdict
from datetime import date, timedelta, time
from pathlib import Path

VERSION = "2.0.4"

MONTHS = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
}

RESOURCE_EXTENSIONS = frozenset([
    'png', 'jpg', 'jpeg', 'gif', 'svg', 'webp', 'ico',
    'css', 'js', 'woff2', 'map'
])

LOG_PAT = re.compile(
    r'^(\S+) \S+ \S+ \[(\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+) [^\]]*\] '
    r'"(\S+) (\S+)[^"]*" (\d+) (\d+|-) "([^"]*)"'
)

# Unicode box drawing chars
TL, T, TR = '\u250c', '\u252c', '\u2510'
ML, M,  MR = '\u251c', '\u253c', '\u2524'
BL, B, BR  = '\u2514', '\u2534', '\u2518'
V = '\u2502'
H = '\u2500'

# Block chars for bars
EIGHTHS = [' ', '\u258f', '\u258e', '\u258d', '\u258c', '\u258b', '\u258a', '\u2589', '\u2588']
MINI = [' ', '\u2581', '\u2582', '\u2583', '\u2584', '\u2585', '\u2586', '\u2587']
FULL = '\u2588'

# Trend arrows
UP1 = '  \u279a  '
UP2 = ' \u279a \u279a '
DN1 = '  \u2198  '
DN2 = ' \u2198 \u2198 '
BLANK = '     '


def tb(widths, style='top'):
    """Draw a table border row."""
    if style == 'top':
        c = (TL, T, TR)
    elif style == 'mid':
        c = (ML, M, MR)
    else:
        c = (BL, B, BR)
    return c[0] + c[1].join(H*w for w in widths) + c[2] + '\n'


def tr(*cells):
    """Draw a table data row."""
    return V + V.join(cells) + V + '\n'


def format_bytes(n):
    if n < 10000:
        return str(n)
    elif n < 1_000_000:
        k = round(n / 1000)
        if k >= 1000:
            m = n / 1_000_000
            if m < 10:
                return f'{m:.1f}M'
            return f'{round(m)}M'
        return f'{k}K'
    elif n < 1_000_000_000:
        mv = n / 1_000_000
        mr = round(mv, 1)
        if mr >= 1000:
            g = n / 1_000_000_000
            if g < 10:
                return f'{g:.1f}G'
            return f'{round(g)}G'
        if mr >= 10:
            return f'{round(mr)}M'
        return f'{mr:.1f}M'
    else:
        g = n / 1_000_000_000
        gr = round(g, 1)
        if gr >= 10:
            return f'{round(gr)}G'
        return f'{gr:.1f}G'


def make_bar(value, max_val, width=20):
    if max_val == 0:
        return ' ' * width
    total_eighths = round(value / max_val * width * 8)
    full = total_eighths // 8
    partial = total_eighths % 8
    s = FULL * full
    if partial > 0 and full < width:
        s += EIGHTHS[partial]
    return s.ljust(width)


def make_mini(days_values, n):
    max_v = max(days_values) if days_values else 0
    if max_v == 0:
        return ' ' * n
    res = []
    for i in range(n):
        v = days_values[i] if i < len(days_values) else 0
        idx = min(7, max(0, round(v / max_v * 7)))
        res.append(MINI[idx])
    return ''.join(res)


def is_resource(path):
    p = path.split('?')[0].split('#')[0]
    dot = p.rfind('.')
    if dot >= 0:
        return p[dot+1:].lower() in RESOURCE_EXTENSIONS
    return False


def parse_line(line):
    m = LOG_PAT.match(line)
    if not m:
        return None
    try:
        ip = m.group(1)
        day, mon_s, year = int(m.group(2)), m.group(3), int(m.group(4))
        month = MONTHS.get(mon_s, 0)
        if not month:
            return None
        hour, minute, second = int(m.group(5)), int(m.group(6)), int(m.group(7))
        method = m.group(8)
        path = m.group(9)
        status = int(m.group(10))
        bs = m.group(11)
        bytes_sent = int(bs) if bs != '-' else 0
        referer = m.group(12)
        d = date(year, month, day)
        t = time(hour, minute, second)
        return {
            'ip': ip, 'date': d, 'time': t,
            'method': method, 'path': path,
            'status': status, 'bytes': bytes_sent, 'referer': referer,
            'date_str': f"{year}/{month:02d}/{day:02d}",
            'time_str': f"{hour:02d}:{minute:02d}:{second:02d}",
        }
    except (ValueError, TypeError):
        return None


# ===== FILTERS =====

class StatusFilter:
    def __init__(self, spec):
        self.pos, self.neg = [], []
        for part in spec.split(','):
            p = part.strip()
            neg = p.startswith('!')
            if neg: p = p[1:]
            r = self._range(p)
            (self.neg if neg else self.pos).append(r)

    def _range(self, s):
        if re.match(r'^\d+$', s):
            v = int(s); return (v, v)
        if re.match(r'^[1-9]xx$', s, re.I):
            c = int(s[0])*100; return (c, c+99)
        if '-' in s:
            a, b = s.split('-', 1)
            try: return (int(a), int(b))
            except: pass
        return (0, 0)

    def matches(self, e):
        s = e['status']
        for lo, hi in self.neg:
            if lo <= s <= hi: return False
        if not self.pos: return True
        for lo, hi in self.pos:
            if lo <= s <= hi: return True
        return False


class PathFilter:
    def __init__(self, spec, field='path'):
        self.field = field
        self.clauses = []
        for part in spec.split(','):
            p = part.strip()
            if not p: continue
            neg = p.startswith('!')
            if neg: p = p[1:]
            try:
                r = re.compile(p)
                self.clauses.append((neg, r, None))
            except re.error:
                self.clauses.append((neg, None, p))

    def matches(self, e):
        s = e[self.field]
        for neg, rx, plain in self.clauses:
            result = bool(rx.search(s)) if rx else ((plain or '') in s)
            if neg: result = not result
            if not result: return False
        return True


class DateFilter:
    def __init__(self, spec):
        s = spec.strip()
        self.neg = s.startswith('!')
        if self.neg: s = s[1:]
        self.after = s.startswith('>')
        self.before = s.startswith('<')
        if self.after or self.before: s = s[1:]

        rng = re.match(
            r'^(\d{4}(?:/\d{1,2}(?:/\d{1,2}(?:T[\d:]+)?)?)?)'
            r'-(\d{4}(?:/\d{1,2}(?:/\d{1,2}(?:T[\d:]+)?)?)?)$', s)
        if rng:
            self.f = self._start(rng.group(1))
            self.t = self._end(rng.group(2))
        else:
            self.f = self._start(s)
            self.t = self._end(s)

    def _start(self, s):
        s = s.split('T')[0]
        p = s.split('/')
        try:
            y = int(p[0])
            if len(p) == 1: return date(y, 1, 1)
            mo = int(p[1])
            if len(p) == 2: return date(y, mo, 1)
            return date(y, mo, int(p[2]))
        except: return date.min

    def _end(self, s):
        s = s.split('T')[0]
        p = s.split('/')
        try:
            y = int(p[0])
            if len(p) == 1: return date(y, 12, 31)
            mo = int(p[1])
            if len(p) == 2:
                import calendar
                return date(y, mo, calendar.monthrange(y, mo)[1])
            return date(y, mo, int(p[2]))
        except: return date.max

    def matches(self, e):
        d = e['date']
        if self.after: r = d > self.f
        elif self.before: r = d < self.t
        else: r = self.f <= d <= self.t
        return not r if self.neg else r


class TimeFilter:
    def __init__(self, spec):
        s = spec.strip()
        self.after = s.startswith('>')
        self.before = s.startswith('<')
        if self.after or self.before: s = s[1:]
        p = s.split(':')
        h = int(p[0]) if p else 0
        m = int(p[1]) if len(p) > 1 else 0
        sec = int(p[2]) if len(p) > 2 else 0
        self.t = time(h, m, sec)

    def matches(self, e):
        t = e['time']
        if self.after: return t > self.t
        if self.before: return t < self.t
        return t == self.t


class IpFilter:
    def __init__(self, spec):
        s = spec.strip()
        self.neg = s.startswith('!')
        if self.neg: s = s[1:]
        if s.startswith('^'):
            self.prefix = s[1:]; self.rx = None; self.exact = None
        elif any(c in s for c in r'.*+?[](){}|\\$'):
            try: self.rx = re.compile(s)
            except: self.rx = None
            self.exact = None; self.prefix = None
        else:
            self.exact = s; self.rx = None; self.prefix = None

    def matches(self, e):
        ip = e['ip']
        if self.exact is not None: r = ip == self.exact
        elif self.prefix is not None: r = ip.startswith(self.prefix)
        elif self.rx: r = bool(self.rx.search(ip))
        else: r = True
        return not r if self.neg else r


class MethodFilter:
    STD = {'GET','POST','PUT','DELETE','HEAD','OPTIONS','PATCH','CONNECT','TRACE'}
    def __init__(self, spec):
        s = spec.strip()
        self.neg = s.startswith('!')
        if self.neg: s = s[1:]
        self.other = s.lower() == 'other'
        self.none = s.lower() == 'none'
        self.method = s.upper()
    def matches(self, e):
        m = e['method']
        if self.other: r = m not in self.STD
        elif self.none: r = not m
        else: r = m.upper() == self.method
        return not r if self.neg else r


def build_filters(args):
    f = []
    if args.date: f.append(DateFilter(args.date))
    if getattr(args, 'time_filter', None): f.append(TimeFilter(args.time_filter))
    if args.ip: f.append(IpFilter(args.ip))
    if args.method: f.append(MethodFilter(args.method))
    if args.path: f.append(PathFilter(args.path, 'path'))
    if args.referer: f.append(PathFilter(args.referer, 'referer'))
    if args.status: f.append(StatusFilter(args.status))
    return f


def matches_all(e, filters):
    return all(f.matches(e) for f in filters)


# ===== FIELDS =====

def parse_fields(spec):
    DEFAULT = ['date', 'status', 'referer', 'path']
    ALL = ['date', 'time', 'method', 'status', 'ip', 'referer', 'path']
    FM = {
        'date':'date','d':'date','time':'time','t':'time',
        'method':'method','m':'method','status':'status','s':'status',
        'ip':'ip','i':'ip','ref':'referer','referer':'referer',
        'referrer':'referer','r':'referer','path':'path','p':'path',
    }
    if spec is None: return DEFAULT[:]
    spec = spec.strip()
    op = next((i for i,c in enumerate(spec) if c in '+-'), -1)
    if op == -1:
        if spec.lower() in ('all','a'): return ALL[:]
        r = []
        for p in spec.split(','):
            f = FM.get(p.strip().lower())
            if f and f not in r: r.append(f)
        return r
    if op == 0:
        base = DEFAULT[:]
    else:
        bs = spec[:op].strip().lower()
        if bs in ('all','a'): base = ALL[:]
        else:
            base = []
            for p in bs.split(','):
                f = FM.get(p.strip().lower())
                if f and f not in base: base.append(f)
    rest = spec[op:]
    i = 0
    while i < len(rest):
        o = rest[i]; i += 1
        j = next((k for k in range(i, len(rest)) if rest[k] in '+-'), len(rest))
        fn = rest[i:j].strip().lower(); i = j
        f = FM.get(fn)
        if f:
            if o == '+': base = [x for x in base if x != f]; base.append(f)
            elif o == '-': base = [x for x in base if x != f]
    return base


# ===== FILES =====

def collect_files(paths, no_name=False):
    files = []
    for path in paths:
        p = Path(path)
        if p.is_file():
            if no_name or _is_log(p.name): files.append(p)
        elif p.is_dir():
            files.extend(sorted(
                f for f in p.iterdir()
                if f.is_file() and (no_name or _is_log(f.name))
            ))
    return files


def _is_log(name):
    return name.startswith('access') or ('.log' in name and not name.startswith('.'))


def read_file(path, filters, collect_raw=False):
    entries, raw = [], []
    try:
        opener = gzip.open if str(path).endswith('.gz') else open
        with opener(path, 'rt', encoding='utf-8', errors='replace') as f:
            for line in f:
                line = line.rstrip('\n\r')
                if not line: continue
                e = parse_line(line)
                if e is None: continue
                if matches_all(e, filters):
                    if collect_raw: raw.append(line)
                    entries.append(e)
    except Exception:
        pass
    return entries, raw


# ===== PROGRESS =====

def progress(cur, total, color):
    w = 40
    filled = cur * w // total if total > 0 else 0
    bar = FULL * filled + ' ' * (w - filled)
    sys.stderr.write(f"\x1b7\x1b[2K{cur:3} / {total} ")
    if color:
        sys.stderr.write(f"\x1b[48;5;5m\x1b[38;5;11m{bar}\x1b[49m\x1b[39m")
    else:
        sys.stderr.write(bar)
    sys.stderr.write("\x1b8")
    sys.stderr.flush()


# ===== DATE RANGE =====

def date_range(a, b):
    r = []
    d = a
    while d <= b:
        r.append(d)
        d += timedelta(days=1)
    return r


# ===== TREND =====

def trend(dv, total):
    n = len(dv)
    if n < 4: return BLANK
    half = n // 2
    tf = sum(total[:half])
    ts = sum(total[half:])
    if tf == 0 or ts == 0: return BLANK
    f = sum(dv[:half])
    s = sum(dv[half:])
    if f == 0 and s == 0: return BLANK
    if f == 0: return UP1
    sf = f / tf
    ss = s / ts
    diff = ss - sf
    exp = f * ts / tf
    chi2 = (s - exp)**2 / exp if exp > 0 else 0
    ad = abs(diff)
    if diff > 0:
        ratio = ss / sf
        if chi2 >= 10 and ratio >= 3.0: return UP2
        if chi2 >= 3.5 or (ratio >= 2.0 and ad >= 0.1): return UP1
    else:
        ratio = sf / ss if ss > 0 else 1e9
        if chi2 >= 10 and ratio >= 3.0: return DN2
        if chi2 >= 3.5 or (ratio >= 2.0 and ad >= 0.1): return DN1
    return BLANK


# ===== RENDERER =====

def _chunks(s, w):
    if len(s) <= w: return [s]
    return [s[i:i+w] for i in range(0, len(s), w)]


class Renderer:
    T = 50  # target table width

    def __init__(self, args, color):
        self.args = args
        self.color = color
        self.by_bytes = args.key.startswith('b')
        rm = {0:10,1:50,2:100,3:150,4:200,5:250,6:300}
        self.maxr = rm.get(args.length, 50)

    def render(self, entries, fields, total_before, has_filter):
        if not entries:
            sys.stdout.write("0 hits and 0 bytes\n")
            return

        TH = len(entries)
        TB = sum(e['bytes'] for e in entries)
        mnd = min(e['date'] for e in entries)
        mxd = max(e['date'] for e in entries)

        sys.stdout.write(
            f"{TH} hits and {format_bytes(TB)} from "
            f"{mnd.year}/{mnd.month:02d}/{mnd.day:02d} to "
            f"{mxd.year}/{mxd.month:02d}/{mxd.day:02d}\n"
        )

        if has_filter and total_before > 0 and TH < total_before:
            self._filter_info(TH, TB, total_before)

        dates = date_range(mnd, mxd)
        nd = len(dates)
        didx = {d:i for i,d in enumerate(dates)}

        tpd = [0]*nd
        for e in entries:
            i = didx.get(e['date'])
            if i is not None: tpd[i] += 1

        hist = nd >= 4

        for fld in fields:
            if fld == 'date': self._date(entries, dates, didx, nd)
            elif fld == 'time': self._time(entries)
            elif fld == 'method': self._method(entries, didx, nd, tpd, hist)
            elif fld == 'status': self._status(entries, didx, nd, tpd, hist)
            elif fld == 'ip': self._ip(entries, didx, nd, tpd, hist)
            elif fld == 'referer': self._referer(entries, didx, nd, tpd, hist)
            elif fld == 'path': self._path(entries, didx, nd, tpd, hist)

    def _filter_info(self, TH, TB, total_before):
        pct = (total_before - TH) / total_before * 100
        parts = []
        a = self.args
        if a.date: parts.append(f"date on pattern {a.date}")
        if getattr(a,'time_filter',None): parts.append(f"time on pattern {a.time_filter}")
        if a.ip: parts.append(f"ip on pattern {a.ip}")
        if a.method: parts.append(f"method on pattern {a.method}")
        if a.path: parts.append(f"path on pattern {a.path}")
        if a.referer: parts.append(f"referer on pattern {a.referer}")
        if a.status: parts.append(f"status on pattern {a.status}")
        if parts:
            desc = f"Filtering by {parts[0]} removed {pct:.2f}%"
            self._wrap(desc, 43)
            sys.stdout.write("\nof total lines\n")
            sys.stdout.write(f" ==> hits: {TH}, bytes sent: {format_bytes(TB)}\n")

    def _wrap(self, text, width):
        while len(text) > width:
            pos = text.rfind(' ', 0, width)
            if pos < 0: pos = width
            sys.stdout.write(text[:pos] + '\n')
            text = text[pos:].lstrip()
        if text: sys.stdout.write(text)

    def _agg(self, entries, kfn, didx, nd):
        data = {}
        for e in entries:
            k = kfn(e)
            if k not in data: data[k] = [0,0,[0]*nd]
            d = data[k]
            d[0] += 1; d[1] += e['bytes']
            i = didx.get(e['date'])
            if i is not None: d[2][i] += 1
        return data

    def _sort(self, data):
        items = list(data.items())
        if self.by_bytes:
            items.sort(key=lambda x: (-x[1][1], x[0]))
        else:
            items.sort(key=lambda x: (-x[1][0], x[0]))
        return items

    def _date(self, entries, dates, didx, nd):
        hits = [0]*nd; bts = [0]*nd
        for e in entries:
            i = didx.get(e['date'])
            if i is not None:
                hits[i] += 1; bts[i] += e['bytes']
        kv = bts if self.by_bytes else hits
        mx = max(kv) if kv else 1
        BW = 20
        ms = format_bytes(mx)
        inner = '0' + ' '*(BW-1-len(ms)) + ms
        W = [10, 4, 5, BW+2]
        sys.stdout.write(tb(W,'top'))
        sys.stdout.write(tr('   date   ', 'hits', 'bytes', inner))
        sys.stdout.write(tb(W,'mid'))
        for i, d in enumerate(dates):
            v = bts[i] if self.by_bytes else hits[i]
            bar = make_bar(v, mx, BW)
            sys.stdout.write(tr(
                f"{d.year}/{d.month:02d}/{d.day:02d}",
                f"{hits[i]:4}", f"{format_bytes(bts[i]):>5}", bar
            ))
        sys.stdout.write(tb(W,'bot'))

    def _time(self, entries):
        hits = [0]*24; bts = [0]*24
        for e in entries:
            h = e['time'].hour
            hits[h] += 1; bts[h] += e['bytes']
        kv = bts if self.by_bytes else hits
        mx = max(kv) if any(kv) else 1
        BW = 20
        ms = format_bytes(mx)
        inner = '0' + ' '*(BW-1-len(ms)) + ms
        W = [4, 4, 5, BW+2]
        sys.stdout.write(tb(W,'top'))
        sys.stdout.write(tr('hour', 'hits', 'bytes', inner))
        sys.stdout.write(tb(W,'mid'))
        for h in range(24):
            v = bts[h] if self.by_bytes else hits[h]
            bar = make_bar(v, mx, BW)
            sys.stdout.write(tr(
                f"{h:<4}", f"{hits[h]:^4}", f"{format_bytes(bts[h]):>5}", bar
            ))
        sys.stdout.write(tb(W,'bot'))

    def _status(self, entries, didx, nd, tpd, hist):
        data = self._agg(entries, lambda e: str(e['status']), didx, nd)
        TH = len(entries)
        n = len(data)

        if self.by_bytes:
            items = sorted(data.items(), key=lambda x: (-x[1][1], int(x[0])))
        else:
            items = sorted(data.items(), key=lambda x: (-x[1][0], int(x[0])))

        if self.args.length == 0:
            self._status_cls(entries, TH)
            return

        if hist:
            mx_pct = max(v[0]/TH*100 for _,v in items) if items else 0
            pw = max(5, len(f"{mx_pct:.1f}%"))
            dw = nd
            W = [6, 4, pw, 5, dw, 5]
            sys.stdout.write("HTTP status codes\n")
            sys.stdout.write(tb(W,'top'))
            sys.stdout.write(tr('status', 'hits', f"{'%':^{pw}}", 'bytes', f"{'days':^{dw}}", 'trend'))
            sys.stdout.write(tb(W,'mid'))
            for ss, (h, b, dv) in items:
                ps = f"{h/TH*100:.1f}%"
                db = make_mini(dv, dw)
                tr_ = trend(dv, tpd)
                sys.stdout.write(tr(
                    f" {int(ss):^4} ", f"{h:>{4}}",
                    f"{ps:>{pw}}", f"{format_bytes(b):>5}", db, tr_
                ))
            sys.stdout.write(tb(W,'bot'))
        else:
            pw = max(5, len("100.0%"))
            W = [3, 6, 4, pw, 5]
            sys.stdout.write(f"{n} HTTP status codes.\n")
            sys.stdout.write(tb(W,'top'))
            sys.stdout.write(tr(' # ', 'status', 'hits', f"{'%':^{pw}}", 'bytes'))
            sys.stdout.write(tb(W,'mid'))
            for i, (ss, (h, b, _)) in enumerate(items[:self.maxr]):
                ps = f"{h/TH*100:.1f}%"
                sys.stdout.write(tr(f"{i+1:3}", f"{ss:<6}", f"{h:4}", f"{ps:>{pw}}", f"{format_bytes(b):>5}"))
            sys.stdout.write(tb(W,'bot'))

    def _status_cls(self, entries, TH):
        cls = defaultdict(int)
        for e in entries: cls[e['status']//100] += 1
        cols = []
        for c in [1,2,3,4,5]:
            if cls[c] > 0:
                cols.append((f"{c}xx", f"{cls[c]/TH*100:.1f}%"))
        if not cols: return
        w = 5
        sys.stdout.write("HTTP status codes:\n")
        sys.stdout.write(TL + T.join(H*w for _ in cols) + TR + '\n')
        sys.stdout.write(V + V.join(f" {h} " for h,_ in cols) + V + '\n')
        sys.stdout.write(ML + M.join(H*w for _ in cols) + MR + '\n')
        sys.stdout.write(V + V.join(f"{v:>{w}}" for _,v in cols) + V + '\n')
        sys.stdout.write(BL + B.join(H*w for _ in cols) + BR + '\n')

    def _method(self, entries, didx, nd, tpd, hist):
        data = self._agg(entries, lambda e: e['method'], didx, nd)
        items = self._sort(data)
        TH = len(entries)
        mw = max(max((len(k) for k,_ in items), default=0), 6)
        sys.stdout.write("methods\n")
        if hist:
            dw = nd
            W = [mw, 4, 5, 5, dw, 5]
            sys.stdout.write(tb(W,'top'))
            sys.stdout.write(tr(f"{'method':^{mw}}", 'hits', f"{'%':^5}", 'bytes', f"{'days':^{dw}}", 'trend'))
            sys.stdout.write(tb(W,'mid'))
            for m, (h, b, dv) in items:
                ps = f"{h/TH*100:.1f}%"
                db = make_mini(dv, dw)
                tr_ = trend(dv, tpd)
                sys.stdout.write(tr(f"{m:^{mw}}", f"{h:4}", f"{ps:>5}", f"{format_bytes(b):>5}", db, tr_))
            sys.stdout.write(tb(W,'bot'))
        else:
            W = [mw, 4, 5, 5]
            sys.stdout.write(tb(W,'top'))
            sys.stdout.write(tr(f"{'method':^{mw}}", 'hits', f"{'%':^5}", 'bytes'))
            sys.stdout.write(tb(W,'mid'))
            for m, (h, b, _) in items:
                ps = f"{h/TH*100:.1f}%"
                sys.stdout.write(tr(f"{m:^{mw}}", f"{h:4}", f"{ps:>5}", f"{format_bytes(b):>5}"))
            sys.stdout.write(tb(W,'bot'))

    def _ip(self, entries, didx, nd, tpd, hist):
        data = self._agg(entries, lambda e: e['ip'], didx, nd)
        items = self._sort(data)
        tot = len(data); TH = len(entries)
        sn = min(tot, self.maxr)
        if tot > sn:
            sys.stdout.write(f"{tot} remote IP addresses. {sn} most frequent:\n")
        else:
            sys.stdout.write(f"{tot} remote IP addresses\n")

        if sn == 0: return
        if hist:
            self._hist_tbl(items[:sn], 'IP address', TH, nd, tpd)
        else:
            self._pct_tbl(items[:sn], 'IP address', TH)

    def _referer(self, entries, didx, nd, tpd, hist):
        re_entries = [e for e in entries if e['referer'] != '-']
        data = self._agg(re_entries, lambda e: e['referer'], didx, nd)
        items = self._sort(data)
        tot = len(data); TH = len(entries)
        sn = min(tot, self.maxr)

        if tot == 0:
            sys.stdout.write("0 referrers : none\n")
            return

        if hist:
            if tot > sn:
                sys.stdout.write(f"{tot} referrers. {sn} most frequent:\n")
            else:
                sys.stdout.write(f"{tot} referrers\n")
            self._hist_tbl(items[:sn], 'referrer', TH, nd, tpd)
        else:
            if tot > sn:
                sys.stdout.write(f"{tot} referrers. {sn} most frequent:\n")
            else:
                sys.stdout.write(f"{tot} referrers.\n")
            self._pct_tbl(items[:sn], 'referrer', TH)

        if self.args.changes and hist:
            self._changes(items, 'referrers', 'referrer', TH, nd, tpd)

    def _path(self, entries, didx, nd, tpd, hist):
        all_data = self._agg(entries, lambda e: e['path'], didx, nd)
        inc = self.args.all
        data = all_data if inc else {k:v for k,v in all_data.items() if not is_resource(k)}
        items = self._sort(data)
        tot = len(data); TH = len(entries)
        sn = min(tot, self.maxr)
        note = '' if inc else ' (excluding resources like images, css, \netc.)'

        if hist:
            if tot > sn:
                sys.stdout.write(f"{tot} paths{note}. {sn} most frequent:\n")
            else:
                sys.stdout.write(f"{tot} paths{note}\n")
            self._hist_tbl(items[:sn], 'path', TH, nd, tpd)
        else:
            if tot > sn:
                sys.stdout.write(f"{tot} paths{note}. {sn} most frequent:\n")
            else:
                sys.stdout.write(f"{tot} paths{note}.\n")
            self._pct_tbl(items[:sn], 'path', TH)

        if self.args.changes and hist:
            self._changes(items, 'paths', 'path', TH, nd, tpd)

    def _changes(self, items, plural, singular, TH, nd, tpd):
        half = nd // 2
        tf = sum(tpd[:half]); ts = sum(tpd[half:])
        if tf == 0 or ts == 0:
            sys.stdout.write(f"More popular {plural} : none\n")
            sys.stdout.write(f"Less popular {plural} : none\n")
            return

        more, less = [], []
        for name, (h, b, dv) in items:
            f = sum(dv[:half]); s = sum(dv[half:])
            if f == 0: continue
            sf = f/tf; ss = s/ts
            diff = ss - sf
            exp = f * ts / tf
            chi2 = (s-exp)**2/exp if exp > 0 else 0
            ad = abs(diff)
            if diff > 0:
                rt = ss/sf if sf > 0 else 1e9
                if chi2 >= 3.5 or (rt >= 2.0 and ad >= 0.1):
                    more.append((name,(h,b,dv)))
            elif diff < 0:
                rt = sf/ss if ss > 0 else 1e9
                if chi2 >= 3.5 or (rt >= 2.0 and ad >= 0.1):
                    less.append((name,(h,b,dv)))

        if not more:
            sys.stdout.write(f"More popular {plural} : none\n")
        else:
            sys.stdout.write(f"More popular {plural}\n")
            self._hist_tbl(more, singular, TH, nd, tpd)

        if not less:
            sys.stdout.write(f"Less popular {plural} : none\n")
        else:
            sys.stdout.write(f"Less popular {plural}\n")
            self._hist_tbl(less, singular, TH, nd, tpd)

    def _col_w(self, items, cname, nd):
        mc = max((len(k) for k,_ in items), default=len(cname))
        # fixed = 3(#) + 4(hits) + 5(bytes) + nd(days) + 5(trend) + 7(seps)
        avail = self.T - (3 + 4 + 5 + nd + 5 + 7)
        return min(mc, max(len(cname), avail)), mc

    def _hist_tbl(self, items, cname, TH, nd, tpd):
        cw, mc = self._col_w(items, cname, nd)
        dw = nd
        W = [3, cw, 4, 5, dw, 5]
        sys.stdout.write(tb(W,'top'))
        sys.stdout.write(tr(' # ', f"{cname:<{cw}}", 'hits', 'bytes', f"{'days':^{dw}}", 'trend'))
        sys.stdout.write(tb(W,'mid'))
        for i, (name, (h, b, dv)) in enumerate(items):
            db = make_mini(dv, dw)
            tr_ = trend(dv, tpd)
            chunks = _chunks(name, cw)
            for ci, chunk in enumerate(chunks):
                pad = f"{chunk:<{cw}}"
                if ci == 0:
                    sys.stdout.write(tr(f"{i+1:3}", pad, f"{h:4}", f"{format_bytes(b):>5}", db, tr_))
                else:
                    sys.stdout.write(tr('   ', pad, '    ', '     ', ' '*dw, '     '))
        sys.stdout.write(tb(W,'bot'))

    def _pct_tbl(self, items, cname, TH):
        mc = max((len(k) for k,_ in items), default=len(cname))
        # fixed = 3(#) + 4(hits) + 5(%) + 5(bytes) + 7(seps)
        avail = self.T - (3 + 4 + 5 + 5 + 7)
        cw = min(mc, max(len(cname), avail))

        mx_pct = max(v[0]/TH*100 for _,v in items) if items else 100
        pw = max(5, len(f"{mx_pct:.1f}%"))

        W = [3, cw, 4, pw, 5]
        sys.stdout.write(tb(W,'top'))
        sys.stdout.write(tr(' # ', f"{cname:<{cw}}", 'hits', f"{'%':^{pw}}", 'bytes'))
        sys.stdout.write(tb(W,'mid'))
        for i, (name, (h, b, _)) in enumerate(items[:self.maxr]):
            ps = f"{h/TH*100:.1f}%"
            chunks = _chunks(name, cw)
            for ci, chunk in enumerate(chunks):
                pad = f"{chunk:<{cw}}"
                if ci == 0:
                    sys.stdout.write(tr(f"{i+1:3}", pad, f"{h:4}", f"{ps:>{pw}}", f"{format_bytes(b):>5}"))
                else:
                    sys.stdout.write(tr('   ', pad, '    ', ' '*pw, '     '))
        sys.stdout.write(tb(W,'bot'))


# ===== MAIN =====

def main():
    p = argparse.ArgumentParser(prog='rhit', add_help=False)
    p.add_argument('--help', action='store_true')
    p.add_argument('--version', action='store_true')
    p.add_argument('--color', default='auto')
    p.add_argument('-k', '--key', default='hits')
    p.add_argument('-l', '--length', type=int, default=1)
