        sys.stderr.write(f"I've read {n} {fw} in \"{dp}\"\n")
        return

    sys.stderr.write(f"I've read {n} {fw} in \"{dp}\"\n")
    R = Renderer(args, color)
    R.render(all_e, fields, 0, bool(filters))


def _help():
